uint32_t str_hash(const char *s, size_t len) {
  uint64_t h = 0xcbf29ce484222325ULL ^ len;
  size_t i = 0;
  while (i + 8 <= len) {
    uint64_t v; memcpy(&v, s + i, 8);
    h ^= v; h *= 0x100000001b3ULL; h ^= h >> 29;
    i += 8;
  }
  while (i < len) { h ^= (unsigned char)s[i++]; h *= 0x100000001b3ULL; }
  h ^= h >> 32;
  return (uint32_t)h;
}

void str_resize(uint32_t newsize) {
  GCstr **newhash = (GCstr **)calloc(newsize, sizeof(GCstr *));
  uint32_t i;
  for (i = 0; i <= G.strmask && G.strhash; i++) {
    GCstr *p = G.strhash[i];
    while (p) {
      GCstr *next = p->hnext;
      uint32_t h = p->hash & (newsize - 1);
      p->hnext = newhash[h];
      newhash[h] = p;
      p = next;
    }
  }
  free(G.strhash);
  G.strhash = newhash;
  G.strmask = newsize - 1;
}

GCstr *str_new(const char *s, size_t len) {
  uint32_t h = str_hash(s, len);
  GCstr *p;
  if (!G.strhash) str_resize(1024);
  for (p = G.strhash[h & G.strmask]; p; p = p->hnext) {
    if (p->hash == h && p->len == len && memcmp(p->data, s, len) == 0) {
      if (p->marked == 2) p->marked = 0; /* resurrect if being swept (not used) */
      return p;
    }
  }
  if (G.strcount >= G.strmask) str_resize((G.strmask + 1) * 2);
  p = (GCstr *)mem_alloc(sizeof(GCstr) + len);
  p->gct = T_STRING; p->marked = 0; p->reserved = 0;
  p->hash = h; p->len = (uint32_t)len;
  memcpy(p->data, s, len); p->data[len] = '\0';
  p->hnext = G.strhash[h & G.strmask];
  G.strhash[h & G.strmask] = p;
  G.strcount++;
  return p;
}

GCstr *str_newz(const char *s) { return str_new(s, strlen(s)); }

void str_free(GCstr *s) {
  mem_free(s, sizeof(GCstr) + s->len);
}

GCstr *str_fmt(const char *fmt, ...) {
  char buf[512];
  va_list ap;
  va_start(ap, fmt);
  int n = vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  if (n < (int)sizeof(buf)) return str_new(buf, n);
  char *big = (char *)malloc(n + 1);
  va_start(ap, fmt);
  vsnprintf(big, n + 1, fmt, ap);
  va_end(ap);
  GCstr *r = str_new(big, n);
  free(big);
  return r;
}

int str_cmp(const GCstr *a, const GCstr *b) {
  /* strcoll-like comparison with embedded zeros, like Lua's l_strcmp (C locale => memcmp semantics) */
  size_t la = a->len, lb = b->len;
  size_t n = la < lb ? la : lb;
  int r = memcmp(a->data, b->data, n);
  if (r != 0) return r;
  if (la < lb) return -1;
  if (la > lb) return 1;
  return 0;
}

/* ---- number formatting ---- */
