  if (isnan(n)) { memcpy(buf, "nan", 4); return 3; }
  if (isinf(n)) { if (n > 0) { memcpy(buf, "inf", 4); return 3; } memcpy(buf, "-inf", 5); return 4; }
  return sprintf(buf, "%.14g", n);
}

