static int lstrncasecmp(const char *a, const char *b, size_t n) {
  size_t i;
  for (i = 0; i < n; i++) {
    int ca = tolower((unsigned char)a[i]), cb = tolower((unsigned char)b[i]);
    if (ca != cb) return ca - cb;
    if (!ca) return 0;
  }
  return 0;
}

/* Builtin string -> number conversion (LuaJIT-like semantics). */
int str2num(const char *s, size_t len, double *out) {
  const char *p = s, *e = s + len;
  int neg = 0;
  if (memchr(s, 0, len)) return 0;
  while (p < e && isspace((unsigned char)*p)) p++;
  while (e > p && isspace((unsigned char)e[-1])) e--;
  if (p >= e) return 0;
  if (*p == '-') { neg = 1; p++; } else if (*p == '+') p++;
  if (p >= e) return 0;
