#include "lua.h"

const TValue nilvalue = { { .gc = NULL }, T_NIL };
static Node dummynode_ = { { { .gc = NULL }, T_NIL }, { { .gc = NULL }, T_NIL }, NULL };
#define dummynode (&dummynode_)
#define sizenode(t) (1u << (t)->lsizenode)
#define isdummy(t) ((t)->node == dummynode)

static inline uint32_t hash_u64(uint64_t x) {
  x ^= x >> 33; x *= 0xff51afd7ed558ccdULL; x ^= x >> 33; x *= 0xc4ceb9fe1a85ec53ULL; x ^= x >> 33;
  return (uint32_t)x;
}

static Node *mainposition(const Table *t, const TValue *key) {
  uint32_t h;
  switch (key->tt) {
  case T_NUMBER: {
    double n = numV(key);
    if (n == 0) n = 0; /* normalize -0 */
    { uint64_t bits; memcpy(&bits, &n, 8); h = hash_u64(bits); }
    break;
  }
  case T_STRING: h = strV(key)->hash; break;
  case T_BOOLEAN: h = (uint32_t)boolV(key); break;
  default: h = hash_u64((uint64_t)(uintptr_t)key->u.p); break;
  }
  return &t->node[h & (sizenode(t) - 1)];
}

/* Returns integer index if key is a number with integer value fitting int64 */
static inline int num2intkey(double n, int64_t *k) {
  if (n >= -9.2233720368547758e18 && n < 9.2233720368547758e18) {
    int64_t i = (int64_t)n;
    if ((double)i == n) { *k = i; return 1; }
  }
  return 0;
}

