static void setnodevector(Table *t, uint32_t size) {
  uint32_t lsize = 0;
  if (size == 0) { t->node = dummynode; t->lsizenode = 0; t->lastfree = dummynode; return; }
  while ((1u << lsize) < size) lsize++;
