#include "lua.h"

GlobalState G;

void *mem_alloc(size_t sz) {
  void *p = malloc(sz);
  if (!p) { fprintf(stderr, "not enough memory\n"); exit(1); }
  G.totalbytes += sz;
  return p;
}

void *mem_realloc(void *p, size_t oldsz, size_t newsz) {
  void *np = realloc(p, newsz);
  if (!np && newsz) { fprintf(stderr, "not enough memory\n"); exit(1); }
  G.totalbytes = G.totalbytes - oldsz + newsz;
  return np;
}

void mem_free(void *p, size_t sz) {
  free(p);
  G.totalbytes -= sz;
}

void gc_link(GCobj *o, uint8_t gct) {
  o->gct = gct;
  o->marked = 0;
  o->gcnext = G.allgc;
  G.allgc = o;
}

void gc_init(void) {
  G.gcthreshold = 4 * 1024 * 1024;
}

/* ---- marking ---- */
static GCobj **gray; static size_t ngray, graycap;
static Table **weaklist; static size_t nweak, weakcap;

static void gray_push(GCobj *o) {
  if (ngray == graycap) { graycap = graycap ? graycap * 2 : 1024; gray = (GCobj **)realloc(gray, graycap * sizeof(GCobj *)); }
  gray[ngray++] = o;
}

static inline void markobj(GCobj *o) {
  if (o == NULL || o->marked) return;
  o->marked = 1;
  if (o->gct == T_STRING) return;
  gray_push(o);
}

static inline void markvalue(const TValue *v) {
  if (iscollectable(v) && v->u.gc) markobj(v->u.gc);
}

static void mark_table(Table *t) {
  int weakk = 0, weakv = 0;
  if (t->metatable) {
    markobj((GCobj *)t->metatable);
    const TValue *mode = tab_getstr(t->metatable, G.mmnames[MM_MODE]);
    if (ttisstring(mode)) {
      const char *s = str_data(strV(mode));
      if (strchr(s, 'k')) weakk = 1;
      if (strchr(s, 'v')) weakv = 1;
    }
  }
  if (weakk || weakv) {
    if (nweak == weakcap) { weakcap = weakcap ? weakcap * 2 : 64; weaklist = (Table **)realloc(weaklist, weakcap * sizeof(Table *)); }
    weaklist[nweak++] = t;
    t->flags |= 0x80;
  }
  uint32_t i;
  if (!weakv) for (i = 0; i < t->asize; i++) markvalue(&t->array[i]);
  else for (i = 0; i < t->asize; i++) if (ttisstring(&t->array[i])) markvalue(&t->array[i]);
  uint32_t ns = t->node == NULL ? 0 : (1u << t->lsizenode);
  if (t->node && ttisnil(&t->node[0].key) && ns == 1 && t->lastfree == t->node) {
    /* could be dummy node; check by seeing if it's static: handled by asize/lsizenode flag - safe to iterate anyway */
  }
  for (i = 0; i < ns; i++) {
    Node *n = &t->node[i];
    if (ttisnil(&n->val)) continue;
    if (!weakk || ttisstring(&n->key)) markvalue(&n->key);
    if (!weakv || ttisstring(&n->val)) markvalue(&n->val);
  }
}

static void mark_proto(Proto *p) {
  int i;
  markobj((GCobj *)p->source);
  for (i = 0; i < p->nconsts; i++) markobj((GCobj *)p->consts[i]);
  for (i = 0; i < p->nchildren; i++) markobj((GCobj *)p->children[i]);
}

static void mark_thread(lua_State *L) {
  TValue *o;
  for (o = L->stack; o < L->top; o++) markvalue(o);
  if (L->env) markobj((GCobj *)L->env);
  if (L->cofunc) markobj((GCobj *)L->cofunc);
  markvalue(&L->errval);
  for (UpVal *uv = L->openupval; uv; uv = uv->nextopen) markobj((GCobj *)uv);
  /* clear dead part of stack */
  if (L->stack) for (o = L->top; o < L->top + 64 && o < L->stacklast; o++) setnilV(o);
}

static void propagate(void) {
  while (ngray) {
    GCobj *o = gray[--ngray];
    switch (o->gct) {
    case T_TABLE: mark_table((Table *)o); break;
    case T_FUNCTION: {
      Closure *c = (Closure *)o;
      if (c->env) markobj((GCobj *)c->env);
      if (c->isC) { for (int i = 0; i < c->nupvals; i++) markvalue(&c->u.c.upvals[i]); }
      else {
        markobj((GCobj *)c->u.l.p);
        for (int i = 0; i < c->nupvals; i++) if (c->u.l.upvals[i]) markobj((GCobj *)c->u.l.upvals[i]);
      }
      break;
    }
    case T_UPVAL: markvalue(((UpVal *)o)->v); break;
    case T_PROTO: mark_proto((Proto *)o); break;
    case T_USERDATA: {
      Udata *u = (Udata *)o;
      if (u->metatable) markobj((GCobj *)u->metatable);
      if (u->env) markobj((GCobj *)u->env);
      break;
    }
    case T_THREAD: mark_thread((lua_State *)o); break;
    default: break;
    }
  }
