static int isdead(const TValue *v) {
  if (!iscollectable(v) || v->u.gc == NULL) return 0;
  if (v->tt == T_STRING) return 0;
  return !v->u.gc->marked;
}

static void clear_weak(void) {
  for (size_t w = 0; w < nweak; w++) {
    Table *t = weaklist[w];
    uint32_t i;
    t->flags &= ~0x80;
    for (i = 0; i < t->asize; i++) if (isdead(&t->array[i])) setnilV(&t->array[i]);
    uint32_t ns = (1u << t->lsizenode);
    if (t->lastfree == t->node && ttisnil(&t->node[0].key) && ns == 1) { /* dummy check skipped */ }
    for (i = 0; i < ns; i++) {
      Node *n = &t->node[i];
      if (ttisnil(&n->val)) continue;
      if (isdead(&n->key) || isdead(&n->val)) setnilV(&n->val);
    }
  }
  nweak = 0;
}

static void free_obj(GCobj *o) {
  switch (o->gct) {
  case T_TABLE: tab_free((Table *)o); break;
  case T_FUNCTION: {
    Closure *c = (Closure *)o;
    if (c->isC) mem_free(c, sizeof(Closure) + sizeof(TValue) * c->nupvals);
    else mem_free(c, sizeof(Closure) + sizeof(UpVal *) * c->nupvals);
    break;
