#ifndef LEX_H
#define LEX_H
#include "lua.h"

enum {
  TK_and = 257, TK_break, TK_do, TK_else, TK_elseif, TK_end, TK_false, TK_for,
  TK_function, TK_goto_unused, TK_if, TK_in, TK_local, TK_nil, TK_not, TK_or,
