  TK_concat, TK_dots, TK_eq, TK_ge, TK_le, TK_ne, TK_label, TK_number, TK_name, TK_string, TK_eof
};
#define NUM_RESERVED (TK_while - 257 + 1)

typedef struct Token {
  int tok;
  double num;
  GCstr *str;
} Token;

typedef struct LexState {
  lua_State *L;
  const char *p, *pe;
  int c;              /* current char or -1 */
  int line;
  int lastline;
  Token t, ahead;
  int hasahead;
  GCstr *chunkname;
  SBuf sb;
  Proto *curproto;    /* for registering constants */
  struct FuncState *fs;
  int level;
} LexState;

