#include "lex.h"
#include <stdarg.h>
#include <ctype.h>

static const char *const tokennames[] = {
  "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
  "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return", "then",
  "true", "until", "while",
  "..", "...", "==", ">=", "<=", "~=", "::", "<number>", "<name>", "<string>", "<eof>", NULL
};

static GCstr *keyword_strs[NUM_RESERVED];

void lex_init_keywords(void) {
  for (int i = 0; i < NUM_RESERVED; i++) {
    GCstr *s = str_newz(tokennames[i]);
    s->reserved = (uint8_t)(i + 1);
    keyword_strs[i] = s;
  }
  /* goto is not reserved */
  keyword_strs[TK_goto_unused - 257]->reserved = 0;
}

#define END (-1)
#define iscont(c) ((c) == '\r' || (c) == '\n')

static inline int nextc(LexState *ls) {
  if (ls->p < ls->pe) { ls->c = (unsigned char)*ls->p++; }
  else ls->c = END;
  return ls->c;
}
#define save(ls, c) sbuf_putc(&(ls)->sb, (char)(c))
#define savenext(ls) (save(ls, (ls)->c), nextc(ls))

void lex_setup(LexState *ls, lua_State *L, const char *src, size_t len, GCstr *chunkname) {
  ls->L = L; ls->p = src; ls->pe = src + len; ls->line = 1; ls->lastline = 1;
  ls->hasahead = 0; ls->chunkname = chunkname; ls->level = 0; ls->fs = NULL;
  sbuf_init(&ls->sb);
  nextc(ls);
  /* skip UTF-8 BOM */
  if (ls->c == 0xef && ls->pe - ls->p >= 2 && (unsigned char)ls->p[0] == 0xbb && (unsigned char)ls->p[1] == 0xbf) {
    ls->p += 2; nextc(ls);
  }
  if (ls->c == '#') {
    while (ls->c != END && !iscont(ls->c)) nextc(ls);
  }
}

void lex_free(LexState *ls) { sbuf_free(&ls->sb); }

const char *lex_token2str(LexState *ls, int tok) {
  static char buf[64];
  if (tok > 255) {
    if (tok == TK_number || tok == TK_name || tok == TK_string) {
      sbuf_putc(&ls->sb, '\0'); ls->sb.n--;
      return ls->sb.b ? ls->sb.b : "";
