#define _GNU_SOURCE
#include "lua.h"
#include <stdarg.h>
#include <ucontext.h>
#include <sys/mman.h>

const char *const type_names[] = {
  "nil", "boolean", "userdata", "number", "string", "table", "function", "userdata", "thread", "proto", "upval"
};
const char *const mm_names[] = {
  "__index", "__newindex", "__gc", "__mode", "__eq", "__len", "__lt", "__le", "__concat",
  "__call", "__add", "__sub", "__mul", "__div", "__mod", "__pow", "__unm", "__metatable",
  "__tostring", "__pairs", "__ipairs"
};

const char *typename_of(const TValue *o) { return type_names[o->tt]; }

#define STACKSLOTS (LUAI_MAXSTACK + STACK_EXTRA)
#define MAXCI 70000

/* ---- stack / thread management ---- */
static void *map_anon(size_t sz) {
  void *p = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
  if (p == MAP_FAILED) { fprintf(stderr, "not enough memory\n"); exit(1); }
  return p;
}

static void thread_init_stack(lua_State *L) {
  size_t sz = sizeof(TValue) * STACKSLOTS + sizeof(CallInfo) * MAXCI;
  char *mem = (char *)map_anon(sz);
  L->stack = (TValue *)mem;
  L->stacksize = STACKSLOTS;
  L->stacklast = L->stack + STACKSLOTS;
  L->top = L->stack;
  L->cibase = (CallInfo *)(mem + sizeof(TValue) * STACKSLOTS);
  L->ciend = L->cibase + MAXCI;
  L->ci = L->cibase;
  memset(L->ci, 0, sizeof(CallInfo));
  L->ci->func = L->stack; L->ci->base = L->stack + 1; L->ci->isC = 1; L->ci->ismain = 1;
  setnilV(L->top++);  /* dummy function slot for base frame */
}

lua_State *thread_new(lua_State *parent, int iscoroutine) {
  lua_State *L = (lua_State *)mem_alloc(sizeof(lua_State));
  memset(L, 0, sizeof(lua_State));
  if (parent) gc_link((GCobj *)L, T_THREAD); else { L->gct = T_THREAD; }
  thread_init_stack(L);
  L->env = parent ? parent->env : NULL;
  L->status = CO_SUSPENDED;
  setnilV(&L->errval);
  (void)iscoroutine;
  G.totalbytes += 32768;  /* nominal accounting to trigger GC on many coroutines */
  return L;
}

void co_free_cstack(lua_State *L);
void thread_free(lua_State *L) {
  co_free_cstack(L);
  if (L->stack) munmap(L->stack, sizeof(TValue) * STACKSLOTS + sizeof(CallInfo) * MAXCI);
  G.totalbytes -= 32768;
  mem_free(L, sizeof(lua_State));
}

static inline void checkstack(lua_State *L, int n) {
  if (L->top + n >= L->stack + LUAI_MAXSTACK) {
    err_run(L, "stack overflow");
  }
}
void err_check_stack(lua_State *L, int n) { checkstack(L, n); }

void vm_settop(lua_State *L, TValue *top) { L->top = top; }
void vm_push(lua_State *L, const TValue *v) { copyTV(L->top, v); L->top++; }
void vm_pushnum(lua_State *L, double n) { setnumV(L->top, n); L->top++; }
void vm_pushbool(lua_State *L, int b) { setboolV(L->top, b); L->top++; }
void vm_pushnil(lua_State *L) { setnilV(L->top); L->top++; }
void vm_pushtab(lua_State *L, Table *t) { settabV(L->top, t); L->top++; }
void vm_pushfunc(lua_State *L, Closure *c) { setfuncV(L->top, c); L->top++; }
void vm_pushstr(lua_State *L, GCstr *s) { setstrV(L->top, s); L->top++; }
void vm_pushlstring(lua_State *L, const char *s, size_t len) { vm_pushstr(L, str_new(s, len)); }
void vm_pushstring(lua_State *L, const char *s) { vm_pushstr(L, str_newz(s)); }
void vm_pushfstring(lua_State *L, const char *fmt, ...) {
  char buf[1024]; va_list ap;
  va_start(ap, fmt); int n = vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  if (n < (int)sizeof(buf)) { vm_pushlstring(L, buf, n); return; }
  char *big = (char *)malloc(n + 1);
  va_start(ap, fmt); vsnprintf(big, n + 1, fmt, ap); va_end(ap);
  vm_pushlstring(L, big, n); free(big);
}

/* ---- objects ---- */
Proto *proto_new(void) {
  Proto *p = (Proto *)mem_alloc(sizeof(Proto));
  memset(p, 0, sizeof(Proto));
  gc_link((GCobj *)p, T_PROTO);
  return p;
}
void *proto_alloc(Proto *p, size_t sz) {
  void *m = malloc(sz);
  if (p->nallocs == p->alloccap) { p->alloccap = p->alloccap ? p->alloccap * 2 : 64; p->allocs = (void **)realloc(p->allocs, p->alloccap * sizeof(void *)); }
  p->allocs[p->nallocs++] = m;
  G.totalbytes += sz;
  return m;
}
void proto_addconst(Proto *p, GCstr *s) {
  if (p->nconsts == p->constcap) { p->constcap = p->constcap ? p->constcap * 2 : 16; p->consts = (GCstr **)realloc(p->consts, p->constcap * sizeof(GCstr *)); }
  p->consts[p->nconsts++] = s;
}
void proto_free(Proto *p) {
  for (int i = 0; i < p->nallocs; i++) free(p->allocs[i]);
  free(p->allocs); free(p->consts); free(p->children); free(p->upvals); free(p->paramnames);
  mem_free(p, sizeof(Proto));
}

Closure *func_newL(Proto *p, Table *env) {
  Closure *c = (Closure *)mem_alloc(sizeof(Closure) + sizeof(UpVal *) * p->nupvals);
  c->isC = 0; c->nupvals = p->nupvals; c->env = env;
  c->u.l.p = p; c->u.l.upvals = (UpVal **)(c + 1);
  for (int i = 0; i < p->nupvals; i++) c->u.l.upvals[i] = NULL;
  gc_link((GCobj *)c, T_FUNCTION);
  return c;
}
Closure *func_newC(CFunction f, int nupvals, Table *env) {
  Closure *c = (Closure *)mem_alloc(sizeof(Closure) + sizeof(TValue) * nupvals);
  c->isC = 1; c->nupvals = nupvals; c->env = env;
  c->u.c.f = f; c->u.c.name = NULL; c->u.c.builtin = 0; c->u.c.upvals = (TValue *)(c + 1);
  for (int i = 0; i < nupvals; i++) setnilV(&c->u.c.upvals[i]);
  gc_link((GCobj *)c, T_FUNCTION);
  return c;
}
Udata *udata_new(size_t sz, Table *env) {
  Udata *u = (Udata *)mem_alloc(sizeof(Udata) + sz);
  u->metatable = NULL; u->env = env; u->len = sz; u->payload = (void *)(u + 1); u->has_gc = 0;
  memset(u->payload, 0, sz);
  gc_link((GCobj *)u, T_USERDATA);
  return u;
}

UpVal *func_findupval(lua_State *L, TValue *level) {
  UpVal **pp = &L->openupval, *p;
  while ((p = *pp) != NULL && p->v >= level) {
    if (p->v == level) return p;
    pp = &p->nextopen;
  }
  UpVal *uv = (UpVal *)mem_alloc(sizeof(UpVal));
  uv->v = level; setnilV(&uv->closed); uv->level = 0;
  uv->nextopen = *pp; *pp = uv;
  gc_link((GCobj *)uv, T_UPVAL);
  return uv;
}
void func_closeupvals(lua_State *L, TValue *level) {
  UpVal *uv;
  while ((uv = L->openupval) != NULL && uv->v >= level) {
    L->openupval = uv->nextopen;
    copyTV(&uv->closed, uv->v);
    uv->v = &uv->closed;
  }
}

/* ---- errors ---- */
void vm_throw(lua_State *L, int status) {
  if (L->errjmp) {
    L->errjmp->status = status;
    longjmp(L->errjmp->jb, 1);
  }
  /* no handler: print and exit */
  {
    GCstr *s = vm_tostring_basic(L->top - 1);
    fprintf(stderr, "PANIC: unprotected error in call to Lua API (%s)\n", str_data(s));
    exit(1);
  }
}

void vm_error(lua_State *L) { vm_throw(L, LUA_ERRRUN); }

GCstr *vm_shortsrc(GCstr *source) {
  const char *s = str_data(source);
  char buf[128];
  if (s[0] == '=') { snprintf(buf, 60, "%s", s + 1); return str_newz(buf); }
  if (s[0] == '@') {
    size_t len = source->len - 1;
    if (len <= 59) return str_new(s + 1, len);
    snprintf(buf, sizeof(buf), "...%s", s + 1 + (len - 56));
    return str_newz(buf);
  }
  /* string chunk: [string "..."] */
  {
    const char *nl = strchr(s, '\n');
    size_t len = nl ? (size_t)(nl - s) : source->len;
    if (len > 60 - 15 || nl) {
      size_t take = len;
      if (take > 60 - 15) take = 60 - 15;
      snprintf(buf, sizeof(buf), "[string \"%.*s...\"]", (int)take, s);
    } else snprintf(buf, sizeof(buf), "[string \"%s\"]", s);
    return str_newz(buf);
  }
}

CallInfo *vm_getframe(lua_State *L, int level) {
  CallInfo *ci = L->ci - level;
  if (ci <= L->cibase) return NULL;
  return ci;
}

GCstr *vm_where(lua_State *L, int level) {
  CallInfo *ci = L->ci - level;
  if (ci > L->cibase && !ci->isC && ci->cl) {
    GCstr *src = vm_shortsrc(ci->cl->u.l.p->source);
    return str_fmt("%s:%d:", str_data(src), ci->curline);
  }
  return str_new("", 0);
}

void err_run(lua_State *L, const char *fmt, ...) {
  char buf[1024]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  GCstr *w = vm_where(L, 0);
  vm_pushfstring(L, "%s %s", str_data(w), buf);
  /* fix: vm_where returns "src:line:" and we want "src:line: msg"; if empty, no space */
  if (w->len == 0) { L->top--; vm_pushstring(L, buf); }
  else { L->top--; vm_pushfstring(L, "%s %s", str_data(w), buf); }
  vm_throw(L, LUA_ERRRUN);
}

void err_msg(lua_State *L, const char *fmt, ...) {
  char buf[1024]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  vm_pushstring(L, buf);
  vm_throw(L, LUA_ERRRUN);
}

/* error raised by a C function: position from caller Lua frame */
void err_callermsg(lua_State *L, const char *msg) {
  CallInfo *ci = L->ci;
  CallInfo *caller = ci - 1;
  if (caller > L->cibase && !caller->isC && caller->cl) {
    GCstr *src = vm_shortsrc(caller->cl->u.l.p->source);
    vm_pushfstring(L, "%s:%d: %s", str_data(src), caller->curline, msg);
  } else vm_pushstring(L, msg);
  vm_throw(L, LUA_ERRRUN);
}

static const char *expr_name(const Expr *e, const char **what) {
  while (e && e->kind == E_PAREN) e = e->u.un.e;
  if (!e) return NULL;
  switch (e->kind) {
  case E_GLOBAL: *what = "global"; return str_data(e->u.str);
  case E_LOCAL: *what = "local"; return str_data(e->u.var.name);
  case E_UPVAL: *what = "upvalue"; return str_data(e->u.var.name);
  case E_INDEX:
    if (e->u.index.key->kind == E_STRING) { *what = "field"; return str_data(e->u.index.key->u.str); }
    return NULL;
  case E_METHOD: *what = "method"; return str_data(e->u.call.name);
  default: return NULL;
  }
}

/* name of function running in frame ci, derived from the frame below */
int vm_getinfo_name(lua_State *L, CallInfo *ci, const char **name, const char **namewhat) {
  CallInfo *below = ci - 1;
  *name = NULL; *namewhat = "";
  if (ci->tailcalled) return 0;
  if (below < L->cibase) return 0;
  if (below->isC) return 0;
  if (below->curmm) { *name = below->curmm; *namewhat = "metamethod"; return 1; }
  if (below->curforgen) { *name = "(for generator)"; *namewhat = "for iterator"; return 1; }
  if (below->curcall) {
    const Expr *ce = below->curcall;
    const char *what = NULL, *n = NULL;
    if (ce->kind == E_METHOD) { *name = str_data(ce->u.call.name); *namewhat = "method"; return 1; }
    if (ce->kind == E_CALL) n = expr_name(ce->u.call.fn, &what);
    if (n) { *name = n; *namewhat = what; return 1; }
  }
  return 0;
}

void err_arg(lua_State *L, int narg, const char *msg) {
  const char *name, *what;
  char buf[1024];
  vm_getinfo_name(L, L->ci, &name, &what);
  if (name && strcmp(what, "method") == 0) {
    narg--;
    if (narg == 0) { snprintf(buf, sizeof(buf), "calling '%s' on bad self (%s)", name, msg); err_callermsg(L, buf); }
  }
  snprintf(buf, sizeof(buf), "bad argument #%d to '%s' (%s)", narg, name ? name : "?", msg);
  err_callermsg(L, buf);
}

void err_argtype(lua_State *L, int narg, const char *expected) {
  char buf[256];
  TValue *o = L->ci->base + narg - 1;
  const char *got = (o < L->top) ? typename_of(o) : "no value";
  snprintf(buf, sizeof(buf), "%s expected, got %s", expected, got);
  err_arg(L, narg, buf);
}

/* ---- metatables ---- */
Table *vm_getmetatable(const TValue *o) {
  switch (o->tt) {
  case T_TABLE: return tabV(o)->metatable;
  case T_USERDATA: return udataV(o)->metatable;
  case T_STRING: return G.strmt;
  default: return G.basemt[o->tt];
  }
}

const TValue *vm_getmetamethod(const TValue *o, int mm) {
  Table *mt = vm_getmetatable(o);
  if (!mt) return NILOBJ;
  return tab_getstr(mt, G.mmnames[mm]);
}

static inline const TValue *tab_getmm(Table *mt, int mm) {
  if (!mt) return NILOBJ;
  return tab_getstr(mt, G.mmnames[mm]);
}

/* ---- conversions ---- */
int vm_tonumber(const TValue *o, TValue *out) {
  if (ttisnumber(o)) { copyTV(out, o); return 1; }
  if (ttisstring(o)) {
    double n;
    if (str2num(str_data(strV(o)), strV(o)->len, &n)) { setnumV(out, n); return 1; }
  }
  return 0;
}

GCstr *vm_tostring_basic(const TValue *o) {
  char buf[64];
  switch (o->tt) {
  case T_NIL: return str_newz("nil");
  case T_BOOLEAN: return str_newz(boolV(o) ? "true" : "false");
  case T_NUMBER: return num2strobj(numV(o));
  case T_STRING: return strV(o);
  case T_FUNCTION: {
    Closure *c = funcV(o);
    if (c->isC && c->u.c.builtin) { sprintf(buf, "function: builtin#%d", c->u.c.builtin); return str_newz(buf); }
    sprintf(buf, "function: %p", (void *)c); return str_newz(buf);
  }
  case T_TABLE: sprintf(buf, "table: %p", (void *)tabV(o)); return str_newz(buf);
  case T_USERDATA: sprintf(buf, "userdata: %p", (void *)udataV(o)); return str_newz(buf);
  case T_THREAD: sprintf(buf, "thread: %p", (void *)threadV(o)); return str_newz(buf);
  case T_LIGHTUD: sprintf(buf, "userdata: %p", o->u.p); return str_newz(buf);
  default: return str_newz("?");
  }
}

static void call_mm(lua_State *L, const TValue *f, const char *mmname, int nargs, int nresults, const TValue *a, const TValue *b, const TValue *c);

GCstr *vm_tostring(lua_State *L, const TValue *o) {
  const TValue *mm = vm_getmetamethod(o, MM_TOSTRING);
  if (!ttisnil(mm)) {
    TValue obj = *o;
    call_mm(L, mm, "__tostring", 1, 1, &obj, NULL, NULL);
    L->top--;
    GCstr *s = vm_tostring_basic(L->top);
    return s;
  }
  return vm_tostring_basic(o);
}

/* ---- calls ---- */
static void exec_function(lua_State *L, CallInfo *ci);

static void adjust_results(lua_State *L, TValue *func, TValue *resbase, int nres, int nresults) {
  int i;
  if (nresults < 0) {
    if (resbase != func) for (i = 0; i < nres; i++) copyTV(func + i, resbase + i);
    L->top = func + nres;
  } else {
    int n = nres < nresults ? nres : nresults;
    if (resbase != func) for (i = 0; i < n; i++) copyTV(func + i, resbase + i);
    for (i = n; i < nresults; i++) setnilV(func + i);
    L->top = func + nresults;
  }
}

static void err_call(lua_State *L, const TValue *func) {
  const Expr *ce = L->ci->curcall;
  const char *what = NULL, *name = NULL;
  if (ce && ce->kind == E_METHOD) { what = "method"; name = str_data(ce->u.call.name); }
  else if (ce && ce->kind == E_CALL) name = expr_name(ce->u.call.fn, &what);
  if (name) err_run(L, "attempt to call %s '%s' (a %s value)", what, name, typename_of(func));
  err_run(L, "attempt to call a %s value", typename_of(func));
}

static char *cstack_limit;

void vm_call(lua_State *L, TValue *func, int nresults) {
  int nargs;
  Closure *cl;
  CallInfo *ci;
  int tail = 0;
  char probe;
  if (&probe < cstack_limit) { L->ci->curline = L->ci->curline; err_run(L, "stack overflow"); }
reentry:
  nargs = (int)(L->top - func - 1);
  if (!ttisfunction(func)) {
    const TValue *mm = vm_getmetamethod(func, MM_CALL);
    if (ttisnil(mm)) err_call(L, func);
    /* insert func as first argument */
    checkstack(L, 1);
    for (TValue *p = L->top; p > func; p--) copyTV(p, p - 1);
    L->top++;
    copyTV(func, mm);
    nargs++;
  }
  cl = funcV(func);
  if (L->ci + 1 >= L->ciend) err_run(L, "stack overflow");
  if (L->top + 40 >= L->stack + LUAI_MAXSTACK) err_run(L, "stack overflow");
  ci = ++L->ci;
  ci->func = func; ci->cl = cl; ci->curline = 0; ci->curcall = NULL; ci->curmm = NULL;
  ci->tailcalled = (uint8_t)tail; ci->curforgen = 0; ci->ismain = 0; ci->ispcall = 0; ci->retbase = NULL;
  ci->nvarargs = 0; ci->varargs = NULL;
  if (cl->isC) {
    ci->isC = 1;
    ci->base = func + 1;
    ci->top = L->top;
    int n = cl->u.c.f(L);
    /* results are the last n values on the stack */
    TValue *resbase = L->top - n;
    L->ci = ci - 1;
    adjust_results(L, func, resbase, n, nresults);
    return;
  }
  ci->isC = 0;
  {
    Proto *p = cl->u.l.p;
    TValue *base;
    if (p->isvararg) {
      int nfix = p->nparams;
      base = L->top;
      if (nargs < nfix) { for (int i = nargs; i < nfix; i++) setnilV(L->top++); nargs = nfix; base = L->top; }
      /* copy fixed params up; varargs stay */
      for (int i = 0; i < nfix; i++) { copyTV(base + i, func + 1 + i); setnilV(func + 1 + i); }
      ci->varargs = func + 1 + nfix;
      ci->nvarargs = nargs - nfix;
      ci->base = base;
      L->top = base + nfix;
    } else {
      base = func + 1;
      ci->base = base;
      for (int i = nargs; i < p->nparams; i++) setnilV(func + 1 + i);
      L->top = base + p->nparams;
    }
    if (L->top + p->nslots + 20 >= L->stack + LUAI_MAXSTACK) { L->ci = ci - 1; err_run(L, "stack overflow"); }
    for (int i = (int)(L->top - base); i < p->nslots; i++) setnilV(base + i);
    L->top = base + p->nslots;
    exec_function(L, ci);
    /* ci->retbase..L->top are results, or tail call pending (retbase points at function) */
    if (ci->retbase && ci->retbase->tt == T_NIL && 0) {}
    if (L->nresults == -2) {
      /* tail call: function at ci->retbase, args above */
      TValue *nf = ci->retbase;
      int n = (int)(L->top - nf);
      func_closeupvals(L, base);
      for (int i = 0; i < n; i++) copyTV(func + i, nf + i);
      L->top = func + n;
      L->ci = ci - 1;
      tail = 1;
      goto reentry;
    }
    {
      TValue *rb = ci->retbase ? ci->retbase : L->top;
      int nres = (int)(L->top - rb);
      func_closeupvals(L, base);
      L->ci = ci - 1;
      adjust_results(L, func, rb, nres, nresults);
    }
  }
}

int vm_pcall(lua_State *L, TValue *func, int nresults, ErrorJmp *ej) {
  CallInfo *saveci = L->ci;
  int oldncalls = L->ncalls;
  ej->prev = L->errjmp; ej->status = 0; ej->top = func;
  L->errjmp = ej;
  if (setjmp(ej->jb) == 0) {
    vm_call(L, func, nresults);
    L->errjmp = ej->prev;
    return LUA_OK;
  }
  /* error: error value at L->top-1 */
  {
    TValue err = *(L->top - 1);
    L->errjmp = ej->prev;
    L->ci = saveci;
    L->ncalls = oldncalls;
    func_closeupvals(L, func);
    L->top = func;
    copyTV(L->top++, &err);
    return ej->status ? ej->status : LUA_ERRRUN;
  }
}

/* call metamethod f with args, leave nresults on stack top */
static void call_mm(lua_State *L, const TValue *f, const char *mmname, int nargs, int nresults, const TValue *a, const TValue *b, const TValue *c) {
  TValue *base = L->top;
  checkstack(L, 4);
  copyTV(L->top++, f);
  if (nargs >= 1) copyTV(L->top++, a);
  if (nargs >= 2) copyTV(L->top++, b);
  if (nargs >= 3) copyTV(L->top++, c);
  const char *savemm = L->ci->curmm;
  const Expr *savecall = L->ci->curcall;
  L->ci->curmm = mmname; L->ci->curcall = NULL;
  vm_call(L, base, nresults);
  L->ci->curmm = savemm; L->ci->curcall = savecall;
}

/* ---- indexing ---- */
static void err_index(lua_State *L, const TValue *obj, const Expr *e) {
  const char *what = NULL, *name = NULL;
  if (e) name = expr_name(e, &what);
  if (name) err_run(L, "attempt to index %s '%s' (a %s value)", what, name, typename_of(obj));
  err_run(L, "attempt to index a %s value", typename_of(obj));
}

/* obj[key] with metamethods; result stored in *out (which must not alias stack top concerns) */
static void index_value(lua_State *L, const TValue *obj, const TValue *key, TValue *out, const Expr *objexpr) {
  TValue o = *obj;
  TValue k = *key;
  for (int loop = 0; loop < 100; loop++) {
    const TValue *mm;
    if (ttistable(&o)) {
      Table *t = tabV(&o);
      const TValue *v = tab_get(t, &k);
      if (!ttisnil(v)) { copyTV(out, v); return; }
      mm = tab_getmm(t->metatable, MM_INDEX);
      if (ttisnil(mm)) { setnilV(out); return; }
    } else {
      mm = vm_getmetamethod(&o, MM_INDEX);
      if (ttisnil(mm)) err_index(L, &o, loop == 0 ? objexpr : NULL);
    }
    if (ttisfunction(mm)) {
      call_mm(L, mm, "__index", 2, 1, &o, &k, NULL);
      L->top--;
      copyTV(out, L->top);
      return;
    }
    o = *mm;
  }
  err_run(L, "loop in gettable");
}

const TValue *vm_index(lua_State *L, const TValue *obj, const TValue *key, TValue *out) {
  index_value(L, obj, key, out, NULL);
  return out;
}

static void setindex_value(lua_State *L, const TValue *obj, const TValue *key, const TValue *val, const Expr *objexpr) {
  TValue o = *obj;
  TValue k = *key, v = *val;
  for (int loop = 0; loop < 100; loop++) {
    const TValue *mm;
    if (ttistable(&o)) {
      Table *t = tabV(&o);
      const TValue *slot = tab_get(t, &k);
      if (!ttisnil(slot)) { copyTV((TValue *)slot, &v); return; }
      mm = tab_getmm(t->metatable, MM_NEWINDEX);
      if (ttisnil(mm)) {
        TValue *s = tab_set(L, t, &k);
        copyTV(s, &v);
        return;
      }
    } else {
      mm = vm_getmetamethod(&o, MM_NEWINDEX);
      if (ttisnil(mm)) err_index(L, &o, loop == 0 ? objexpr : NULL);
    }
    if (ttisfunction(mm)) {
      call_mm(L, mm, "__newindex", 3, 0, &o, &k, &v);
      return;
    }
    o = *mm;
  }
  err_run(L, "loop in settable");
}

void vm_setindex(lua_State *L, const TValue *obj, const TValue *key, const TValue *val) {
  setindex_value(L, obj, key, val, NULL);
}

/* ---- arithmetic ---- */
double lua_fmod(double a, double b) {
  double m = fmod(a, b);
  if (m != 0 && (m ^ 0, (m < 0) != (b < 0))) m += b;
  return m;
}
static inline double lmod(double a, double b) {
  /* LuaJIT: a - floor(a/b)*b */
  double m = fmod(a, b);
  if ((m > 0 && b < 0) || (m < 0 && b > 0)) m += b;
  if (b == 0 || isinf(b)) return a - floor(a / b) * b;
  return m;
}

static inline double arith_op(int op, double a, double b) {
  switch (op) {
  case OP_ADD: return a + b;
  case OP_SUB: return a - b;
  case OP_MUL: return a * b;
  case OP_DIV: return a / b;
  case OP_MOD: return lmod(a, b);
  case OP_POW: return pow(a, b);
  default: return 0;
  }
}

static int arith_mm[] = { MM_ADD, MM_SUB, MM_MUL, MM_DIV, MM_MOD, MM_POW };

static void err_optype(lua_State *L, const TValue *o, const Expr *e, const char *opmsg) {
  const char *what = NULL, *name = NULL;
  if (e) name = expr_name(e, &what);
  if (name) err_run(L, "attempt to %s %s '%s' (a %s value)", opmsg, what, name, typename_of(o));
  err_run(L, "attempt to %s a %s value", opmsg, typename_of(o));
}

void vm_arith(lua_State *L, int op, const TValue *a, const TValue *b, TValue *out, const Expr *ea, const Expr *eb) {
  TValue na, nb;
  if (vm_tonumber(a, &na) && vm_tonumber(b, &nb)) { setnumV(out, arith_op(op, numV(&na), numV(&nb))); return; }
  {
    int mm = arith_mm[op];
    const TValue *f = vm_getmetamethod(a, mm);
    if (ttisnil(f)) {
      f = vm_getmetamethod(b, mm);
      if (ttisnil(f)) {
        if (!vm_tonumber(a, &na)) err_optype(L, a, ea, "perform arithmetic on");
        err_optype(L, b, eb, "perform arithmetic on");
      }
    }
    TValue ta = *a, tb = *b;
    call_mm(L, f, mm_names[mm], 2, 1, &ta, &tb, NULL);
    L->top--;
    copyTV(out, L->top);
  }
}

static void vm_unm(lua_State *L, const TValue *a, TValue *out, const Expr *ea) {
  TValue na;
  if (vm_tonumber(a, &na)) { setnumV(out, -numV(&na)); return; }
  const TValue *f = vm_getmetamethod(a, MM_UNM);
  if (ttisnil(f)) err_optype(L, a, ea, "perform arithmetic on");
  TValue ta = *a;
  call_mm(L, f, "__unm", 2, 1, &ta, &ta, NULL);
  L->top--;
  copyTV(out, L->top);
}

static void vm_len(lua_State *L, const TValue *a, TValue *out, const Expr *ea) {
  if (ttisstring(a)) { setnumV(out, (double)strV(a)->len); return; }
  if (ttistable(a)) { setnumV(out, (double)tab_len(tabV(a))); return; }
  const TValue *f = vm_getmetamethod(a, MM_LEN);
  if (ttisnil(f)) err_optype(L, a, ea, "get length of");
  TValue ta = *a;
  call_mm(L, f, "__len", 2, 1, &ta, &ta, NULL);
  L->top--;
  copyTV(out, L->top);
}

/* ---- comparison ---- */
int vm_equal(lua_State *L, const TValue *a, const TValue *b) {
  if (a->tt != b->tt) return 0;
  switch (a->tt) {
  case T_NIL: return 1;
  case T_BOOLEAN: return boolV(a) == boolV(b);
  case T_NUMBER: return numV(a) == numV(b);
  case T_LIGHTUD: return a->u.p == b->u.p;
  case T_TABLE: case T_USERDATA: {
    if (a->u.gc == b->u.gc) return 1;
    const TValue *ma = vm_getmetamethod(a, MM_EQ);
    if (ttisnil(ma)) return 0;
    const TValue *mb = vm_getmetamethod(b, MM_EQ);
    if (ttisnil(mb)) return 0;
    if (!lua_rawequal(ma, mb)) return 0;
    TValue ta = *a, tb = *b;
    call_mm(L, ma, "__eq", 2, 1, &ta, &tb, NULL);
    L->top--;
    return !isfalse(L->top);
  }
  default: return a->u.gc == b->u.gc;
  }
}

static void err_compare(lua_State *L, const TValue *a, const TValue *b) {
  const char *t1 = typename_of(a), *t2 = typename_of(b);
  if (strcmp(t1, t2) == 0) err_run(L, "attempt to compare two %s values", t1);
  err_run(L, "attempt to compare %s with %s", t1, t2);
}

static int call_orderTM(lua_State *L, const TValue *a, const TValue *b, int mm) {
  const TValue *ma = vm_getmetamethod(a, mm);
  if (ttisnil(ma)) return -1;
  const TValue *mb = vm_getmetamethod(b, mm);
  if (ttisnil(mb)) return -1;
  if (!lua_rawequal(ma, mb)) return -1;
  TValue ta = *a, tb = *b;
  call_mm(L, ma, mm_names[mm], 2, 1, &ta, &tb, NULL);
  L->top--;
  return !isfalse(L->top);
}

int vm_lessthan(lua_State *L, const TValue *a, const TValue *b) {
  if (ttisnumber(a) && ttisnumber(b)) return numV(a) < numV(b);
  if (ttisstring(a) && ttisstring(b)) return str_cmp(strV(a), strV(b)) < 0;
  if (a->tt == b->tt) {
    int r = call_orderTM(L, a, b, MM_LT);
    if (r >= 0) return r;
  }
  err_compare(L, a, b);
  return 0;
}

int vm_lessequal(lua_State *L, const TValue *a, const TValue *b) {
  if (ttisnumber(a) && ttisnumber(b)) return numV(a) <= numV(b);
  if (ttisstring(a) && ttisstring(b)) return str_cmp(strV(a), strV(b)) <= 0;
  if (a->tt == b->tt) {
    int r = call_orderTM(L, a, b, MM_LE);
    if (r >= 0) return r;
    r = call_orderTM(L, b, a, MM_LT);
    if (r >= 0) return !r;
  }
  err_compare(L, a, b);
  return 0;
}

/* ---- concat ---- */
static inline int tostr_concat(const TValue *o, GCstr **s, char *buf, size_t *len, const char **data) {
  if (ttisstring(o)) { *s = strV(o); *data = str_data(*s); *len = (*s)->len; return 1; }
  if (ttisnumber(o)) { *len = num2str(buf, numV(o)); *data = buf; *s = NULL; return 1; }
  return 0;
}

/* concatenate `total` values at top of stack (right to left), leaving one value. exprs for naming may be NULL */
static void concat_values(lua_State *L, int total, const Expr *const *exprs) {
  /* values at L->top - total .. L->top - 1 */
  while (total > 1) {
    TValue *top = L->top;
    TValue *r = top - 1, *l = top - 2;
    GCstr *ls, *rs; char lbuf[64], rbuf[64]; size_t llen, rlen; const char *ld, *rd;
    if (!tostr_concat(l, &ls, lbuf, &llen, &ld) || !tostr_concat(r, &rs, rbuf, &rlen, &rd)) {
      const TValue *f = vm_getmetamethod(l, MM_CONCAT);
      if (ttisnil(f)) f = vm_getmetamethod(r, MM_CONCAT);
      if (ttisnil(f)) {
        int idx;
        const TValue *bad;
        if (!(ttisstring(l) || ttisnumber(l))) { bad = l; idx = (int)(l - (top - total)); }
        else { bad = r; idx = (int)(r - (top - total)); }
        const Expr *e = exprs ? exprs[(int)(L->top - total) + 0 == 0 ? idx : idx] : NULL;
        (void)e;
        err_optype(L, bad, exprs ? exprs[idx] : NULL, "concatenate");
      }
      TValue tl = *l, tr = *r;
      call_mm(L, f, "__concat", 2, 1, &tl, &tr, NULL);
      L->top--;
      copyTV(l, L->top);
      L->top = top - 1;
      total--;
      continue;
    }
    /* collect as many consecutive string/number values from the right as possible */
    {
      int n = 2; size_t tl = llen + rlen;
      while (n < total) {
        TValue *o = top - n - 1;
        GCstr *s; char b[64]; size_t len; const char *d;
        if (!tostr_concat(o, &s, b, &len, &d)) break;
        tl += len; n++;
      }
      if (tl >= 0x7fffff00u) err_run(L, "string length overflow");
      char *buf = (char *)malloc(tl + 1);
      char *p = buf;
      for (int i = n; i >= 1; i--) {
        TValue *o = top - i;
        if (ttisstring(o)) { memcpy(p, str_data(strV(o)), strV(o)->len); p += strV(o)->len; }
        else { p += num2str(p, numV(o)); }
      }
      GCstr *res = str_new(buf, tl);
      free(buf);
      setstrV(top - n, res);
      L->top = top - n + 1;
      total -= n - 1;
    }
  }
}

void vm_concat(lua_State *L, int total) { concat_values(L, total, NULL); }

/* ---- interpreter ---- */
enum { EX_NORMAL = 0, EX_BREAK, EX_RETURN, EX_GOTO };

static int exec_block(lua_State *L, CallInfo *ci, const Block *b, const Stmt **gototarget);
static void eval(lua_State *L, CallInfo *ci, const Expr *e);
static int eval_multi(lua_State *L, CallInfo *ci, const Expr *e);

static const Stmt *pending_goto;  /* goto statement being propagated */

#define SLOT(ci, i) ((ci)->base + (i))

static inline void push_closure(lua_State *L, CallInfo *ci, const Expr *e) {
  Proto *p = ci->cl->u.l.p->children[e->u.idx];
  Closure *c = func_newL(p, ci->cl->env);
  setfuncV(L->top, c); L->top++;   /* anchor before creating upvalues */
  for (int i = 0; i < p->nupvals; i++) {
    UpvalDesc *d = &p->upvals[i];
    if (d->instack) c->u.l.upvals[i] = func_findupval(L, ci->base + d->idx);
    else c->u.l.upvals[i] = ci->cl->u.l.upvals[d->idx];
  }
}

static void eval_call(lua_State *L, CallInfo *ci, const Expr *e, int nresults) {
  TValue *func = L->top;
  checkstack(L, e->u.call.nargs + 3);
  if (e->kind == E_METHOD) {
    eval(L, ci, e->u.call.fn);           /* object */
    TValue *obj = L->top - 1;
    TValue key; setstrV(&key, e->u.call.name);
    TValue method;
    ci->curline = e->line;
    index_value(L, obj, &key, &method, e->u.call.fn);
    /* arrange: func = method, arg1 = obj */
    copyTV(L->top, obj); L->top++;
    copyTV(func, &method);
  } else {
    eval(L, ci, e->u.call.fn);
  }
  for (int i = 0; i < e->u.call.nargs; i++) {
    const Expr *a = e->u.call.args[i];
    if (i == e->u.call.nargs - 1) eval_multi(L, ci, a);
    else eval(L, ci, a);
  }
  ci->curline = e->line;
  ci->curcall = e;
  vm_call(L, func, nresults);
  ci->curcall = NULL;
}

static int eval_multi(lua_State *L, CallInfo *ci, const Expr *e) {
  switch (e->kind) {
  case E_CALL: case E_METHOD: {
    TValue *base = L->top;
    eval_call(L, ci, e, -1);
    return (int)(L->top - base);
  }
  case E_VARARG: {
    int n = ci->nvarargs;
    checkstack(L, n + 1);
    for (int i = 0; i < n; i++) copyTV(L->top + i, ci->varargs + i);
    L->top += n;
    return n;
  }
  default:
    eval(L, ci, e);
    return 1;
  }
}

static void eval_table(lua_State *L, CallInfo *ci, const Expr *e) {
  Table *t = tab_new(e->u.tab.narray, e->u.tab.nhash);
  TValue *tv = L->top;
  settabV(L->top, t); L->top++;
  int ai = 1;
  for (int i = 0; i < e->u.tab.nitems; i++) {
    const TabItem *it = &e->u.tab.items[i];
    if (it->key) {
      eval(L, ci, it->key);
      eval(L, ci, it->val);
      TValue *k = L->top - 2, *v = L->top - 1;
      if (ttisnil(k)) { ci->curline = it->val->line; err_run(L, "table index is nil"); }
      if (ttisnumber(k) && isnan(numV(k))) { ci->curline = it->val->line; err_run(L, "table index is NaN"); }
      TValue *slot = tab_set(L, t, k);
      copyTV(slot, v);
      L->top -= 2;
    } else {
      if (i == e->u.tab.nitems - 1 && (it->val->kind == E_CALL || it->val->kind == E_METHOD || it->val->kind == E_VARARG)) {
        int n = eval_multi(L, ci, it->val);
        TValue *vals = L->top - n;
        if (n > 0 && (uint32_t)(ai + n - 1) > t->asize) tab_resize(L, t, ai + n - 1, t->node && t->lsizenode ? (1u << t->lsizenode) : 0);
        for (int j = 0; j < n; j++) {
          TValue *slot = tab_setint(L, t, ai++);
          copyTV(slot, vals + j);
        }
        L->top = vals;
      } else {
        eval(L, ci, it->val);
        TValue *slot = tab_setint(L, t, ai++);
        copyTV(slot, L->top - 1);
        L->top--;
      }
    }
  }
  (void)tv;
}

static void eval(lua_State *L, CallInfo *ci, const Expr *e) {
  switch (e->kind) {
  case E_NIL: setnilV(L->top); L->top++; return;
  case E_TRUE: setboolV(L->top, 1); L->top++; return;
  case E_FALSE: setboolV(L->top, 0); L->top++; return;
  case E_NUMBER: setnumV(L->top, e->u.num); L->top++; return;
  case E_STRING: setstrV(L->top, e->u.str); L->top++; return;
  case E_VARARG:
    if (ci->nvarargs > 0) copyTV(L->top, ci->varargs); else setnilV(L->top);
    L->top++; return;
  case E_FUNCTION: push_closure(L, ci, e); return;
  case E_LOCAL: copyTV(L->top, SLOT(ci, e->u.var.idx)); L->top++; return;
  case E_UPVAL: copyTV(L->top, ci->cl->u.l.upvals[e->u.var.idx]->v); L->top++; return;
  case E_GLOBAL: {
    TValue key; setstrV(&key, e->u.str);
    TValue env; settabV(&env, ci->cl->env);
    const TValue *v = tab_getstr(ci->cl->env, e->u.str);
    if (!ttisnil(v) || ci->cl->env->metatable == NULL) { copyTV(L->top, v); L->top++; return; }
    ci->curline = e->line;
    index_value(L, &env, &key, L->top, NULL);
    L->top++;
    return;
  }
  case E_INDEX: {
    eval(L, ci, e->u.index.obj);
    eval(L, ci, e->u.index.key);
    TValue *obj = L->top - 2, *key = L->top - 1;
    if (ttistable(obj)) {
      const TValue *v = tab_get(tabV(obj), key);
      if (!ttisnil(v) || tabV(obj)->metatable == NULL) { copyTV(obj, v); L->top--; return; }
    }
    ci->curline = e->line;
    TValue out;
    index_value(L, obj, key, &out, e->u.index.obj);
    copyTV(obj, &out);
    L->top--;
    return;
  }
  case E_CALL: case E_METHOD:
    eval_call(L, ci, e, 1);
    return;
  case E_PAREN: {
    TValue *base = L->top;
    eval_multi(L, ci, e->u.un.e);
    if (L->top == base) { setnilV(L->top); L->top++; }
    else L->top = base + 1;
    return;
  }
  case E_AND: {
    eval(L, ci, e->u.bin.a);
    if (isfalse(L->top - 1)) return;
    L->top--;
    eval(L, ci, e->u.bin.b);
    return;
  }
  case E_OR: {
    eval(L, ci, e->u.bin.a);
    if (!isfalse(L->top - 1)) return;
    L->top--;
    eval(L, ci, e->u.bin.b);
    return;
  }
  case E_UNOP: {
    eval(L, ci, e->u.un.e);
    TValue *a = L->top - 1;
    switch (e->op) {
    case OPU_NOT: setboolV(a, isfalse(a)); return;
    case OPU_NEG:
      if (ttisnumber(a)) { a->u.n = -a->u.n; return; }
      ci->curline = e->line;
      { TValue out; vm_unm(L, a, &out, e->u.un.e); copyTV(L->top - 1, &out); }
      return;
    case OPU_LEN:
      if (ttisstring(a)) { setnumV(a, (double)strV(a)->len); return; }
      if (ttistable(a)) { setnumV(a, (double)tab_len(tabV(a))); return; }
      ci->curline = e->line;
      { TValue out; vm_len(L, a, &out, e->u.un.e); copyTV(L->top - 1, &out); }
      return;
    }
    return;
  }
  case E_BINOP: {
    int op = e->op;
    if (op == OP_CONCAT) {
      /* flatten chain */
      const Expr *parts[256]; int n = 0;
      const Expr *c = e;
      while (c->kind == E_BINOP && c->op == OP_CONCAT && n < 255) { parts[n++] = c->u.bin.a; c = c->u.bin.b; }
      parts[n++] = c;
      checkstack(L, n + 2);
      for (int i = 0; i < n; i++) eval(L, ci, parts[i]);
      ci->curline = e->line;
      concat_values(L, n, parts);
      return;
    }
    eval(L, ci, e->u.bin.a);
    eval(L, ci, e->u.bin.b);
    TValue *a = L->top - 2, *b = L->top - 1;
    switch (op) {
    case OP_ADD: if (ttisnumber(a) && ttisnumber(b)) { a->u.n += b->u.n; L->top--; return; } break;
    case OP_SUB: if (ttisnumber(a) && ttisnumber(b)) { a->u.n -= b->u.n; L->top--; return; } break;
    case OP_MUL: if (ttisnumber(a) && ttisnumber(b)) { a->u.n *= b->u.n; L->top--; return; } break;
    case OP_DIV: if (ttisnumber(a) && ttisnumber(b)) { a->u.n /= b->u.n; L->top--; return; } break;
    case OP_MOD: if (ttisnumber(a) && ttisnumber(b)) { a->u.n = lmod(a->u.n, b->u.n); L->top--; return; } break;
    case OP_POW: if (ttisnumber(a) && ttisnumber(b)) { a->u.n = pow(a->u.n, b->u.n); L->top--; return; } break;
    case OP_EQ: case OP_NE: {
      int r;
      if (a->tt != b->tt) r = 0;
      else if (ttisnumber(a)) r = a->u.n == b->u.n;
      else if (ttisstring(a) || ttisboolean(a) || ttisnil(a)) r = lua_rawequal(a, b);
      else { ci->curline = e->line; r = vm_equal(L, a, b); }
      setboolV(a, op == OP_EQ ? r : !r);
      L->top--;
      return;
    }
    case OP_LT: case OP_GT: {
      int r;
      if (op == OP_GT) { TValue *t = a; a = b; b = t; }
      if (ttisnumber(a) && ttisnumber(b)) r = a->u.n < b->u.n;
      else { ci->curline = e->line; r = vm_lessthan(L, a, b); }
      setboolV(L->top - 2, r); L->top--;
      return;
    }
    case OP_LE: case OP_GE: {
      int r;
      if (op == OP_GE) { TValue *t = a; a = b; b = t; }
      if (ttisnumber(a) && ttisnumber(b)) r = a->u.n <= b->u.n;
      else { ci->curline = e->line; r = vm_lessequal(L, a, b); }
      setboolV(L->top - 2, r); L->top--;
      return;
    }
    }
    /* arithmetic slow path */
    ci->curline = e->line;
    {
      TValue out;
      vm_arith(L, op, a, b, &out, e->u.bin.a, e->u.bin.b);
      copyTV(L->top - 2, &out);
      L->top--;
    }
    return;
  }
  case E_TABLE: eval_table(L, ci, e); return;
  }
}

/* assign value v to target expression */
static void assign_to(lua_State *L, CallInfo *ci, const Expr *target, TValue *objkey, const TValue *v, int line) {
  switch (target->kind) {
  case E_LOCAL: copyTV(SLOT(ci, target->u.var.idx), v); return;
  case E_UPVAL: copyTV(ci->cl->u.l.upvals[target->u.var.idx]->v, v); return;
  case E_GLOBAL: {
    Table *env = ci->cl->env;
    if (env->metatable == NULL) {
      TValue *slot = tab_setstr(L, env, target->u.str);
      copyTV(slot, v);
      return;
    }
    TValue envv, key; settabV(&envv, env); setstrV(&key, target->u.str);
    ci->curline = line;
    setindex_value(L, &envv, &key, v, NULL);
    return;
  }
  case E_INDEX: {
    TValue *obj = objkey, *key = objkey + 1;
    if (ttistable(obj)) {
      Table *t = tabV(obj);
      const TValue *slot = tab_get(t, key);
      if (!ttisnil(slot)) { copyTV((TValue *)slot, v); return; }
      if (t->metatable == NULL) {
        ci->curline = line;
        TValue *s = tab_set(L, t, key);
        copyTV(s, v);
        return;
      }
    }
    ci->curline = line;
    setindex_value(L, obj, key, v, target->u.index.obj);
    return;
  }
  default: return;
  }
}

static int exec_stmt(lua_State *L, CallInfo *ci, const Stmt *s, const Block *blk, int *pc);

static int exec_block(lua_State *L, CallInfo *ci, const Block *b, const Stmt **gototarget) {
  int pc = 0;
  int st = EX_NORMAL;
  (void)gototarget;
  gc_check(L);
  while (pc < b->nstmts) {
    const Stmt *s = b->stmts[pc++];
    st = exec_stmt(L, ci, s, b, &pc);
    if (st != EX_NORMAL) {
      if (st == EX_GOTO) {
        const Stmt *g = pending_goto;
        if (g->u.gotostmt.target == b) {
          pc = g->u.gotostmt.index;
          func_closeupvals(L, ci->base + (int)(intptr_t)g->u.gotostmt.name);
          st = EX_NORMAL;
          continue;
        }
      }
      break;
    }
  }
  if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot);
  return st;
}

static inline int exec_body(lua_State *L, CallInfo *ci, const Block *b) {
  return exec_block(L, ci, b, NULL);
}

static int exec_stmt(lua_State *L, CallInfo *ci, const Stmt *s, const Block *blk, int *pc) {
  (void)blk; (void)pc;
  switch (s->kind) {
  case S_LOCAL: {
    int nv = s->u.local.nvars, ne = s->u.local.nexprs;
    TValue *base = L->top;
    checkstack(L, nv + ne + 2);
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.local.exprs[i]);
      else eval(L, ci, s->u.local.exprs[i]);
    }
    int got = (int)(L->top - base);
    for (int i = 0; i < nv; i++) {
      if (i < got) copyTV(SLOT(ci, s->u.local.slots[i]), base + i);
      else setnilV(SLOT(ci, s->u.local.slots[i]));
    }
    L->top = base;
    return EX_NORMAL;
  }
  case S_LOCALFUNC: {
    TValue *base = L->top;
    setnilV(SLOT(ci, s->u.localfunc.slot));
    /* the closure may reference itself: create closure, then store */
    push_closure(L, ci, s->u.localfunc.func);
    copyTV(SLOT(ci, s->u.localfunc.slot), base);
    L->top = base;
    return EX_NORMAL;
  }
  case S_ASSIGN: {
    int nt = s->u.assign.ntargets, ne = s->u.assign.nexprs;
    TValue *base = L->top;
    checkstack(L, nt * 2 + ne + 2);
    if (nt == 1 && ne == 1) {
      const Expr *t = s->u.assign.targets[0];
      if (t->kind == E_LOCAL) {
        eval(L, ci, s->u.assign.exprs[0]);
        copyTV(SLOT(ci, t->u.var.idx), L->top - 1);
        L->top = base;
        return EX_NORMAL;
      }
      if (t->kind == E_INDEX) {
        eval(L, ci, t->u.index.obj);
        eval(L, ci, t->u.index.key);
        eval(L, ci, s->u.assign.exprs[0]);
        assign_to(L, ci, t, base, L->top - 1, s->line);
        L->top = base;
        return EX_NORMAL;
      }
      eval(L, ci, s->u.assign.exprs[0]);
      assign_to(L, ci, t, NULL, L->top - 1, s->line);
      L->top = base;
      return EX_NORMAL;
    }
    /* evaluate target prefixes (obj, key) for index targets */
    for (int i = 0; i < nt; i++) {
      const Expr *t = s->u.assign.targets[i];
      if (t->kind == E_INDEX) { eval(L, ci, t->u.index.obj); eval(L, ci, t->u.index.key); }
      else { setnilV(L->top); setnilV(L->top + 1); L->top += 2; }
    }
    TValue *vbase = L->top;
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.assign.exprs[i]);
      else eval(L, ci, s->u.assign.exprs[i]);
    }
    int got = (int)(L->top - vbase);
    for (int i = got; i < nt; i++) { setnilV(L->top); L->top++; }
    /* assign right to left */
    for (int i = nt - 1; i >= 0; i--) {
      assign_to(L, ci, s->u.assign.targets[i], base + 2 * i, vbase + i, s->line);
    }
    L->top = base;
    return EX_NORMAL;
  }
  case S_CALL: {
    TValue *base = L->top;
    eval_call(L, ci, s->u.call.call, 0);
    L->top = base;
    return EX_NORMAL;
  }
  case S_DO:
    return exec_body(L, ci, s->u.doblk.body);
  case S_WHILE: {
    for (;;) {
      TValue *base = L->top;
      eval(L, ci, s->u.whileloop.cond);
      int c = !isfalse(L->top - 1);
      L->top = base;
      if (!c) break;
      int st = exec_body(L, ci, s->u.whileloop.body);
      if (st == EX_BREAK) break;
      if (st != EX_NORMAL) return st;
    }
    return EX_NORMAL;
  }
  case S_REPEAT: {
    for (;;) {
      const Block *b = s->u.repeatloop.body;
      /* execute body without closing upvalues until condition evaluated */
      int pcc = 0, st = EX_NORMAL;
      gc_check(L);
      while (pcc < b->nstmts) {
        const Stmt *ss = b->stmts[pcc++];
        st = exec_stmt(L, ci, ss, b, &pcc);
        if (st != EX_NORMAL) {
          if (st == EX_GOTO && pending_goto->u.gotostmt.target == b) {
            pcc = pending_goto->u.gotostmt.index;
            func_closeupvals(L, ci->base + (int)(intptr_t)pending_goto->u.gotostmt.name);
            st = EX_NORMAL; continue;
          }
          break;
        }
      }
      if (st == EX_BREAK) { if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot); break; }
      if (st != EX_NORMAL) { if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot); return st; }
      TValue *base = L->top;
      eval(L, ci, s->u.repeatloop.cond);
      int c = !isfalse(L->top - 1);
      L->top = base;
      if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot);
      if (c) break;
    }
    return EX_NORMAL;
  }
  case S_IF: {
    for (int i = 0; i < s->u.ifstmt.nconds; i++) {
      TValue *base = L->top;
      eval(L, ci, s->u.ifstmt.conds[i]);
      int c = !isfalse(L->top - 1);
      L->top = base;
      if (c) return exec_body(L, ci, s->u.ifstmt.blocks[i]);
    }
    if (s->u.ifstmt.elseblk) return exec_body(L, ci, s->u.ifstmt.elseblk);
    return EX_NORMAL;
  }
  case S_NUMFOR: {
    TValue *base = L->top;
    eval(L, ci, s->u.numfor.start);
    eval(L, ci, s->u.numfor.limit);
    if (s->u.numfor.step) eval(L, ci, s->u.numfor.step); else { setnumV(L->top, 1); L->top++; }
    TValue *vs = base;
    ci->curline = s->line;
    if (!ttisnumber(vs)) { TValue n; if (vm_tonumber(vs, &n) && 0) copyTV(vs, &n); else err_run(L, "'for' initial value must be a number"); }
    if (!ttisnumber(vs + 1)) err_run(L, "'for' limit must be a number");
    if (!ttisnumber(vs + 2)) err_run(L, "'for' step must be a number");
    double idx = numV(vs), limit = numV(vs + 1), step = numV(vs + 2);
    L->top = base;
    TValue *var = SLOT(ci, s->u.numfor.slot);
    const Block *body = s->u.numfor.body;
    if (step > 0 ? idx <= limit : idx >= limit) {
      for (;;) {
        setnumV(var, idx);
        int st = exec_body(L, ci, body);
        if (st == EX_BREAK) break;
        if (st != EX_NORMAL) return st;
        idx += step;
        if (!(step > 0 ? idx <= limit : idx >= limit)) break;
      }
    }
    return EX_NORMAL;
  }
  case S_GENFOR: {
    TValue *base = L->top;
    int ne = s->u.genfor.nexprs;
    checkstack(L, ne + 8);
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.genfor.exprs[i]);
      else eval(L, ci, s->u.genfor.exprs[i]);
    }
    int got = (int)(L->top - base);
    for (int i = got; i < 3; i++) { setnilV(L->top); L->top++; }
    TValue *hid = SLOT(ci, s->u.genfor.baseslot);
    copyTV(hid, base); copyTV(hid + 1, base + 1); copyTV(hid + 2, base + 2);
    L->top = base;
    int nv = s->u.genfor.nvars;
    TValue *vars = hid + 3;
    const Block *body = s->u.genfor.body;
    for (;;) {
      TValue *cb = L->top;
      copyTV(L->top, hid); copyTV(L->top + 1, hid + 1); copyTV(L->top + 2, hid + 2);
      L->top += 3;
      ci->curline = s->line;
      ci->curforgen = 1;
      vm_call(L, cb, nv);
      ci->curforgen = 0;
      if (ttisnil(cb)) { L->top = cb; break; }
      for (int i = 0; i < nv; i++) copyTV(vars + i, cb + i);
      copyTV(hid + 2, cb);
      L->top = cb;
      int st = exec_body(L, ci, body);
      if (st == EX_BREAK) break;
      if (st != EX_NORMAL) return st;
    }
    return EX_NORMAL;
  }
  case S_RETURN: {
    int ne = s->u.ret.nexprs;
    TValue *base = L->top;
    checkstack(L, ne + 2);
    if (s->u.ret.istail) {
      /* evaluate function and args, then signal tail call */
      const Expr *e = s->u.ret.exprs[0];
      TValue *func = L->top;
      if (e->kind == E_METHOD) {
        eval(L, ci, e->u.call.fn);
        TValue *obj = L->top - 1;
        TValue key; setstrV(&key, e->u.call.name);
        TValue method;
        ci->curline = e->line;
        index_value(L, obj, &key, &method, e->u.call.fn);
        copyTV(L->top, obj); L->top++;
        copyTV(func, &method);
      } else eval(L, ci, e->u.call.fn);
      for (int i = 0; i < e->u.call.nargs; i++) {
        if (i == e->u.call.nargs - 1) eval_multi(L, ci, e->u.call.args[i]);
        else eval(L, ci, e->u.call.args[i]);
      }
      ci->curline = e->line;
      ci->curcall = e;
      if (!ttisfunction(func)) {
        /* let vm_call handle __call or error, but as a normal call to keep naming */
        const TValue *mm = vm_getmetamethod(func, MM_CALL);
        if (ttisnil(mm)) err_call(L, func);
      }
      ci->retbase = func;
      L->nresults = -2;
      return EX_RETURN;
    }
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.ret.exprs[i]);
      else eval(L, ci, s->u.ret.exprs[i]);
    }
    ci->retbase = base;
    L->nresults = (int)(L->top - base);
    return EX_RETURN;
  }
  case S_BREAK: return EX_BREAK;
  case S_GOTO: pending_goto = s; return EX_GOTO;
  case S_LABEL: return EX_NORMAL;
  }
  return EX_NORMAL;
}

static void exec_function(lua_State *L, CallInfo *ci) {
  Proto *p = ci->cl->u.l.p;
  L->nresults = 0;
  ci->retbase = NULL;
  int st = exec_block(L, ci, p->body, NULL);
  if (st != EX_RETURN) { ci->retbase = L->top; L->nresults = 0; }
}

/* ---- traceback ---- */
static void frame_desc(lua_State *L, CallInfo *ci, SBuf *sb) {
  if (ci->isC) {
    const char *name, *what;
    if (vm_getinfo_name(L, ci, &name, &what)) sbuf_putf(sb, "\t[C]: in function '%s'\n", name);
    else if (ci->cl && ci->cl->isC && ci->cl->u.c.builtin == 0 && ci->cl->u.c.name) sbuf_putf(sb, "\t[C]: in function '%s'\n", ci->cl->u.c.name);
    else sbuf_putf(sb, "\t[C]: at 0x%08x\n", (unsigned)(uintptr_t)(ci->cl ? (void *)ci->cl->u.c.f : NULL) & 0xffffffffu);
    return;
  }
  Proto *p = ci->cl->u.l.p;
  GCstr *src = vm_shortsrc(p->source);
  sbuf_putf(sb, "\t%s:%d: in ", str_data(src), ci->curline);
  const char *name, *what;
  if (vm_getinfo_name(L, ci, &name, &what)) sbuf_putf(sb, "function '%s'\n", name);
  else if (p->linedefined == 0) sbuf_puts(sb, "main chunk\n");
  else sbuf_putf(sb, "function <%s:%d>\n", str_data(src), p->linedefined);
}

void vm_traceback(lua_State *L, lua_State *L1, const char *msg, int level, char **out) {
  SBuf sb; sbuf_init(&sb);
  if (msg) { sbuf_puts(&sb, msg); sbuf_putc(&sb, '\n'); }
  sbuf_puts(&sb, "stack traceback:");
  CallInfo *ci = L1->ci - level;
  int count = 0;
  int total = (int)(ci - L1->cibase);
  for (; ci > L1->cibase; ci--) {
    if (total > 22 && count == 10) {
      int skip = total - 21 - 10;
      if (skip > 0) { sbuf_putf(&sb, "\n\t...\n"); ci -= skip; sb.n--; }
    }
    sbuf_putc(&sb, '\n');
    frame_desc(L1, ci, &sb);
    sb.n--;  /* remove trailing newline */
    count++;
  }
  if (L1 == G.mainthread || L1->status != CO_SUSPENDED) {
    /* nothing */
  }
  if (L1->cibase->ismain && L1 == G.mainthread) {
    sbuf_puts(&sb, "\n\t[C]: at 0x");
    sbuf_putf(&sb, "%012lx", (unsigned long)(uintptr_t)vm_traceback & 0xffffffffffffUL);
  }
  (void)L;
  sbuf_putc(&sb, '\0');
  *out = sb.b;
}

/* ---- coroutines (ucontext based) ---- */
#define CO_CSTACK_SIZE (256u * 1024 * 1024)

typedef struct CoCtx {
  ucontext_t uc;
  ucontext_t *back;
} CoCtx;

void co_free_cstack(lua_State *L) {
  if (L->cstack) { munmap(L->cstack, L->cstacksize); L->cstack = NULL; }
  if (L->ctx) { free(L->ctx); L->ctx = NULL; }
}

static lua_State *co_starting;

static void co_entry(void) {
  lua_State *co = co_starting;
  CoCtx *cc = (CoCtx *)co->ctx;
  ErrorJmp ej;
  ej.prev = NULL; ej.status = 0;
  co->errjmp = &ej;
  char *oldlimit = cstack_limit;
  cstack_limit = (char *)co->cstack + 256 * 1024;
  if (setjmp(ej.jb) == 0) {
    /* function at stack[1], args after */
    TValue *func = co->stack + 1;
    vm_call(co, func, -1);
    /* results at func .. top */
    co->status = CO_DEAD;
    co->errjmp = NULL;
    L_done:
    cstack_limit = oldlimit;
    swapcontext(&cc->uc, cc->back);
    goto L_done;
  } else {
    /* error */
    co->status = CO_DEAD;
    co->errjmp = NULL;
    copyTV(&co->errval, co->top - 1);
    co->top = co->stack + 1;
    copyTV(co->top++, &co->errval);
    cstack_limit = oldlimit;
    swapcontext(&cc->uc, cc->back);
    for (;;) swapcontext(&cc->uc, cc->back);
  }
}

static ucontext_t main_uc;
static ucontext_t *cur_back;

static void co_switch_to(lua_State *L, lua_State *co) {
  CoCtx *cc = (CoCtx *)co->ctx;
  ucontext_t here;
  ucontext_t *saveback = cc->back;
  cc->back = &here;
  (void)L;
  swapcontext(&here, &cc->uc);
  cc->back = saveback;
}

/* resume co with nargs values at top of L's stack; returns status; results left on L's stack top (count in *nres via L->nresults) */
int vm_resume(lua_State *L, lua_State *co, int nargs) {
  TValue *args = L->top - nargs;
  if (co->status == CO_DEAD) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume dead coroutine");
    return LUA_ERRRUN;
  }
  if (co->status == CO_RUNNING || co == L) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume running coroutine");
    return LUA_ERRRUN;
  }
  if (co->status == CO_NORMAL) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume non-suspended coroutine");
    return LUA_ERRRUN;
  }
  /* transfer args */
  if (co->top + nargs + 10 >= co->stack + LUAI_MAXSTACK) { L->top -= nargs; vm_pushstring(L, "stack overflow"); return LUA_ERRRUN; }
  for (int i = 0; i < nargs; i++) copyTV(co->top + i, args + i);
  co->top += nargs;
  L->top -= nargs;
  co->coargs = nargs;
  co->resumer = L;
  L->status = CO_NORMAL;
  co->status = CO_RUNNING;
  G.curthread = co;
  if (!co->costarted) {
    co->costarted = 1;
    CoCtx *cc = (CoCtx *)calloc(1, sizeof(CoCtx));
    co->ctx = cc;
    co->cstacksize = CO_CSTACK_SIZE;
    co->cstack = map_anon(co->cstacksize);
    getcontext(&cc->uc);
    cc->uc.uc_stack.ss_sp = co->cstack;
    cc->uc.uc_stack.ss_size = co->cstacksize;
    cc->uc.uc_link = NULL;
    co_starting = co;
    makecontext(&cc->uc, co_entry, 0);
  }
  co_switch_to(L, co);
  G.curthread = L;
  L->status = CO_RUNNING;
  co->resumer = NULL;
  if (co->status == CO_DEAD) {
    if (!ttisnil(&co->errval) || co->top == co->stack + 2 && 0) {}
    if (co->errjmp == NULL && co->ctx && ((CoCtx *)co->ctx)->uc.uc_stack.ss_sp && co->errval.tt != T_NIL) {
      /* error */
      copyTV(L->top++, &co->errval);
      setnilV(&co->errval);
      co_free_cstack(co);
      co->errval.tt = T_NIL;
      co->status = CO_DEAD;
      L->nresults = 1;
      return LUA_ERRRUN;
    }
    /* normal finish: results at co->stack+1 .. co->top */
    {
      TValue *rb = co->stack + 1;
      int n = (int)(co->top - rb);
      checkstack(L, n + 1);
      for (int i = 0; i < n; i++) copyTV(L->top + i, rb + i);
      L->top += n;
      co->top = co->stack + 1;
      co_free_cstack(co);
      L->nresults = n;
      return LUA_OK;
    }
  }
  /* yielded: values at co->top - co->coargs */
  {
    int n = co->coargs;
    TValue *yb = co->top - n;
    checkstack(L, n + 1);
    for (int i = 0; i < n; i++) copyTV(L->top + i, yb + i);
    L->top += n;
    co->top = yb;
    L->nresults = n;
    return LUA_YIELD;
  }
}

int vm_isyieldable(lua_State *L) {
  return L != G.mainthread && L->ctx != NULL;
}

/* yield nresults values at top of co's stack; returns number of resume args placed at top */
int vm_yield(lua_State *L, int nresults) {
  if (L == G.mainthread || L->ctx == NULL) {
    err_msg(L, "attempt to yield from outside a coroutine");
  }
  CoCtx *cc = (CoCtx *)L->ctx;
  L->coargs = nresults;
  L->status = CO_SUSPENDED;
  char *oldlimit = cstack_limit;
  swapcontext(&cc->uc, cc->back);
  cstack_limit = oldlimit;
  /* resumed: args at top */
  L->status = CO_RUNNING;
  return L->coargs;
}

/* ---- init ---- */
extern char *main_cstack_base;
void vm_init(void) {
  memset(&G, 0, sizeof(G));
  gc_init();
  for (int i = 0; i < MM__MAX; i++) { G.mmnames[i] = str_newz(mm_names[i]); G.mmnames[i]->reserved = 0; }
  lua_State *L = thread_new(NULL, 0);
  G.mainthread = L; G.curthread = L;
  L->status = CO_RUNNING;
  G.registry = tab_new(0, 0);
  G.globals = tab_new(0, 0);
  L->env = G.globals;
  cstack_limit = main_cstack_base ? main_cstack_base + 512 * 1024 : NULL;
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/vm.c <<'EOF'
#define _GNU_SOURCE
#include "lua.h"
#include <stdarg.h>
#include <ucontext.h>
#include <sys/mman.h>

const char *const type_names[] = {
  "nil", "boolean", "userdata", "number", "string", "table", "function", "userdata", "thread", "proto", "upval"
};
const char *const mm_names[] = {
  "__index", "__newindex", "__gc", "__mode", "__eq", "__len", "__lt", "__le", "__concat",
  "__call", "__add", "__sub", "__mul", "__div", "__mod", "__pow", "__unm", "__metatable",
  "__tostring", "__pairs", "__ipairs"
};

const char *typename_of(const TValue *o) { return type_names[o->tt]; }

#define STACKSLOTS (LUAI_MAXSTACK + STACK_EXTRA)
#define MAXCI 70000

/* ---- stack / thread management ---- */
static void *map_anon(size_t sz) {
  void *p = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
  if (p == MAP_FAILED) { fprintf(stderr, "not enough memory\n"); exit(1); }
  return p;
}

static void thread_init_stack(lua_State *L) {
  size_t sz = sizeof(TValue) * STACKSLOTS + sizeof(CallInfo) * MAXCI;
  char *mem = (char *)map_anon(sz);
  L->stack = (TValue *)mem;
  L->stacksize = STACKSLOTS;
  L->stacklast = L->stack + STACKSLOTS;
  L->top = L->stack;
  L->cibase = (CallInfo *)(mem + sizeof(TValue) * STACKSLOTS);
  L->ciend = L->cibase + MAXCI;
  L->ci = L->cibase;
  memset(L->ci, 0, sizeof(CallInfo));
  L->ci->func = L->stack; L->ci->base = L->stack + 1; L->ci->isC = 1; L->ci->ismain = 1;
  setnilV(L->top++);  /* dummy function slot for base frame */
}

lua_State *thread_new(lua_State *parent, int iscoroutine) {
  lua_State *L = (lua_State *)mem_alloc(sizeof(lua_State));
  memset(L, 0, sizeof(lua_State));
  if (parent) gc_link((GCobj *)L, T_THREAD); else { L->gct = T_THREAD; }
  thread_init_stack(L);
  L->env = parent ? parent->env : NULL;
  L->status = CO_SUSPENDED;
  setnilV(&L->errval);
  (void)iscoroutine;
  G.totalbytes += 32768;  /* nominal accounting to trigger GC on many coroutines */
  return L;
}

void co_free_cstack(lua_State *L);
void thread_free(lua_State *L) {
  co_free_cstack(L);
  if (L->stack) munmap(L->stack, sizeof(TValue) * STACKSLOTS + sizeof(CallInfo) * MAXCI);
  G.totalbytes -= 32768;
  mem_free(L, sizeof(lua_State));
}

static inline void checkstack(lua_State *L, int n) {
  if (L->top + n >= L->stack + LUAI_MAXSTACK) {
    err_run(L, "stack overflow");
  }
}
void err_check_stack(lua_State *L, int n) { checkstack(L, n); }

void vm_settop(lua_State *L, TValue *top) { L->top = top; }
void vm_push(lua_State *L, const TValue *v) { copyTV(L->top, v); L->top++; }
void vm_pushnum(lua_State *L, double n) { setnumV(L->top, n); L->top++; }
void vm_pushbool(lua_State *L, int b) { setboolV(L->top, b); L->top++; }
void vm_pushnil(lua_State *L) { setnilV(L->top); L->top++; }
void vm_pushtab(lua_State *L, Table *t) { settabV(L->top, t); L->top++; }
void vm_pushfunc(lua_State *L, Closure *c) { setfuncV(L->top, c); L->top++; }
void vm_pushstr(lua_State *L, GCstr *s) { setstrV(L->top, s); L->top++; }
void vm_pushlstring(lua_State *L, const char *s, size_t len) { vm_pushstr(L, str_new(s, len)); }
void vm_pushstring(lua_State *L, const char *s) { vm_pushstr(L, str_newz(s)); }
void vm_pushfstring(lua_State *L, const char *fmt, ...) {
  char buf[1024]; va_list ap;
  va_start(ap, fmt); int n = vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  if (n < (int)sizeof(buf)) { vm_pushlstring(L, buf, n); return; }
  char *big = (char *)malloc(n + 1);
  va_start(ap, fmt); vsnprintf(big, n + 1, fmt, ap); va_end(ap);
  vm_pushlstring(L, big, n); free(big);
}

/* ---- objects ---- */
Proto *proto_new(void) {
  Proto *p = (Proto *)mem_alloc(sizeof(Proto));
  memset(p, 0, sizeof(Proto));
  gc_link((GCobj *)p, T_PROTO);
  return p;
}
void *proto_alloc(Proto *p, size_t sz) {
  void *m = malloc(sz);
  if (p->nallocs == p->alloccap) { p->alloccap = p->alloccap ? p->alloccap * 2 : 64; p->allocs = (void **)realloc(p->allocs, p->alloccap * sizeof(void *)); }
  p->allocs[p->nallocs++] = m;
  G.totalbytes += sz;
  return m;
}
void proto_addconst(Proto *p, GCstr *s) {
  if (p->nconsts == p->constcap) { p->constcap = p->constcap ? p->constcap * 2 : 16; p->consts = (GCstr **)realloc(p->consts, p->constcap * sizeof(GCstr *)); }
  p->consts[p->nconsts++] = s;
}
void proto_free(Proto *p) {
  for (int i = 0; i < p->nallocs; i++) free(p->allocs[i]);
  free(p->allocs); free(p->consts); free(p->children); free(p->upvals); free(p->paramnames);
  mem_free(p, sizeof(Proto));
}

Closure *func_newL(Proto *p, Table *env) {
  Closure *c = (Closure *)mem_alloc(sizeof(Closure) + sizeof(UpVal *) * p->nupvals);
  c->isC = 0; c->nupvals = p->nupvals; c->env = env;
  c->u.l.p = p; c->u.l.upvals = (UpVal **)(c + 1);
  for (int i = 0; i < p->nupvals; i++) c->u.l.upvals[i] = NULL;
  gc_link((GCobj *)c, T_FUNCTION);
  return c;
}
Closure *func_newC(CFunction f, int nupvals, Table *env) {
  Closure *c = (Closure *)mem_alloc(sizeof(Closure) + sizeof(TValue) * nupvals);
  c->isC = 1; c->nupvals = nupvals; c->env = env;
  c->u.c.f = f; c->u.c.name = NULL; c->u.c.builtin = 0; c->u.c.upvals = (TValue *)(c + 1);
  for (int i = 0; i < nupvals; i++) setnilV(&c->u.c.upvals[i]);
  gc_link((GCobj *)c, T_FUNCTION);
  return c;
}
Udata *udata_new(size_t sz, Table *env) {
  Udata *u = (Udata *)mem_alloc(sizeof(Udata) + sz);
  u->metatable = NULL; u->env = env; u->len = sz; u->payload = (void *)(u + 1); u->has_gc = 0;
  memset(u->payload, 0, sz);
  gc_link((GCobj *)u, T_USERDATA);
  return u;
}

UpVal *func_findupval(lua_State *L, TValue *level) {
  UpVal **pp = &L->openupval, *p;
  while ((p = *pp) != NULL && p->v >= level) {
    if (p->v == level) return p;
    pp = &p->nextopen;
  }
  UpVal *uv = (UpVal *)mem_alloc(sizeof(UpVal));
  uv->v = level; setnilV(&uv->closed); uv->level = 0;
  uv->nextopen = *pp; *pp = uv;
  gc_link((GCobj *)uv, T_UPVAL);
  return uv;
}
void func_closeupvals(lua_State *L, TValue *level) {
  UpVal *uv;
  while ((uv = L->openupval) != NULL && uv->v >= level) {
    L->openupval = uv->nextopen;
    copyTV(&uv->closed, uv->v);
    uv->v = &uv->closed;
  }
}

/* ---- errors ---- */
void vm_throw(lua_State *L, int status) {
  if (L->errjmp) {
    L->errjmp->status = status;
    longjmp(L->errjmp->jb, 1);
  }
  /* no handler: print and exit */
  {
    GCstr *s = vm_tostring_basic(L->top - 1);
    fprintf(stderr, "PANIC: unprotected error in call to Lua API (%s)\n", str_data(s));
    exit(1);
  }
}

void vm_error(lua_State *L) { vm_throw(L, LUA_ERRRUN); }

GCstr *vm_shortsrc(GCstr *source) {
  const char *s = str_data(source);
  char buf[128];
  if (s[0] == '=') { snprintf(buf, 60, "%s", s + 1); return str_newz(buf); }
  if (s[0] == '@') {
    size_t len = source->len - 1;
    if (len <= 59) return str_new(s + 1, len);
    snprintf(buf, sizeof(buf), "...%s", s + 1 + (len - 56));
    return str_newz(buf);
  }
  /* string chunk: [string "..."] */
  {
    const char *nl = strchr(s, '\n');
    size_t len = nl ? (size_t)(nl - s) : source->len;
    if (len > 60 - 15 || nl) {
      size_t take = len;
      if (take > 60 - 15) take = 60 - 15;
      snprintf(buf, sizeof(buf), "[string \"%.*s...\"]", (int)take, s);
    } else snprintf(buf, sizeof(buf), "[string \"%s\"]", s);
    return str_newz(buf);
  }
}

CallInfo *vm_getframe(lua_State *L, int level) {
  CallInfo *ci = L->ci - level;
  if (ci <= L->cibase) return NULL;
  return ci;
}

GCstr *vm_where(lua_State *L, int level) {
  CallInfo *ci = L->ci - level;
  if (ci > L->cibase && !ci->isC && ci->cl) {
    GCstr *src = vm_shortsrc(ci->cl->u.l.p->source);
    return str_fmt("%s:%d:", str_data(src), ci->curline);
  }
  return str_new("", 0);
}

void err_run(lua_State *L, const char *fmt, ...) {
  char buf[1024]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  GCstr *w = vm_where(L, 0);
  vm_pushfstring(L, "%s %s", str_data(w), buf);
  /* fix: vm_where returns "src:line:" and we want "src:line: msg"; if empty, no space */
  if (w->len == 0) { L->top--; vm_pushstring(L, buf); }
  else { L->top--; vm_pushfstring(L, "%s %s", str_data(w), buf); }
  vm_throw(L, LUA_ERRRUN);
}

void err_msg(lua_State *L, const char *fmt, ...) {
  char buf[1024]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  vm_pushstring(L, buf);
  vm_throw(L, LUA_ERRRUN);
}

/* error raised by a C function: position from caller Lua frame */
void err_callermsg(lua_State *L, const char *msg) {
  CallInfo *ci = L->ci;
  CallInfo *caller = ci - 1;
  if (caller > L->cibase && !caller->isC && caller->cl) {
    GCstr *src = vm_shortsrc(caller->cl->u.l.p->source);
    vm_pushfstring(L, "%s:%d: %s", str_data(src), caller->curline, msg);
  } else vm_pushstring(L, msg);
  vm_throw(L, LUA_ERRRUN);
}

static const char *expr_name(const Expr *e, const char **what) {
  while (e && e->kind == E_PAREN) e = e->u.un.e;
  if (!e) return NULL;
  switch (e->kind) {
  case E_GLOBAL: *what = "global"; return str_data(e->u.str);
  case E_LOCAL: *what = "local"; return str_data(e->u.var.name);
  case E_UPVAL: *what = "upvalue"; return str_data(e->u.var.name);
  case E_INDEX:
    if (e->u.index.key->kind == E_STRING) { *what = "field"; return str_data(e->u.index.key->u.str); }
    return NULL;
  case E_METHOD: *what = "method"; return str_data(e->u.call.name);
  default: return NULL;
  }
}

/* name of function running in frame ci, derived from the frame below */
int vm_getinfo_name(lua_State *L, CallInfo *ci, const char **name, const char **namewhat) {
  CallInfo *below = ci - 1;
  *name = NULL; *namewhat = "";
  if (ci->tailcalled) return 0;
  if (below < L->cibase) return 0;
  if (below->isC) return 0;
  if (below->curmm) { *name = below->curmm; *namewhat = "metamethod"; return 1; }
  if (below->curforgen) { *name = "(for generator)"; *namewhat = "for iterator"; return 1; }
  if (below->curcall) {
    const Expr *ce = below->curcall;
    const char *what = NULL, *n = NULL;
    if (ce->kind == E_METHOD) { *name = str_data(ce->u.call.name); *namewhat = "method"; return 1; }
    if (ce->kind == E_CALL) n = expr_name(ce->u.call.fn, &what);
    if (n) { *name = n; *namewhat = what; return 1; }
  }
  return 0;
}

void err_arg(lua_State *L, int narg, const char *msg) {
  const char *name, *what;
  char buf[1024];
  vm_getinfo_name(L, L->ci, &name, &what);
  if (name && strcmp(what, "method") == 0) {
    narg--;
    if (narg == 0) { snprintf(buf, sizeof(buf), "calling '%s' on bad self (%s)", name, msg); err_callermsg(L, buf); }
  }
  snprintf(buf, sizeof(buf), "bad argument #%d to '%s' (%s)", narg, name ? name : "?", msg);
  err_callermsg(L, buf);
}

void err_argtype(lua_State *L, int narg, const char *expected) {
  char buf[256];
  TValue *o = L->ci->base + narg - 1;
  const char *got = (o < L->top) ? typename_of(o) : "no value";
  snprintf(buf, sizeof(buf), "%s expected, got %s", expected, got);
  err_arg(L, narg, buf);
}

/* ---- metatables ---- */
Table *vm_getmetatable(const TValue *o) {
  switch (o->tt) {
  case T_TABLE: return tabV(o)->metatable;
  case T_USERDATA: return udataV(o)->metatable;
  case T_STRING: return G.strmt;
  default: return G.basemt[o->tt];
  }
}

const TValue *vm_getmetamethod(const TValue *o, int mm) {
  Table *mt = vm_getmetatable(o);
  if (!mt) return NILOBJ;
  return tab_getstr(mt, G.mmnames[mm]);
}

static inline const TValue *tab_getmm(Table *mt, int mm) {
  if (!mt) return NILOBJ;
  return tab_getstr(mt, G.mmnames[mm]);
}

/* ---- conversions ---- */
int vm_tonumber(const TValue *o, TValue *out) {
  if (ttisnumber(o)) { copyTV(out, o); return 1; }
  if (ttisstring(o)) {
    double n;
    if (str2num(str_data(strV(o)), strV(o)->len, &n)) { setnumV(out, n); return 1; }
  }
  return 0;
}

GCstr *vm_tostring_basic(const TValue *o) {
  char buf[64];
  switch (o->tt) {
  case T_NIL: return str_newz("nil");
  case T_BOOLEAN: return str_newz(boolV(o) ? "true" : "false");
  case T_NUMBER: return num2strobj(numV(o));
  case T_STRING: return strV(o);
  case T_FUNCTION: {
    Closure *c = funcV(o);
    if (c->isC && c->u.c.builtin) { sprintf(buf, "function: builtin#%d", c->u.c.builtin); return str_newz(buf); }
    sprintf(buf, "function: %p", (void *)c); return str_newz(buf);
  }
  case T_TABLE: sprintf(buf, "table: %p", (void *)tabV(o)); return str_newz(buf);
  case T_USERDATA: sprintf(buf, "userdata: %p", (void *)udataV(o)); return str_newz(buf);
  case T_THREAD: sprintf(buf, "thread: %p", (void *)threadV(o)); return str_newz(buf);
  case T_LIGHTUD: sprintf(buf, "userdata: %p", o->u.p); return str_newz(buf);
  default: return str_newz("?");
  }
}

static void call_mm(lua_State *L, const TValue *f, const char *mmname, int nargs, int nresults, const TValue *a, const TValue *b, const TValue *c);

GCstr *vm_tostring(lua_State *L, const TValue *o) {
  const TValue *mm = vm_getmetamethod(o, MM_TOSTRING);
  if (!ttisnil(mm)) {
    TValue obj = *o;
    call_mm(L, mm, "__tostring", 1, 1, &obj, NULL, NULL);
    L->top--;
    GCstr *s = vm_tostring_basic(L->top);
    return s;
  }
  return vm_tostring_basic(o);
}

/* ---- calls ---- */
static void exec_function(lua_State *L, CallInfo *ci);

static void adjust_results(lua_State *L, TValue *func, TValue *resbase, int nres, int nresults) {
  int i;
  if (nresults < 0) {
    if (resbase != func) for (i = 0; i < nres; i++) copyTV(func + i, resbase + i);
    L->top = func + nres;
  } else {
    int n = nres < nresults ? nres : nresults;
    if (resbase != func) for (i = 0; i < n; i++) copyTV(func + i, resbase + i);
    for (i = n; i < nresults; i++) setnilV(func + i);
    L->top = func + nresults;
  }
}

static void err_call(lua_State *L, const TValue *func) {
  const Expr *ce = L->ci->curcall;
  const char *what = NULL, *name = NULL;
  if (ce && ce->kind == E_METHOD) { what = "method"; name = str_data(ce->u.call.name); }
  else if (ce && ce->kind == E_CALL) name = expr_name(ce->u.call.fn, &what);
  if (name) err_run(L, "attempt to call %s '%s' (a %s value)", what, name, typename_of(func));
  err_run(L, "attempt to call a %s value", typename_of(func));
}

static char *cstack_limit;

void vm_call(lua_State *L, TValue *func, int nresults) {
  int nargs;
  Closure *cl;
  CallInfo *ci;
  int tail = 0;
  char probe;
  if (&probe < cstack_limit) { L->ci->curline = L->ci->curline; err_run(L, "stack overflow"); }
reentry:
  nargs = (int)(L->top - func - 1);
  if (!ttisfunction(func)) {
    const TValue *mm = vm_getmetamethod(func, MM_CALL);
    if (ttisnil(mm)) err_call(L, func);
    /* insert func as first argument */
    checkstack(L, 1);
    for (TValue *p = L->top; p > func; p--) copyTV(p, p - 1);
    L->top++;
    copyTV(func, mm);
    nargs++;
  }
  cl = funcV(func);
  if (L->ci + 1 >= L->ciend) err_run(L, "stack overflow");
  if (L->top + 40 >= L->stack + LUAI_MAXSTACK) err_run(L, "stack overflow");
  ci = ++L->ci;
  ci->func = func; ci->cl = cl; ci->curline = 0; ci->curcall = NULL; ci->curmm = NULL;
  ci->tailcalled = (uint8_t)tail; ci->curforgen = 0; ci->ismain = 0; ci->ispcall = 0; ci->retbase = NULL;
  ci->nvarargs = 0; ci->varargs = NULL;
  if (cl->isC) {
    ci->isC = 1;
    ci->base = func + 1;
    ci->top = L->top;
    int n = cl->u.c.f(L);
    /* results are the last n values on the stack */
    TValue *resbase = L->top - n;
    L->ci = ci - 1;
    adjust_results(L, func, resbase, n, nresults);
    return;
  }
  ci->isC = 0;
  {
    Proto *p = cl->u.l.p;
    TValue *base;
    if (p->isvararg) {
      int nfix = p->nparams;
      base = L->top;
      if (nargs < nfix) { for (int i = nargs; i < nfix; i++) setnilV(L->top++); nargs = nfix; base = L->top; }
      /* copy fixed params up; varargs stay */
      for (int i = 0; i < nfix; i++) { copyTV(base + i, func + 1 + i); setnilV(func + 1 + i); }
      ci->varargs = func + 1 + nfix;
      ci->nvarargs = nargs - nfix;
      ci->base = base;
      L->top = base + nfix;
    } else {
      base = func + 1;
      ci->base = base;
      for (int i = nargs; i < p->nparams; i++) setnilV(func + 1 + i);
      L->top = base + p->nparams;
    }
    if (L->top + p->nslots + 20 >= L->stack + LUAI_MAXSTACK) { L->ci = ci - 1; err_run(L, "stack overflow"); }
    for (int i = (int)(L->top - base); i < p->nslots; i++) setnilV(base + i);
    L->top = base + p->nslots;
    exec_function(L, ci);
    /* ci->retbase..L->top are results, or tail call pending (retbase points at function) */
    if (ci->retbase && ci->retbase->tt == T_NIL && 0) {}
    if (L->nresults == -2) {
      /* tail call: function at ci->retbase, args above */
      TValue *nf = ci->retbase;
      int n = (int)(L->top - nf);
      func_closeupvals(L, base);
      for (int i = 0; i < n; i++) copyTV(func + i, nf + i);
      L->top = func + n;
      L->ci = ci - 1;
      tail = 1;
      goto reentry;
    }
    {
      TValue *rb = ci->retbase ? ci->retbase : L->top;
      int nres = (int)(L->top - rb);
      func_closeupvals(L, base);
      L->ci = ci - 1;
      adjust_results(L, func, rb, nres, nresults);
    }
  }
}

int vm_pcall(lua_State *L, TValue *func, int nresults, ErrorJmp *ej) {
  CallInfo *saveci = L->ci;
  int oldncalls = L->ncalls;
  ej->prev = L->errjmp; ej->status = 0; ej->top = func;
  L->errjmp = ej;
  if (setjmp(ej->jb) == 0) {
    vm_call(L, func, nresults);
    L->errjmp = ej->prev;
    return LUA_OK;
  }
  /* error: error value at L->top-1 */
  {
    TValue err = *(L->top - 1);
    L->errjmp = ej->prev;
    L->ci = saveci;
    L->ncalls = oldncalls;
    func_closeupvals(L, func);
    L->top = func;
    copyTV(L->top++, &err);
    return ej->status ? ej->status : LUA_ERRRUN;
  }
}

/* call metamethod f with args, leave nresults on stack top */
static void call_mm(lua_State *L, const TValue *f, const char *mmname, int nargs, int nresults, const TValue *a, const TValue *b, const TValue *c) {
  TValue *base = L->top;
  checkstack(L, 4);
  copyTV(L->top++, f);
  if (nargs >= 1) copyTV(L->top++, a);
  if (nargs >= 2) copyTV(L->top++, b);
  if (nargs >= 3) copyTV(L->top++, c);
  const char *savemm = L->ci->curmm;
  const Expr *savecall = L->ci->curcall;
  L->ci->curmm = mmname; L->ci->curcall = NULL;
  vm_call(L, base, nresults);
  L->ci->curmm = savemm; L->ci->curcall = savecall;
}

/* ---- indexing ---- */
static void err_index(lua_State *L, const TValue *obj, const Expr *e) {
  const char *what = NULL, *name = NULL;
  if (e) name = expr_name(e, &what);
  if (name) err_run(L, "attempt to index %s '%s' (a %s value)", what, name, typename_of(obj));
  err_run(L, "attempt to index a %s value", typename_of(obj));
}

/* obj[key] with metamethods; result stored in *out (which must not alias stack top concerns) */
static void index_value(lua_State *L, const TValue *obj, const TValue *key, TValue *out, const Expr *objexpr) {
  TValue o = *obj;
  TValue k = *key;
  for (int loop = 0; loop < 100; loop++) {
    const TValue *mm;
    if (ttistable(&o)) {
      Table *t = tabV(&o);
      const TValue *v = tab_get(t, &k);
      if (!ttisnil(v)) { copyTV(out, v); return; }
      mm = tab_getmm(t->metatable, MM_INDEX);
      if (ttisnil(mm)) { setnilV(out); return; }
    } else {
      mm = vm_getmetamethod(&o, MM_INDEX);
      if (ttisnil(mm)) err_index(L, &o, loop == 0 ? objexpr : NULL);
    }
    if (ttisfunction(mm)) {
      call_mm(L, mm, "__index", 2, 1, &o, &k, NULL);
      L->top--;
      copyTV(out, L->top);
      return;
    }
    o = *mm;
  }
  err_run(L, "loop in gettable");
}

const TValue *vm_index(lua_State *L, const TValue *obj, const TValue *key, TValue *out) {
  index_value(L, obj, key, out, NULL);
  return out;
}

static void setindex_value(lua_State *L, const TValue *obj, const TValue *key, const TValue *val, const Expr *objexpr) {
  TValue o = *obj;
  TValue k = *key, v = *val;
  for (int loop = 0; loop < 100; loop++) {
    const TValue *mm;
    if (ttistable(&o)) {
      Table *t = tabV(&o);
      const TValue *slot = tab_get(t, &k);
      if (!ttisnil(slot)) { copyTV((TValue *)slot, &v); return; }
      mm = tab_getmm(t->metatable, MM_NEWINDEX);
      if (ttisnil(mm)) {
        TValue *s = tab_set(L, t, &k);
        copyTV(s, &v);
        return;
      }
    } else {
      mm = vm_getmetamethod(&o, MM_NEWINDEX);
      if (ttisnil(mm)) err_index(L, &o, loop == 0 ? objexpr : NULL);
    }
    if (ttisfunction(mm)) {
      call_mm(L, mm, "__newindex", 3, 0, &o, &k, &v);
      return;
    }
    o = *mm;
  }
  err_run(L, "loop in settable");
}

void vm_setindex(lua_State *L, const TValue *obj, const TValue *key, const TValue *val) {
  setindex_value(L, obj, key, val, NULL);
}

/* ---- arithmetic ---- */
double lua_fmod(double a, double b) {
  double m = fmod(a, b);
  if (m != 0 && (m ^ 0, (m < 0) != (b < 0))) m += b;
  return m;
}
static inline double lmod(double a, double b) {
  /* LuaJIT: a - floor(a/b)*b */
  double m = fmod(a, b);
  if ((m > 0 && b < 0) || (m < 0 && b > 0)) m += b;
  if (b == 0 || isinf(b)) return a - floor(a / b) * b;
  return m;
}

static inline double arith_op(int op, double a, double b) {
  switch (op) {
  case OP_ADD: return a + b;
  case OP_SUB: return a - b;
  case OP_MUL: return a * b;
  case OP_DIV: return a / b;
  case OP_MOD: return lmod(a, b);
  case OP_POW: return pow(a, b);
  default: return 0;
  }
}

static int arith_mm[] = { MM_ADD, MM_SUB, MM_MUL, MM_DIV, MM_MOD, MM_POW };

static void err_optype(lua_State *L, const TValue *o, const Expr *e, const char *opmsg) {
  const char *what = NULL, *name = NULL;
  if (e) name = expr_name(e, &what);
  if (name) err_run(L, "attempt to %s %s '%s' (a %s value)", opmsg, what, name, typename_of(o));
  err_run(L, "attempt to %s a %s value", opmsg, typename_of(o));
}

void vm_arith(lua_State *L, int op, const TValue *a, const TValue *b, TValue *out, const Expr *ea, const Expr *eb) {
  TValue na, nb;
  if (vm_tonumber(a, &na) && vm_tonumber(b, &nb)) { setnumV(out, arith_op(op, numV(&na), numV(&nb))); return; }
  {
    int mm = arith_mm[op];
    const TValue *f = vm_getmetamethod(a, mm);
    if (ttisnil(f)) {
      f = vm_getmetamethod(b, mm);
      if (ttisnil(f)) {
        if (!vm_tonumber(a, &na)) err_optype(L, a, ea, "perform arithmetic on");
        err_optype(L, b, eb, "perform arithmetic on");
      }
    }
    TValue ta = *a, tb = *b;
    call_mm(L, f, mm_names[mm], 2, 1, &ta, &tb, NULL);
    L->top--;
    copyTV(out, L->top);
  }
}

static void vm_unm(lua_State *L, const TValue *a, TValue *out, const Expr *ea) {
  TValue na;
  if (vm_tonumber(a, &na)) { setnumV(out, -numV(&na)); return; }
  const TValue *f = vm_getmetamethod(a, MM_UNM);
  if (ttisnil(f)) err_optype(L, a, ea, "perform arithmetic on");
  TValue ta = *a;
  call_mm(L, f, "__unm", 2, 1, &ta, &ta, NULL);
  L->top--;
  copyTV(out, L->top);
}

static void vm_len(lua_State *L, const TValue *a, TValue *out, const Expr *ea) {
  if (ttisstring(a)) { setnumV(out, (double)strV(a)->len); return; }
  if (ttistable(a)) { setnumV(out, (double)tab_len(tabV(a))); return; }
  const TValue *f = vm_getmetamethod(a, MM_LEN);
  if (ttisnil(f)) err_optype(L, a, ea, "get length of");
  TValue ta = *a;
  call_mm(L, f, "__len", 2, 1, &ta, &ta, NULL);
  L->top--;
  copyTV(out, L->top);
}

/* ---- comparison ---- */
int vm_equal(lua_State *L, const TValue *a, const TValue *b) {
  if (a->tt != b->tt) return 0;
  switch (a->tt) {
  case T_NIL: return 1;
  case T_BOOLEAN: return boolV(a) == boolV(b);
  case T_NUMBER: return numV(a) == numV(b);
  case T_LIGHTUD: return a->u.p == b->u.p;
  case T_TABLE: case T_USERDATA: {
    if (a->u.gc == b->u.gc) return 1;
    const TValue *ma = vm_getmetamethod(a, MM_EQ);
    if (ttisnil(ma)) return 0;
    const TValue *mb = vm_getmetamethod(b, MM_EQ);
    if (ttisnil(mb)) return 0;
    if (!lua_rawequal(ma, mb)) return 0;
    TValue ta = *a, tb = *b;
    call_mm(L, ma, "__eq", 2, 1, &ta, &tb, NULL);
    L->top--;
    return !isfalse(L->top);
  }
  default: return a->u.gc == b->u.gc;
  }
}

static void err_compare(lua_State *L, const TValue *a, const TValue *b) {
  const char *t1 = typename_of(a), *t2 = typename_of(b);
  if (strcmp(t1, t2) == 0) err_run(L, "attempt to compare two %s values", t1);
  err_run(L, "attempt to compare %s with %s", t1, t2);
}

static int call_orderTM(lua_State *L, const TValue *a, const TValue *b, int mm) {
  const TValue *ma = vm_getmetamethod(a, mm);
  if (ttisnil(ma)) return -1;
  const TValue *mb = vm_getmetamethod(b, mm);
  if (ttisnil(mb)) return -1;
  if (!lua_rawequal(ma, mb)) return -1;
  TValue ta = *a, tb = *b;
  call_mm(L, ma, mm_names[mm], 2, 1, &ta, &tb, NULL);
  L->top--;
  return !isfalse(L->top);
}

int vm_lessthan(lua_State *L, const TValue *a, const TValue *b) {
  if (ttisnumber(a) && ttisnumber(b)) return numV(a) < numV(b);
  if (ttisstring(a) && ttisstring(b)) return str_cmp(strV(a), strV(b)) < 0;
  if (a->tt == b->tt) {
    int r = call_orderTM(L, a, b, MM_LT);
    if (r >= 0) return r;
  }
  err_compare(L, a, b);
  return 0;
}

int vm_lessequal(lua_State *L, const TValue *a, const TValue *b) {
  if (ttisnumber(a) && ttisnumber(b)) return numV(a) <= numV(b);
  if (ttisstring(a) && ttisstring(b)) return str_cmp(strV(a), strV(b)) <= 0;
  if (a->tt == b->tt) {
    int r = call_orderTM(L, a, b, MM_LE);
    if (r >= 0) return r;
    r = call_orderTM(L, b, a, MM_LT);
    if (r >= 0) return !r;
  }
  err_compare(L, a, b);
  return 0;
}

/* ---- concat ---- */
static inline int tostr_concat(const TValue *o, GCstr **s, char *buf, size_t *len, const char **data) {
  if (ttisstring(o)) { *s = strV(o); *data = str_data(*s); *len = (*s)->len; return 1; }
  if (ttisnumber(o)) { *len = num2str(buf, numV(o)); *data = buf; *s = NULL; return 1; }
  return 0;
}

/* concatenate `total` values at top of stack (right to left), leaving one value. exprs for naming may be NULL */
static void concat_values(lua_State *L, int total, const Expr *const *exprs) {
  /* values at L->top - total .. L->top - 1 */
  while (total > 1) {
    TValue *top = L->top;
    TValue *r = top - 1, *l = top - 2;
    GCstr *ls, *rs; char lbuf[64], rbuf[64]; size_t llen, rlen; const char *ld, *rd;
    if (!tostr_concat(l, &ls, lbuf, &llen, &ld) || !tostr_concat(r, &rs, rbuf, &rlen, &rd)) {
      const TValue *f = vm_getmetamethod(l, MM_CONCAT);
      if (ttisnil(f)) f = vm_getmetamethod(r, MM_CONCAT);
      if (ttisnil(f)) {
        int idx;
        const TValue *bad;
        if (!(ttisstring(l) || ttisnumber(l))) { bad = l; idx = (int)(l - (top - total)); }
        else { bad = r; idx = (int)(r - (top - total)); }
        const Expr *e = exprs ? exprs[(int)(L->top - total) + 0 == 0 ? idx : idx] : NULL;
        (void)e;
        err_optype(L, bad, exprs ? exprs[idx] : NULL, "concatenate");
      }
      TValue tl = *l, tr = *r;
      call_mm(L, f, "__concat", 2, 1, &tl, &tr, NULL);
      L->top--;
      copyTV(l, L->top);
      L->top = top - 1;
      total--;
      continue;
    }
    /* collect as many consecutive string/number values from the right as possible */
    {
      int n = 2; size_t tl = llen + rlen;
      while (n < total) {
        TValue *o = top - n - 1;
        GCstr *s; char b[64]; size_t len; const char *d;
        if (!tostr_concat(o, &s, b, &len, &d)) break;
        tl += len; n++;
      }
      if (tl >= 0x7fffff00u) err_run(L, "string length overflow");
      char *buf = (char *)malloc(tl + 1);
      char *p = buf;
      for (int i = n; i >= 1; i--) {
        TValue *o = top - i;
        if (ttisstring(o)) { memcpy(p, str_data(strV(o)), strV(o)->len); p += strV(o)->len; }
        else { p += num2str(p, numV(o)); }
      }
      GCstr *res = str_new(buf, tl);
      free(buf);
      setstrV(top - n, res);
      L->top = top - n + 1;
      total -= n - 1;
    }
  }
}

void vm_concat(lua_State *L, int total) { concat_values(L, total, NULL); }

/* ---- interpreter ---- */
enum { EX_NORMAL = 0, EX_BREAK, EX_RETURN, EX_GOTO };

static int exec_block(lua_State *L, CallInfo *ci, const Block *b, const Stmt **gototarget);
static void eval(lua_State *L, CallInfo *ci, const Expr *e);
static int eval_multi(lua_State *L, CallInfo *ci, const Expr *e);

static const Stmt *pending_goto;  /* goto statement being propagated */

#define SLOT(ci, i) ((ci)->base + (i))

static inline void push_closure(lua_State *L, CallInfo *ci, const Expr *e) {
  Proto *p = ci->cl->u.l.p->children[e->u.idx];
  Closure *c = func_newL(p, ci->cl->env);
  setfuncV(L->top, c); L->top++;   /* anchor before creating upvalues */
  for (int i = 0; i < p->nupvals; i++) {
    UpvalDesc *d = &p->upvals[i];
    if (d->instack) c->u.l.upvals[i] = func_findupval(L, ci->base + d->idx);
    else c->u.l.upvals[i] = ci->cl->u.l.upvals[d->idx];
  }
}

static void eval_call(lua_State *L, CallInfo *ci, const Expr *e, int nresults) {
  TValue *func = L->top;
  checkstack(L, e->u.call.nargs + 3);
  if (e->kind == E_METHOD) {
    eval(L, ci, e->u.call.fn);           /* object */
    TValue *obj = L->top - 1;
    TValue key; setstrV(&key, e->u.call.name);
    TValue method;
    ci->curline = e->line;
    index_value(L, obj, &key, &method, e->u.call.fn);
    /* arrange: func = method, arg1 = obj */
    copyTV(L->top, obj); L->top++;
    copyTV(func, &method);
  } else {
    eval(L, ci, e->u.call.fn);
  }
  for (int i = 0; i < e->u.call.nargs; i++) {
    const Expr *a = e->u.call.args[i];
    if (i == e->u.call.nargs - 1) eval_multi(L, ci, a);
    else eval(L, ci, a);
  }
  ci->curline = e->line;
  ci->curcall = e;
  vm_call(L, func, nresults);
  ci->curcall = NULL;
}

static int eval_multi(lua_State *L, CallInfo *ci, const Expr *e) {
  switch (e->kind) {
  case E_CALL: case E_METHOD: {
    TValue *base = L->top;
    eval_call(L, ci, e, -1);
    return (int)(L->top - base);
  }
  case E_VARARG: {
    int n = ci->nvarargs;
    checkstack(L, n + 1);
    for (int i = 0; i < n; i++) copyTV(L->top + i, ci->varargs + i);
    L->top += n;
    return n;
  }
  default:
    eval(L, ci, e);
    return 1;
  }
}

static void eval_table(lua_State *L, CallInfo *ci, const Expr *e) {
  Table *t = tab_new(e->u.tab.narray, e->u.tab.nhash);
  TValue *tv = L->top;
  settabV(L->top, t); L->top++;
  int ai = 1;
  for (int i = 0; i < e->u.tab.nitems; i++) {
    const TabItem *it = &e->u.tab.items[i];
    if (it->key) {
      eval(L, ci, it->key);
      eval(L, ci, it->val);
      TValue *k = L->top - 2, *v = L->top - 1;
      if (ttisnil(k)) { ci->curline = it->val->line; err_run(L, "table index is nil"); }
      if (ttisnumber(k) && isnan(numV(k))) { ci->curline = it->val->line; err_run(L, "table index is NaN"); }
      TValue *slot = tab_set(L, t, k);
      copyTV(slot, v);
      L->top -= 2;
    } else {
      if (i == e->u.tab.nitems - 1 && (it->val->kind == E_CALL || it->val->kind == E_METHOD || it->val->kind == E_VARARG)) {
        int n = eval_multi(L, ci, it->val);
        TValue *vals = L->top - n;
        if (n > 0 && (uint32_t)(ai + n - 1) > t->asize) tab_resize(L, t, ai + n - 1, t->node && t->lsizenode ? (1u << t->lsizenode) : 0);
        for (int j = 0; j < n; j++) {
          TValue *slot = tab_setint(L, t, ai++);
          copyTV(slot, vals + j);
        }
        L->top = vals;
      } else {
        eval(L, ci, it->val);
        TValue *slot = tab_setint(L, t, ai++);
        copyTV(slot, L->top - 1);
        L->top--;
      }
    }
  }
  (void)tv;
}

static void eval(lua_State *L, CallInfo *ci, const Expr *e) {
  switch (e->kind) {
  case E_NIL: setnilV(L->top); L->top++; return;
  case E_TRUE: setboolV(L->top, 1); L->top++; return;
  case E_FALSE: setboolV(L->top, 0); L->top++; return;
  case E_NUMBER: setnumV(L->top, e->u.num); L->top++; return;
  case E_STRING: setstrV(L->top, e->u.str); L->top++; return;
  case E_VARARG:
    if (ci->nvarargs > 0) copyTV(L->top, ci->varargs); else setnilV(L->top);
    L->top++; return;
  case E_FUNCTION: push_closure(L, ci, e); return;
  case E_LOCAL: copyTV(L->top, SLOT(ci, e->u.var.idx)); L->top++; return;
  case E_UPVAL: copyTV(L->top, ci->cl->u.l.upvals[e->u.var.idx]->v); L->top++; return;
  case E_GLOBAL: {
    TValue key; setstrV(&key, e->u.str);
    TValue env; settabV(&env, ci->cl->env);
    const TValue *v = tab_getstr(ci->cl->env, e->u.str);
    if (!ttisnil(v) || ci->cl->env->metatable == NULL) { copyTV(L->top, v); L->top++; return; }
    ci->curline = e->line;
    index_value(L, &env, &key, L->top, NULL);
    L->top++;
    return;
  }
  case E_INDEX: {
    eval(L, ci, e->u.index.obj);
    eval(L, ci, e->u.index.key);
    TValue *obj = L->top - 2, *key = L->top - 1;
    if (ttistable(obj)) {
      const TValue *v = tab_get(tabV(obj), key);
      if (!ttisnil(v) || tabV(obj)->metatable == NULL) { copyTV(obj, v); L->top--; return; }
    }
    ci->curline = e->line;
    TValue out;
    index_value(L, obj, key, &out, e->u.index.obj);
    copyTV(obj, &out);
    L->top--;
    return;
  }
  case E_CALL: case E_METHOD:
    eval_call(L, ci, e, 1);
    return;
  case E_PAREN: {
    TValue *base = L->top;
    eval_multi(L, ci, e->u.un.e);
    if (L->top == base) { setnilV(L->top); L->top++; }
    else L->top = base + 1;
    return;
  }
  case E_AND: {
    eval(L, ci, e->u.bin.a);
    if (isfalse(L->top - 1)) return;
    L->top--;
    eval(L, ci, e->u.bin.b);
    return;
  }
  case E_OR: {
    eval(L, ci, e->u.bin.a);
    if (!isfalse(L->top - 1)) return;
    L->top--;
    eval(L, ci, e->u.bin.b);
    return;
  }
  case E_UNOP: {
    eval(L, ci, e->u.un.e);
    TValue *a = L->top - 1;
    switch (e->op) {
    case OPU_NOT: setboolV(a, isfalse(a)); return;
    case OPU_NEG:
      if (ttisnumber(a)) { a->u.n = -a->u.n; return; }
      ci->curline = e->line;
      { TValue out; vm_unm(L, a, &out, e->u.un.e); copyTV(L->top - 1, &out); }
      return;
    case OPU_LEN:
      if (ttisstring(a)) { setnumV(a, (double)strV(a)->len); return; }
      if (ttistable(a)) { setnumV(a, (double)tab_len(tabV(a))); return; }
      ci->curline = e->line;
      { TValue out; vm_len(L, a, &out, e->u.un.e); copyTV(L->top - 1, &out); }
      return;
    }
    return;
  }
  case E_BINOP: {
    int op = e->op;
    if (op == OP_CONCAT) {
      /* flatten chain */
      const Expr *parts[256]; int n = 0;
      const Expr *c = e;
      while (c->kind == E_BINOP && c->op == OP_CONCAT && n < 255) { parts[n++] = c->u.bin.a; c = c->u.bin.b; }
      parts[n++] = c;
      checkstack(L, n + 2);
      for (int i = 0; i < n; i++) eval(L, ci, parts[i]);
      ci->curline = e->line;
      concat_values(L, n, parts);
      return;
    }
    eval(L, ci, e->u.bin.a);
    eval(L, ci, e->u.bin.b);
    TValue *a = L->top - 2, *b = L->top - 1;
    switch (op) {
    case OP_ADD: if (ttisnumber(a) && ttisnumber(b)) { a->u.n += b->u.n; L->top--; return; } break;
    case OP_SUB: if (ttisnumber(a) && ttisnumber(b)) { a->u.n -= b->u.n; L->top--; return; } break;
    case OP_MUL: if (ttisnumber(a) && ttisnumber(b)) { a->u.n *= b->u.n; L->top--; return; } break;
    case OP_DIV: if (ttisnumber(a) && ttisnumber(b)) { a->u.n /= b->u.n; L->top--; return; } break;
    case OP_MOD: if (ttisnumber(a) && ttisnumber(b)) { a->u.n = lmod(a->u.n, b->u.n); L->top--; return; } break;
    case OP_POW: if (ttisnumber(a) && ttisnumber(b)) { a->u.n = pow(a->u.n, b->u.n); L->top--; return; } break;
    case OP_EQ: case OP_NE: {
      int r;
      if (a->tt != b->tt) r = 0;
      else if (ttisnumber(a)) r = a->u.n == b->u.n;
      else if (ttisstring(a) || ttisboolean(a) || ttisnil(a)) r = lua_rawequal(a, b);
      else { ci->curline = e->line; r = vm_equal(L, a, b); }
      setboolV(a, op == OP_EQ ? r : !r);
      L->top--;
      return;
    }
    case OP_LT: case OP_GT: {
      int r;
      if (op == OP_GT) { TValue *t = a; a = b; b = t; }
      if (ttisnumber(a) && ttisnumber(b)) r = a->u.n < b->u.n;
      else { ci->curline = e->line; r = vm_lessthan(L, a, b); }
      setboolV(L->top - 2, r); L->top--;
      return;
    }
    case OP_LE: case OP_GE: {
      int r;
      if (op == OP_GE) { TValue *t = a; a = b; b = t; }
      if (ttisnumber(a) && ttisnumber(b)) r = a->u.n <= b->u.n;
      else { ci->curline = e->line; r = vm_lessequal(L, a, b); }
      setboolV(L->top - 2, r); L->top--;
      return;
    }
    }
    /* arithmetic slow path */
    ci->curline = e->line;
    {
      TValue out;
      vm_arith(L, op, a, b, &out, e->u.bin.a, e->u.bin.b);
      copyTV(L->top - 2, &out);
      L->top--;
    }
    return;
  }
  case E_TABLE: eval_table(L, ci, e); return;
  }
}

/* assign value v to target expression */
static void assign_to(lua_State *L, CallInfo *ci, const Expr *target, TValue *objkey, const TValue *v, int line) {
  switch (target->kind) {
  case E_LOCAL: copyTV(SLOT(ci, target->u.var.idx), v); return;
  case E_UPVAL: copyTV(ci->cl->u.l.upvals[target->u.var.idx]->v, v); return;
  case E_GLOBAL: {
    Table *env = ci->cl->env;
    if (env->metatable == NULL) {
      TValue *slot = tab_setstr(L, env, target->u.str);
      copyTV(slot, v);
      return;
    }
    TValue envv, key; settabV(&envv, env); setstrV(&key, target->u.str);
    ci->curline = line;
    setindex_value(L, &envv, &key, v, NULL);
    return;
  }
  case E_INDEX: {
    TValue *obj = objkey, *key = objkey + 1;
    if (ttistable(obj)) {
      Table *t = tabV(obj);
      const TValue *slot = tab_get(t, key);
      if (!ttisnil(slot)) { copyTV((TValue *)slot, v); return; }
      if (t->metatable == NULL) {
        ci->curline = line;
        TValue *s = tab_set(L, t, key);
        copyTV(s, v);
        return;
      }
    }
    ci->curline = line;
    setindex_value(L, obj, key, v, target->u.index.obj);
    return;
  }
  default: return;
  }
}

static int exec_stmt(lua_State *L, CallInfo *ci, const Stmt *s, const Block *blk, int *pc);

static int exec_block(lua_State *L, CallInfo *ci, const Block *b, const Stmt **gototarget) {
  int pc = 0;
  int st = EX_NORMAL;
  (void)gototarget;
  gc_check(L);
  while (pc < b->nstmts) {
    const Stmt *s = b->stmts[pc++];
    st = exec_stmt(L, ci, s, b, &pc);
    if (st != EX_NORMAL) {
      if (st == EX_GOTO) {
        const Stmt *g = pending_goto;
        if (g->u.gotostmt.target == b) {
          pc = g->u.gotostmt.index;
          func_closeupvals(L, ci->base + (int)(intptr_t)g->u.gotostmt.name);
          st = EX_NORMAL;
          continue;
        }
      }
      break;
    }
  }
  if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot);
  return st;
}

static inline int exec_body(lua_State *L, CallInfo *ci, const Block *b) {
  return exec_block(L, ci, b, NULL);
}

static int exec_stmt(lua_State *L, CallInfo *ci, const Stmt *s, const Block *blk, int *pc) {
  (void)blk; (void)pc;
  switch (s->kind) {
  case S_LOCAL: {
    int nv = s->u.local.nvars, ne = s->u.local.nexprs;
    TValue *base = L->top;
    checkstack(L, nv + ne + 2);
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.local.exprs[i]);
      else eval(L, ci, s->u.local.exprs[i]);
    }
    int got = (int)(L->top - base);
    for (int i = 0; i < nv; i++) {
      if (i < got) copyTV(SLOT(ci, s->u.local.slots[i]), base + i);
      else setnilV(SLOT(ci, s->u.local.slots[i]));
    }
    L->top = base;
    return EX_NORMAL;
  }
  case S_LOCALFUNC: {
    TValue *base = L->top;
    setnilV(SLOT(ci, s->u.localfunc.slot));
    /* the closure may reference itself: create closure, then store */
    push_closure(L, ci, s->u.localfunc.func);
    copyTV(SLOT(ci, s->u.localfunc.slot), base);
    L->top = base;
    return EX_NORMAL;
  }
  case S_ASSIGN: {
    int nt = s->u.assign.ntargets, ne = s->u.assign.nexprs;
    TValue *base = L->top;
    checkstack(L, nt * 2 + ne + 2);
    if (nt == 1 && ne == 1) {
      const Expr *t = s->u.assign.targets[0];
      if (t->kind == E_LOCAL) {
        eval(L, ci, s->u.assign.exprs[0]);
        copyTV(SLOT(ci, t->u.var.idx), L->top - 1);
        L->top = base;
        return EX_NORMAL;
      }
      if (t->kind == E_INDEX) {
        eval(L, ci, t->u.index.obj);
        eval(L, ci, t->u.index.key);
        eval(L, ci, s->u.assign.exprs[0]);
        assign_to(L, ci, t, base, L->top - 1, s->line);
        L->top = base;
        return EX_NORMAL;
      }
      eval(L, ci, s->u.assign.exprs[0]);
      assign_to(L, ci, t, NULL, L->top - 1, s->line);
      L->top = base;
      return EX_NORMAL;
    }
    /* evaluate target prefixes (obj, key) for index targets */
    for (int i = 0; i < nt; i++) {
      const Expr *t = s->u.assign.targets[i];
      if (t->kind == E_INDEX) { eval(L, ci, t->u.index.obj); eval(L, ci, t->u.index.key); }
      else { setnilV(L->top); setnilV(L->top + 1); L->top += 2; }
    }
    TValue *vbase = L->top;
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.assign.exprs[i]);
      else eval(L, ci, s->u.assign.exprs[i]);
    }
    int got = (int)(L->top - vbase);
    for (int i = got; i < nt; i++) { setnilV(L->top); L->top++; }
    /* assign right to left */
    for (int i = nt - 1; i >= 0; i--) {
      assign_to(L, ci, s->u.assign.targets[i], base + 2 * i, vbase + i, s->line);
    }
    L->top = base;
    return EX_NORMAL;
  }
  case S_CALL: {
    TValue *base = L->top;
    eval_call(L, ci, s->u.call.call, 0);
    L->top = base;
    return EX_NORMAL;
  }
  case S_DO:
    return exec_body(L, ci, s->u.doblk.body);
  case S_WHILE: {
    for (;;) {
      TValue *base = L->top;
      eval(L, ci, s->u.whileloop.cond);
      int c = !isfalse(L->top - 1);
      L->top = base;
      if (!c) break;
      int st = exec_body(L, ci, s->u.whileloop.body);
      if (st == EX_BREAK) break;
      if (st != EX_NORMAL) return st;
    }
    return EX_NORMAL;
  }
  case S_REPEAT: {
    for (;;) {
      const Block *b = s->u.repeatloop.body;
      /* execute body without closing upvalues until condition evaluated */
      int pcc = 0, st = EX_NORMAL;
      gc_check(L);
      while (pcc < b->nstmts) {
        const Stmt *ss = b->stmts[pcc++];
        st = exec_stmt(L, ci, ss, b, &pcc);
        if (st != EX_NORMAL) {
          if (st == EX_GOTO && pending_goto->u.gotostmt.target == b) {
            pcc = pending_goto->u.gotostmt.index;
            func_closeupvals(L, ci->base + (int)(intptr_t)pending_goto->u.gotostmt.name);
            st = EX_NORMAL; continue;
          }
          break;
        }
      }
      if (st == EX_BREAK) { if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot); break; }
      if (st != EX_NORMAL) { if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot); return st; }
      TValue *base = L->top;
      eval(L, ci, s->u.repeatloop.cond);
      int c = !isfalse(L->top - 1);
      L->top = base;
      if (b->hascapture) func_closeupvals(L, ci->base + b->firstslot);
      if (c) break;
    }
    return EX_NORMAL;
  }
  case S_IF: {
    for (int i = 0; i < s->u.ifstmt.nconds; i++) {
      TValue *base = L->top;
      eval(L, ci, s->u.ifstmt.conds[i]);
      int c = !isfalse(L->top - 1);
      L->top = base;
      if (c) return exec_body(L, ci, s->u.ifstmt.blocks[i]);
    }
    if (s->u.ifstmt.elseblk) return exec_body(L, ci, s->u.ifstmt.elseblk);
    return EX_NORMAL;
  }
  case S_NUMFOR: {
    TValue *base = L->top;
    eval(L, ci, s->u.numfor.start);
    eval(L, ci, s->u.numfor.limit);
    if (s->u.numfor.step) eval(L, ci, s->u.numfor.step); else { setnumV(L->top, 1); L->top++; }
    TValue *vs = base;
    ci->curline = s->line;
    if (!ttisnumber(vs)) { TValue n; if (vm_tonumber(vs, &n) && 0) copyTV(vs, &n); else err_run(L, "'for' initial value must be a number"); }
    if (!ttisnumber(vs + 1)) err_run(L, "'for' limit must be a number");
    if (!ttisnumber(vs + 2)) err_run(L, "'for' step must be a number");
    double idx = numV(vs), limit = numV(vs + 1), step = numV(vs + 2);
    L->top = base;
    TValue *var = SLOT(ci, s->u.numfor.slot);
    const Block *body = s->u.numfor.body;
    if (step > 0 ? idx <= limit : idx >= limit) {
      for (;;) {
        setnumV(var, idx);
        int st = exec_body(L, ci, body);
        if (st == EX_BREAK) break;
        if (st != EX_NORMAL) return st;
        idx += step;
        if (!(step > 0 ? idx <= limit : idx >= limit)) break;
      }
    }
    return EX_NORMAL;
  }
  case S_GENFOR: {
    TValue *base = L->top;
    int ne = s->u.genfor.nexprs;
    checkstack(L, ne + 8);
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.genfor.exprs[i]);
      else eval(L, ci, s->u.genfor.exprs[i]);
    }
    int got = (int)(L->top - base);
    for (int i = got; i < 3; i++) { setnilV(L->top); L->top++; }
    TValue *hid = SLOT(ci, s->u.genfor.baseslot);
    copyTV(hid, base); copyTV(hid + 1, base + 1); copyTV(hid + 2, base + 2);
    L->top = base;
    int nv = s->u.genfor.nvars;
    TValue *vars = hid + 3;
    const Block *body = s->u.genfor.body;
    for (;;) {
      TValue *cb = L->top;
      copyTV(L->top, hid); copyTV(L->top + 1, hid + 1); copyTV(L->top + 2, hid + 2);
      L->top += 3;
      ci->curline = s->line;
      ci->curforgen = 1;
      vm_call(L, cb, nv);
      ci->curforgen = 0;
      if (ttisnil(cb)) { L->top = cb; break; }
      for (int i = 0; i < nv; i++) copyTV(vars + i, cb + i);
      copyTV(hid + 2, cb);
      L->top = cb;
      int st = exec_body(L, ci, body);
      if (st == EX_BREAK) break;
      if (st != EX_NORMAL) return st;
    }
    return EX_NORMAL;
  }
  case S_RETURN: {
    int ne = s->u.ret.nexprs;
    TValue *base = L->top;
    checkstack(L, ne + 2);
    if (s->u.ret.istail) {
      /* evaluate function and args, then signal tail call */
      const Expr *e = s->u.ret.exprs[0];
      TValue *func = L->top;
      if (e->kind == E_METHOD) {
        eval(L, ci, e->u.call.fn);
        TValue *obj = L->top - 1;
        TValue key; setstrV(&key, e->u.call.name);
        TValue method;
        ci->curline = e->line;
        index_value(L, obj, &key, &method, e->u.call.fn);
        copyTV(L->top, obj); L->top++;
        copyTV(func, &method);
      } else eval(L, ci, e->u.call.fn);
      for (int i = 0; i < e->u.call.nargs; i++) {
        if (i == e->u.call.nargs - 1) eval_multi(L, ci, e->u.call.args[i]);
        else eval(L, ci, e->u.call.args[i]);
      }
      ci->curline = e->line;
      ci->curcall = e;
      if (!ttisfunction(func)) {
        /* let vm_call handle __call or error, but as a normal call to keep naming */
        const TValue *mm = vm_getmetamethod(func, MM_CALL);
        if (ttisnil(mm)) err_call(L, func);
      }
      ci->retbase = func;
      L->nresults = -2;
      return EX_RETURN;
    }
    for (int i = 0; i < ne; i++) {
      if (i == ne - 1) eval_multi(L, ci, s->u.ret.exprs[i]);
      else eval(L, ci, s->u.ret.exprs[i]);
    }
    ci->retbase = base;
    L->nresults = (int)(L->top - base);
    return EX_RETURN;
  }
  case S_BREAK: return EX_BREAK;
  case S_GOTO: pending_goto = s; return EX_GOTO;
  case S_LABEL: return EX_NORMAL;
  }
  return EX_NORMAL;
}

static void exec_function(lua_State *L, CallInfo *ci) {
  Proto *p = ci->cl->u.l.p;
  L->nresults = 0;
  ci->retbase = NULL;
  int st = exec_block(L, ci, p->body, NULL);
  if (st != EX_RETURN) { ci->retbase = L->top; L->nresults = 0; }
}

/* ---- traceback ---- */
static void frame_desc(lua_State *L, CallInfo *ci, SBuf *sb) {
  if (ci->isC) {
    const char *name, *what;
    if (vm_getinfo_name(L, ci, &name, &what)) sbuf_putf(sb, "\t[C]: in function '%s'\n", name);
    else if (ci->cl && ci->cl->isC && ci->cl->u.c.builtin == 0 && ci->cl->u.c.name) sbuf_putf(sb, "\t[C]: in function '%s'\n", ci->cl->u.c.name);
    else sbuf_putf(sb, "\t[C]: at 0x%08x\n", (unsigned)(uintptr_t)(ci->cl ? (void *)ci->cl->u.c.f : NULL) & 0xffffffffu);
    return;
  }
  Proto *p = ci->cl->u.l.p;
  GCstr *src = vm_shortsrc(p->source);
  sbuf_putf(sb, "\t%s:%d: in ", str_data(src), ci->curline);
  const char *name, *what;
  if (vm_getinfo_name(L, ci, &name, &what)) sbuf_putf(sb, "function '%s'\n", name);
  else if (p->linedefined == 0) sbuf_puts(sb, "main chunk\n");
  else sbuf_putf(sb, "function <%s:%d>\n", str_data(src), p->linedefined);
}

void vm_traceback(lua_State *L, lua_State *L1, const char *msg, int level, char **out) {
  SBuf sb; sbuf_init(&sb);
  if (msg) { sbuf_puts(&sb, msg); sbuf_putc(&sb, '\n'); }
  sbuf_puts(&sb, "stack traceback:");
  CallInfo *ci = L1->ci - level;
  int count = 0;
  int total = (int)(ci - L1->cibase);
  for (; ci > L1->cibase; ci--) {
    if (total > 22 && count == 10) {
      int skip = total - 21 - 10;
      if (skip > 0) { sbuf_putf(&sb, "\n\t...\n"); ci -= skip; sb.n--; }
    }
    sbuf_putc(&sb, '\n');
    frame_desc(L1, ci, &sb);
    sb.n--;  /* remove trailing newline */
    count++;
  }
  if (L1 == G.mainthread || L1->status != CO_SUSPENDED) {
    /* nothing */
  }
  if (L1->cibase->ismain && L1 == G.mainthread) {
    sbuf_puts(&sb, "\n\t[C]: at 0x");
    sbuf_putf(&sb, "%012lx", (unsigned long)(uintptr_t)vm_traceback & 0xffffffffffffUL);
  }
  (void)L;
  sbuf_putc(&sb, '\0');
  *out = sb.b;
}

/* ---- coroutines (ucontext based) ---- */
#define CO_CSTACK_SIZE (256u * 1024 * 1024)

typedef struct CoCtx {
  ucontext_t uc;
  ucontext_t *back;
} CoCtx;

void co_free_cstack(lua_State *L) {
  if (L->cstack) { munmap(L->cstack, L->cstacksize); L->cstack = NULL; }
  if (L->ctx) { free(L->ctx); L->ctx = NULL; }
}

static lua_State *co_starting;

static void co_entry(void) {
  lua_State *co = co_starting;
  CoCtx *cc = (CoCtx *)co->ctx;
  ErrorJmp ej;
  ej.prev = NULL; ej.status = 0;
  co->errjmp = &ej;
  char *oldlimit = cstack_limit;
  cstack_limit = (char *)co->cstack + 256 * 1024;
  if (setjmp(ej.jb) == 0) {
    /* function at stack[1], args after */
    TValue *func = co->stack + 1;
    vm_call(co, func, -1);
    /* results at func .. top */
    co->status = CO_DEAD;
    co->errjmp = NULL;
    L_done:
    cstack_limit = oldlimit;
    swapcontext(&cc->uc, cc->back);
    goto L_done;
  } else {
    /* error */
    co->status = CO_DEAD;
    co->errjmp = NULL;
    copyTV(&co->errval, co->top - 1);
    co->top = co->stack + 1;
    copyTV(co->top++, &co->errval);
    cstack_limit = oldlimit;
    swapcontext(&cc->uc, cc->back);
    for (;;) swapcontext(&cc->uc, cc->back);
  }
}

static ucontext_t main_uc;
static ucontext_t *cur_back;

static void co_switch_to(lua_State *L, lua_State *co) {
  CoCtx *cc = (CoCtx *)co->ctx;
  ucontext_t here;
  ucontext_t *saveback = cc->back;
  cc->back = &here;
  (void)L;
  swapcontext(&here, &cc->uc);
  cc->back = saveback;
}

/* resume co with nargs values at top of L's stack; returns status; results left on L's stack top (count in *nres via L->nresults) */
int vm_resume(lua_State *L, lua_State *co, int nargs) {
  TValue *args = L->top - nargs;
  if (co->status == CO_DEAD) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume dead coroutine");
    return LUA_ERRRUN;
  }
  if (co->status == CO_RUNNING || co == L) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume running coroutine");
    return LUA_ERRRUN;
  }
  if (co->status == CO_NORMAL) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume non-suspended coroutine");
    return LUA_ERRRUN;
  }
  /* transfer args */
  if (co->top + nargs + 10 >= co->stack + LUAI_MAXSTACK) { L->top -= nargs; vm_pushstring(L, "stack overflow"); return LUA_ERRRUN; }
  for (int i = 0; i < nargs; i++) copyTV(co->top + i, args + i);
  co->top += nargs;
  L->top -= nargs;
  co->coargs = nargs;
  co->resumer = L;
  L->status = CO_NORMAL;
  co->status = CO_RUNNING;
  G.curthread = co;
  if (!co->costarted) {
    co->costarted = 1;
    CoCtx *cc = (CoCtx *)calloc(1, sizeof(CoCtx));
    co->ctx = cc;
    co->cstacksize = CO_CSTACK_SIZE;
    co->cstack = map_anon(co->cstacksize);
    getcontext(&cc->uc);
    cc->uc.uc_stack.ss_sp = co->cstack;
    cc->uc.uc_stack.ss_size = co->cstacksize;
    cc->uc.uc_link = NULL;
    co_starting = co;
    makecontext(&cc->uc, co_entry, 0);
  }
  co_switch_to(L, co);
  G.curthread = L;
  L->status = CO_RUNNING;
  co->resumer = NULL;
  if (co->status == CO_DEAD) {
    if (!ttisnil(&co->errval) || co->top == co->stack + 2 && 0) {}
    if (co->errjmp == NULL && co->ctx && ((CoCtx *)co->ctx)->uc.uc_stack.ss_sp && co->errval.tt != T_NIL) {
      /* error */
      copyTV(L->top++, &co->errval);
      setnilV(&co->errval);
      co_free_cstack(co);
      co->errval.tt = T_NIL;
      co->status = CO_DEAD;
      L->nresults = 1;
      return LUA_ERRRUN;
    }
    /* normal finish: results at co->stack+1 .. co->top */
    {
      TValue *rb = co->stack + 1;
      int n = (int)(co->top - rb);
      checkstack(L, n + 1);
      for (int i = 0; i < n; i++) copyTV(L->top + i, rb + i);
      L->top += n;
      co->top = co->stack + 1;
      co_free_cstack(co);
      L->nresults = n;
      return LUA_OK;
    }
  }
  /* yielded: values at co->top - co->coargs */
  {
    int n = co->coargs;
    TValue *yb = co->top - n;
    checkstack(L, n + 1);
    for (int i = 0; i < n; i++) copyTV(L->top + i, yb + i);
    L->top += n;
    co->top = yb;
    L->nresults = n;
    return LUA_YIELD;
  }
}

int vm_isyieldable(lua_State *L) {
  return L != G.mainthread && L->ctx != NULL;
}

/* yield nresults values at top of co's stack; returns number of resume args placed at top */
int vm_yield(lua_State *L, int nresults) {
  if (L == G.mainthread || L->ctx == NULL) {
    err_msg(L, "attempt to yield from outside a coroutine");
  }
  CoCtx *cc = (CoCtx *)L->ctx;
  L->coargs = nresults;
  L->status = CO_SUSPENDED;
  char *oldlimit = cstack_limit;
  swapcontext(&cc->uc, cc->back);
  cstack_limit = oldlimit;
  /* resumed: args at top */
  L->status = CO_RUNNING;
  return L->coargs;
}

/* ---- init ---- */
extern char *main_cstack_base;
void vm_init(void) {
  memset(&G, 0, sizeof(G));
  gc_init();
  for (int i = 0; i < MM__MAX; i++) { G.mmnames[i] = str_newz(mm_names[i]); G.mmnames[i]->reserved = 0; }
  lua_State *L = thread_new(NULL, 0);
  G.mainthread = L; G.curthread = L;
  L->status = CO_RUNNING;
  G.registry = tab_new(0, 0);
  G.globals = tab_new(0, 0);
  L->env = G.globals;
  cstack_limit = main_cstack_base ? main_cstack_base + 512 * 1024 : NULL;
}
