#define CO_CSTACK_SIZE (256u * 1024 * 1024)

typedef struct CoCtx {
  ucontext_t uc;
  ucontext_t *back;
} CoCtx;

void co_free_cstack(lua_State *L) {
  if (L->cstack) { munmap(L->cstack, L->cstacksize); L->cstack = NULL; }
  if (L->ctx) { free(L->ctx); L->ctx = NULL; }
}

static lua_State *co_starting;

static void co_entry(void) {
  lua_State *co = co_starting;
  CoCtx *cc = (CoCtx *)co->ctx;
  ErrorJmp ej;
  ej.prev = NULL; ej.status = 0;
  co->errjmp = &ej;
  cstack_limit = (char *)co->cstack + 512 * 1024;
  if (setjmp(ej.jb) == 0) {
    TValue *func = co->stack + 1;
    vm_call(co, func, -1);
    co->status = CO_DEAD;
    co->coerror = 0;
    co->errjmp = NULL;
  } else {
    co->status = CO_DEAD;
    co->coerror = 1;
    co->errjmp = NULL;
  }
  for (;;) swapcontext(&cc->uc, cc->back);
}

static void co_switch_to(lua_State *co) {
  CoCtx *cc = (CoCtx *)co->ctx;
  ucontext_t here;
  ucontext_t *saveback = cc->back;
  char *savelimit = cstack_limit;
  cc->back = &here;
  swapcontext(&here, &cc->uc);
  cc->back = saveback;
  cstack_limit = savelimit;
}

/* resume co with nargs values at top of L's stack; returns status; results left on L's stack top (count in L->nresults) */
int vm_resume(lua_State *L, lua_State *co, int nargs) {
  TValue *args = L->top - nargs;
  if (co->status == CO_DEAD) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume dead coroutine");
    L->nresults = 1;
    return LUA_ERRRUN;
  }
  if (co->status == CO_RUNNING || co == L) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume running coroutine");
    L->nresults = 1;
    return LUA_ERRRUN;
  }
  if (co->status == CO_NORMAL) {
    L->top -= nargs;
    vm_pushstring(L, "cannot resume non-suspended coroutine");
    L->nresults = 1;
    return LUA_ERRRUN;
  }
  if (co->top + nargs + 10 >= co->stack + LUAI_MAXSTACK) { L->top -= nargs; vm_pushstring(L, "stack overflow"); L->nresults = 1; return LUA_ERRRUN; }
  for (int i = 0; i < nargs; i++) copyTV(co->top + i, args + i);
  co->top += nargs;
  L->top -= nargs;
  co->coargs = nargs;
  co->resumer = L;
  L->status = CO_NORMAL;
  co->status = CO_RUNNING;
  G.curthread = co;
  if (!co->costarted) {
    co->costarted = 1;
    CoCtx *cc = (CoCtx *)calloc(1, sizeof(CoCtx));
    co->ctx = cc;
    co->cstacksize = CO_CSTACK_SIZE;
    co->cstack = map_anon(co->cstacksize);
    getcontext(&cc->uc);
    cc->uc.uc_stack.ss_sp = co->cstack;
    cc->uc.uc_stack.ss_size = co->cstacksize;
    cc->uc.uc_link = NULL;
    co_starting = co;
    makecontext(&cc->uc, co_entry, 0);
  }
  co_switch_to(co);
  G.curthread = L;
  L->status = CO_RUNNING;
  co->resumer = NULL;
  if (co->status == CO_DEAD) {
    if (co->coerror) {
      copyTV(L->top++, co->top - 1);
      co->top = co->stack + 1;
      co_free_cstack(co);
      L->nresults = 1;
      return LUA_ERRRUN;
    }
    TValue *rb = co->stack + 1;
    int n = (int)(co->top - rb);
    checkstack(L, n + 1);
    for (int i = 0; i < n; i++) copyTV(L->top + i, rb + i);
    L->top += n;
    co->top = co->stack + 1;
    co_free_cstack(co);
    L->nresults = n;
    return LUA_OK;
  }
  /* yielded: values at co->top - co->coargs */
  {
    int n = co->coargs;
    TValue *yb = co->top - n;
    checkstack(L, n + 1);
    for (int i = 0; i < n; i++) copyTV(L->top + i, yb + i);
    L->top += n;
    co->top = yb;
    L->nresults = n;
    return LUA_YIELD;
  }
}

int vm_isyieldable(lua_State *L) {
  return L != G.mainthread && L->ctx != NULL;
}

/* yield nresults values at top of co's stack; returns number of resume args placed at top */
int vm_yield(lua_State *L, int nresults) {
  if (L == G.mainthread || L->ctx == NULL) {
    err_msg(L, "attempt to yield from outside a coroutine");
  }
  CoCtx *cc = (CoCtx *)L->ctx;
  L->coargs = nresults;
  L->status = CO_SUSPENDED;
  char *oldlimit = cstack_limit;
  swapcontext(&cc->uc, cc->back);
  cstack_limit = oldlimit;
  L->status = CO_RUNNING;
  return L->coargs;
}

