void lib_setfieldstr(lua_State *L, Table *t, const char *name, const char *s) { TValue v; setstrV(&v, str_newz(s)); lib_setfield(L, t, name, &v); }

Table *lib_newmodule(lua_State *L, const char *name) {
  Table *t = tab_new(0, 16);
  TValue v; settabV(&v, t);
  lib_setfield(L, G.globals, name, &v);
