static int base_tonumber(lua_State *L) {
  TValue *o = lib_arg(L, 1);
  TValue *b = lib_arg(L, 2);
  if (ttisnil(b)) {
    lib_checkany(L, 1);
    TValue out;
    if (vm_tonumber(o, &out)) { vm_push(L, &out); return 1; }
    vm_pushnil(L);
    return 1;
  }
  int32_t base = lib_checkint(L, 2);
  if (base == 10) {
    TValue out;
    if (vm_tonumber(o, &out)) { vm_push(L, &out); return 1; }
    vm_pushnil(L);
    return 1;
  }
  if (base < 2 || base > 36) err_arg(L, 2, "base out of range");
  GCstr *s = lib_checkstr(L, 1);
  const char *p = str_data(s);
  int neg = 0;
  while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' || *p == '\f' || *p == '\v') p++;
  if (*p == '-') { p++; neg = 1; } else if (*p == '+') p++;
  if ((*p >= '0' && *p <= '9') || (*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z')) {
    char *ep;
    errno = 0;
    unsigned long ul = strtoul(p, &ep, base);
    if (p != ep) {
      while (*ep == ' ' || *ep == '\t' || *ep == '\n' || *ep == '\r' || *ep == '\f' || *ep == '\v') ep++;
      if (*ep == '\0' && (size_t)(ep - str_data(s)) == s->len) {
        double n = (double)ul;
        if (neg) n = -n;
        vm_pushnum(L, n);
        return 1;
      }
    }
  }
  vm_pushnil(L);
  return 1;
}

