static int base_pcall(lua_State *L) {
  lib_checkany(L, 1);
  TValue *func = L->ci->base;
  ErrorJmp ej; ej.handler = NULL;
  L->ci->ispcall = 1;
  int st = vm_pcall(L, func, -1, &ej);
  if (st == LUA_OK) {
    int n = (int)(L->top - func);
    /* insert true before results */
    for (TValue *p = L->top; p > func; p--) copyTV(p, p - 1);
    setboolV(func, 1);
    L->top++;
    return n + 1;
  }
  /* error value at func */
  TValue err = *func;
  L->top = func;
  vm_pushbool(L, 0);
  vm_push(L, &err);
  return 2;
}

static int base_xpcall(lua_State *L) {
  int n = lib_nargs(L);
  TValue *base = L->ci->base;
  if (n < 2 || !ttisfunction(base + 1)) err_argtype(L, 2, "function");
  /* layout: f, h, args... -> move f after h: h, f, args... */
  TValue f = base[0];
  base[0] = base[1];
  base[1] = f;
  ErrorJmp ej; ej.handler = base;
  L->ci->ispcall = 1;
  int st = vm_pcall(L, base + 1, -1, &ej);
  if (st == LUA_OK) {
    int nr = (int)(L->top - (base + 1));
    for (TValue *p = L->top; p > base + 1; p--) copyTV(p, p - 1);
    setboolV(base + 1, 1);
    L->top++;
    return nr + 1;
  }
  TValue err = base[1];
  L->top = base + 1;
  vm_pushbool(L, 0);
  vm_push(L, &err);
  return 2;
}

static int base_error(lua_State *L) {
  TValue *msg = lib_arg(L, 1);
  int32_t level = lib_optint(L, 2, 1);
  TValue m = *msg;
  if (ttisstring(&m) && level > 0) {
    GCstr *w = vm_where(L, level);
    if (w->len) {
      vm_pushfstring(L, "%s %s", str_data(w), str_data(strV(&m)));
      vm_throw(L, LUA_ERRRUN);
    }
  }
  vm_push(L, &m);
  vm_throw(L, LUA_ERRRUN);
  return 0;
}

static int base_assert(lua_State *L) {
  lib_checkany(L, 1);
  if (isfalse(lib_arg(L, 1))) {
    TValue *m = lib_arg(L, 2);
    if (lib_isnone(L, 2)) err_callermsg(L, "assertion failed!");
    if (ttisstring(m) || ttisnumber(m)) {
      GCstr *s = ttisstring(m) ? strV(m) : num2strobj(numV(m));
      err_callermsg(L, str_data(s));
    }
    TValue mm = *m;
    vm_push(L, &mm);
    vm_throw(L, LUA_ERRRUN);
  }
  return lib_nargs(L);  /* results are the args themselves (already at base..top) */
