/* ---- load ---- */
typedef struct LoadCtx { const char *buf; size_t len; GCstr *chunkname; Proto *p; } LoadCtx;
static void load_protected(lua_State *L, void *ud) {
  LoadCtx *c = (LoadCtx *)ud;
  c->p = parse_chunk(L, c->buf, c->len, c->chunkname);
}

static Table *dumpreg;  /* registry of dumped functions: string -> proto closure */

int lib_load_buffer(lua_State *L, const char *buf, size_t len, const char *chunkname, const char *mode) {
  int isbc = (len >= 3 && buf[0] == 27 && buf[1] == 'L' && buf[2] == 'J');
  if (mode) {
    if (isbc && !strchr(mode, 'b')) { vm_pushstring(L, "attempt to load chunk with wrong mode"); return LUA_ERRSYNTAX; }
    if (!isbc && !strchr(mode, 't')) { vm_pushstring(L, "attempt to load chunk with wrong mode"); return LUA_ERRSYNTAX; }
  }
  if (isbc) {
    if (dumpreg) {
      GCstr *key = str_new(buf, len);
      const TValue *v = tab_getstr(dumpreg, key);
      if (ttisfunction(v)) {
        Closure *orig = funcV(v);
        Closure *c = func_newL(orig->u.l.p, L->env ? L->env : G.globals);
        for (int i = 0; i < c->nupvals; i++) {
          UpVal *uv = (UpVal *)mem_alloc(sizeof(UpVal));
          uv->v = &uv->closed; setnilV(&uv->closed); uv->nextopen = NULL; uv->level = 0;
          gc_link((GCobj *)uv, T_UPVAL);
          c->u.l.upvals[i] = uv;
        }
        vm_pushfunc(L, c);
        return LUA_OK;
      }
    }
    vm_pushfstring(L, "%s: cannot load incompatible bytecode", chunkname);
    return LUA_ERRSYNTAX;
  }
  LoadCtx c; c.buf = buf; c.len = len; c.chunkname = str_newz(chunkname); c.p = NULL;
  int st = vm_pcall_c(L, load_protected, &c);
  if (st != LUA_OK) return st;
  Closure *cl = func_newL(c.p, L->env ? L->env : G.globals);
  vm_pushfunc(L, cl);
  return LUA_OK;
}

int lib_load_file(lua_State *L, const char *fname, const char *mode) {
  FILE *f;
  char cn[1024];
  if (fname == NULL) { f = stdin; snprintf(cn, sizeof(cn), "=stdin"); }
  else {
    f = fopen(fname, "rb");
    snprintf(cn, sizeof(cn), "@%s", fname);
    if (!f) { vm_pushfstring(L, "cannot open %s: %s", fname, strerror(errno)); return LUA_ERRFILE; }
  }
  SBuf sb; sbuf_init(&sb);
  char tmp[8192]; size_t n;
  while ((n = fread(tmp, 1, sizeof(tmp), f)) > 0) sbuf_putmem(&sb, tmp, n);
  if (ferror(f)) {
    if (fname) fclose(f);
    sbuf_free(&sb);
    vm_pushfstring(L, "cannot read %s: %s", fname ? fname : "stdin", strerror(errno));
    return LUA_ERRFILE;
  }
  if (fname) fclose(f);
  int st = lib_load_buffer(L, sb.b ? sb.b : "", sb.n, cn, mode);
  sbuf_free(&sb);
  return st;
}

static int load_aux(lua_State *L, int st) {
  if (st == LUA_OK) return 1;
  /* error message at top */
  vm_pushnil(L);
  TValue *t = L->top - 1, *m = L->top - 2;
  TValue tmp = *t; *t = *m; *m = tmp;
  return 2;
}

static int base_loadstring_common(lua_State *L, int isload) {
  TValue *chunk = lib_arg(L, 1);
  GCstr *mode = lib_optstr(L, 3, NULL);
  const char *modes = mode ? str_data(mode) : "bt";
  TValue *env = lib_arg(L, 4);
  if (ttisstring(chunk) || ttisnumber(chunk)) {
    GCstr *s = lib_checkstr(L, 1);
    GCstr *cn = lib_optstr(L, 2, s);
    char *cname = (char *)malloc(cn->len + 1);
    memcpy(cname, str_data(cn), cn->len + 1);
    int st = lib_load_buffer(L, str_data(s), s->len, cname, modes);
    free(cname);
    if (st == LUA_OK && ttistable(env)) funcV(L->top - 1)->env = tabV(env);
    return load_aux(L, st);
  }
  if (!ttisfunction(chunk)) err_argtype(L, 1, isload ? "function" : "string");
  GCstr *cn = lib_optstr(L, 2, NULL);
  const char *cname = cn ? str_data(cn) : "=(load)";
  SBuf sb; sbuf_init(&sb);
  for (;;) {
    TValue *fb = L->top;
    copyTV(L->top++, chunk);
    vm_call(L, fb, 1);
    L->top--;
    if (ttisnil(L->top) || (ttisstring(L->top) && strV(L->top)->len == 0)) break;
    if (!ttisstring(L->top)) { sbuf_free(&sb); vm_pushnil(L); vm_pushstring(L, "reader function must return a string"); return 2; }
    sbuf_putmem(&sb, str_data(strV(L->top)), strV(L->top)->len);
  }
  char *cname2 = strdup(cname);
  int st = lib_load_buffer(L, sb.b ? sb.b : "", sb.n, cname2, modes);
  free(cname2);
  sbuf_free(&sb);
  if (st == LUA_OK && ttistable(env)) funcV(L->top - 1)->env = tabV(env);
  return load_aux(L, st);
}
static int base_load(lua_State *L) { return base_loadstring_common(L, 1); }
static int base_loadstring(lua_State *L) { return base_loadstring_common(L, 0); }

static int base_loadfile(lua_State *L) {
  GCstr *fn = lib_optstr(L, 1, NULL);
  GCstr *mode = lib_optstr(L, 2, NULL);
  TValue *env = lib_arg(L, 3);
  int st = lib_load_file(L, fn ? str_data(fn) : NULL, mode ? str_data(mode) : "bt");
  if (st == LUA_OK && ttistable(env)) funcV(L->top - 1)->env = tabV(env);
  return load_aux(L, st);
}

static int base_dofile(lua_State *L) {
  GCstr *fn = lib_optstr(L, 1, NULL);
  int st = lib_load_file(L, fn ? str_data(fn) : NULL, "bt");
  if (st != LUA_OK) vm_throw(L, LUA_ERRRUN);
  TValue *f = L->top - 1;
  vm_call(L, f, -1);
  return (int)(L->top - f);
}

static int base_collectgarbage(lua_State *L) {
  static const char *const opts[] = { "stop", "restart", "collect", "count", "step", "setpause", "setstepmul", "isrunning", NULL };
  int opt = lib_checkoption(L, 1, "collect", opts);
  static int pause = 200, stepmul = 200;
  switch (opt) {
  case 0: G.gcstopped = 1; vm_pushnum(L, 0); return 1;
  case 1: G.gcstopped = 0; vm_pushnum(L, 0); return 1;
  case 2: gc_fullcollect(L); vm_pushnum(L, 0); return 1;
  case 3: vm_pushnum(L, (double)G.totalbytes / 1024.0); return 1;
  case 4: gc_fullcollect(L); vm_pushbool(L, 0); return 1;
  case 5: { int old = pause; pause = lib_optint(L, 2, 0); vm_pushnum(L, old); return 1; }
  case 6: { int old = stepmul; stepmul = lib_optint(L, 2, 0); vm_pushnum(L, old); return 1; }
  case 7: vm_pushbool(L, !G.gcstopped); return 1;
  }
  return 0;
}
static int base_gcinfo(lua_State *L) { vm_pushnum(L, (double)(G.totalbytes / 1024)); return 1; }

static int base_newproxy(lua_State *L) {
  TValue *a = lib_arg(L, 1);
  Udata *u = udata_new(0, NULL);
  if (lib_isnone(L, 1) || (ttisboolean(a) && !boolV(a))) { vm_push(L, (TValue *)&(TValue){ .u.gc = (GCobj *)u, .tt = T_USERDATA }); return 1; }
  if (ttisboolean(a)) {
    u->metatable = tab_new(0, 0);
    u->has_gc = 1;
    TValue v; setudataV(&v, u); vm_push(L, &v);
    return 1;
  }
  if (ttisudata(a) && udataV(a)->metatable) {
    u->metatable = udataV(a)->metatable;
    u->has_gc = 1;
    TValue v; setudataV(&v, u); vm_push(L, &v);
    return 1;
  }
  err_arg(L, 1, "boolean or proxy expected");
  return 0;
}

static Closure *getfunc_arg(lua_State *L, int opt) {
  TValue *a = lib_arg(L, 1);
  if (ttisfunction(a)) return funcV(a);
  int32_t level = ttisnil(a) ? 1 : lib_checkint(L, 1);
  if (level < 0) err_arg(L, 1, "invalid level");
  if (level == 0) return NULL;  /* thread env */
  CallInfo *ci = L->ci - level;
  if (ci <= L->cibase) err_arg(L, 1, "invalid level");
  (void)opt;
  return ci->cl;
}

static int base_getfenv(lua_State *L) {
  TValue *a = lib_arg(L, 1);
  if (ttisnil(a) || ttisnumber(a) || ttisfunction(a)) {
    Closure *c = getfunc_arg(L, 1);
    if (!c) { vm_pushtab(L, L->env ? L->env : G.globals); return 1; }
    vm_pushtab(L, c->env ? c->env : G.globals);
    return 1;
  }
  err_argtype(L, 1, "number");
  return 0;
}

static int base_setfenv(lua_State *L) {
  TValue *a = lib_arg(L, 1);
  Table *t = lib_checktab(L, 2);
  if (ttisnumber(a) && numV(a) == 0) { L->env = t; return 0; }
  Closure *c = getfunc_arg(L, 1);
  if (!c || c->isC) {
    err_msg(L, "'setfenv' cannot change environment of given object");
  }
  c->env = t;
  if (ttisfunction(a)) { vm_push(L, a); return 1; }
  return 0;
}

static int dump_proto(lua_State *L) {
  lib_checkfunc(L, 1);
  Closure *c = funcV(lib_arg(L, 1));
  if (c->isC) err_msg(L, "unable to dump given function");
  if (!dumpreg) {
    dumpreg = tab_new(0, 0);
    TValue v; settabV(&v, dumpreg);
    lib_setfield(L, G.registry, "__dumpreg", &v);
  }
  char buf[64];
  int n = snprintf(buf, sizeof(buf), "\033LJ\002\n%p", (void *)c->u.l.p);
  GCstr *key = str_new(buf, n);
  TValue *slot = tab_setstr(L, dumpreg, key);
  setfuncV(slot, c);
  vm_pushstr(L, key);
  return 1;
}
int lib_string_dump(lua_State *L) { return dump_proto(L); }

void lib_open_base(lua_State *L) {
  Table *g = G.globals;
  TValue v;
  settabV(&v, g); lib_setfield(L, g, "_G", &v);
  lib_setfieldstr(L, g, "_VERSION", "Lua 5.1");
  lib_register(L, g, "assert", base_assert, 2);
  lib_register(L, g, "type", base_type, 3);
  Closure *nx = lib_register(L, g, "next", base_next, 4);
  setfuncV(&v, nx); lib_setfield(L, G.registry, "__next", &v);
  lib_register(L, g, "pairs", base_pairs, 5);
  Closure *ia = lib_register(L, NULL, "ipairs_aux", ipairs_aux, 6);
  setfuncV(&v, ia); lib_setfield(L, G.registry, "__ipairs_aux", &v);
  lib_register(L, g, "ipairs", base_ipairs, 7);
  lib_register(L, g, "getmetatable", base_getmetatable, 8);
  lib_register(L, g, "setmetatable", base_setmetatable, 9);
  lib_register(L, g, "getfenv", base_getfenv, 10);
  lib_register(L, g, "setfenv", base_setfenv, 11);
  lib_register(L, g, "rawget", base_rawget, 12);
  lib_register(L, g, "rawset", base_rawset, 13);
  lib_register(L, g, "rawequal", base_rawequal, 14);
  lib_register(L, g, "unpack", base_unpack, 15);
  lib_register(L, g, "select", base_select, 16);
  lib_register(L, g, "tonumber", base_tonumber, 17);
  lib_register(L, g, "tostring", base_tostring, 18);
  lib_register(L, g, "error", base_error, 19);
  lib_register(L, g, "pcall", base_pcall, 20);
  lib_register(L, g, "xpcall", base_xpcall, 21);
  lib_register(L, g, "loadfile", base_loadfile, 22);
  lib_register(L, g, "load", base_load, 23);
  lib_register(L, g, "loadstring", base_loadstring, 24);
  lib_register(L, g, "dofile", base_dofile, 25);
  lib_register(L, g, "gcinfo", base_gcinfo, 26);
  lib_register(L, g, "collectgarbage", base_collectgarbage, 27);
  lib_register(L, g, "newproxy", base_newproxy, 28);
  lib_register(L, g, "print", base_print, 29);
}
