#include "lua.h"
#include <errno.h>

static int base_print(lua_State *L) {
  int n = lib_nargs(L);
  TValue *base = L->ci->base;
  const TValue *tsf = tab_getstr(L->env ? L->env : G.globals, str_newz("tostring"));
  int shortcut = ttisfunction(tsf) && funcV(tsf)->isC && funcV(tsf)->u.c.builtin == 18;
  for (int i = 0; i < n; i++) {
    GCstr *s;
    if (shortcut || !ttisfunction(tsf)) s = vm_tostring(L, base + i);
    else {
      TValue *fb = L->top;
      copyTV(L->top++, tsf);
      copyTV(L->top++, base + i);
      vm_call(L, fb, 1);
      L->top--;
      if (!ttisstring(L->top)) err_msg(L, "'tostring' must return a string to 'print'");
      s = strV(L->top);
    }
    if (i) fputc('\t', stdout);
    fwrite(str_data(s), 1, s->len, stdout);
  }
  fputc('\n', stdout);
  return 0;
}

static int base_type(lua_State *L) {
  lib_checkany(L, 1);
  vm_pushstring(L, typename_of(lib_arg(L, 1)));
  return 1;
}

static int base_tostring(lua_State *L) { return lib_tostring(L); }

static int base_tonumber(lua_State *L) {
  TValue *o = lib_arg(L, 1);
  TValue *b = lib_arg(L, 2);
  if (ttisnil(b)) {
    lib_checkany(L, 1);
    TValue out;
    if (vm_tonumber(o, &out)) { vm_push(L, &out); return 1; }
    vm_pushnil(L);
    return 1;
  }
  int32_t base = lib_checkint(L, 2);
  if (base == 10) {
    TValue out;
    if (vm_tonumber(o, &out)) { vm_push(L, &out); return 1; }
    vm_pushnil(L);
    return 1;
  }
  if (base < 2 || base > 36) err_arg(L, 2, "base out of range");
  GCstr *s = lib_checkstr(L, 1);
  const char *p = str_data(s);
  int neg = 0;
  while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' || *p == '\f' || *p == '\v') p++;
  if (*p == '-') { p++; neg = 1; } else if (*p == '+') p++;
  if ((*p >= '0' && *p <= '9') || (*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z')) {
    char *ep;
    errno = 0;
    unsigned long ul = strtoul(p, &ep, base);
    if (p != ep) {
      while (*ep == ' ' || *ep == '\t' || *ep == '\n' || *ep == '\r' || *ep == '\f' || *ep == '\v') ep++;
      if (*ep == '\0' && (size_t)(ep - str_data(s)) == s->len) {
        double n = (double)ul;
        if (neg) n = -n;
        vm_pushnum(L, n);
        return 1;
      }
    }
  }
  vm_pushnil(L);
  return 1;
}

static int base_next(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  TValue key[2];
  copyTV(&key[0], lib_arg(L, 2));
  int r = tab_next(L, t, key);
  if (r < 0) err_msg(L, "invalid key to 'next'");
  if (r == 0) { vm_pushnil(L); return 1; }
  vm_push(L, &key[0]); vm_push(L, &key[1]);
  return 2;
}

static int base_pairs(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  const TValue *nextf = tab_getstr(G.registry, str_newz("__next"));
  vm_push(L, nextf);
  vm_pushtab(L, t);
  vm_pushnil(L);
  return 3;
}

static int ipairs_aux(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  int32_t i = lib_checkint(L, 2) + 1;
  const TValue *v = tab_getint(t, i);
  if (ttisnil(v)) { vm_pushnil(L); return 1; }
  vm_pushnum(L, (double)i);
  vm_push(L, v);
  return 2;
}

static int base_ipairs(lua_State *L) {
  lib_checkany(L, 1);
  Table *t = lib_checktab(L, 1);
  const TValue *f = tab_getstr(G.registry, str_newz("__ipairs_aux"));
  vm_push(L, f);
  vm_pushtab(L, t);
  vm_pushnum(L, 0);
  return 3;
}

static int base_select(lua_State *L) {
  int n = lib_nargs(L);
  TValue *a = lib_arg(L, 1);
  if (ttisstring(a) && str_data(strV(a))[0] == '#') { vm_pushnum(L, (double)(n - 1)); return 1; }
  int32_t i = lib_checkint(L, 1);
  if (i < 0) i = n + i;
  else if (i > n) i = n;
  if (i < 1) err_arg(L, 1, "index out of range");
  /* return args i+1 .. n */
  int cnt = n - i;
  TValue *src = L->ci->base + i;
  for (int k = 0; k < cnt; k++) copyTV(L->top + k, src + k);
  L->top += cnt;
  return cnt;
}

static int base_rawget(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  lib_checkany(L, 2);
  vm_push(L, tab_get(t, lib_arg(L, 2)));
  return 1;
}
static int base_rawset(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  lib_checkany(L, 2);
  lib_checkany(L, 3);
  TValue *k = lib_arg(L, 2);
  if (ttisnil(k)) err_run(L, "table index is nil");
  if (ttisnumber(k) && isnan(numV(k))) err_run(L, "table index is NaN");
  TValue *slot = tab_set(L, t, k);
  copyTV(slot, lib_arg(L, 3));
  vm_pushtab(L, t);
  return 1;
}
static int base_rawequal(lua_State *L) {
  lib_checkany(L, 1); lib_checkany(L, 2);
  vm_pushbool(L, lua_rawequal(lib_arg(L, 1), lib_arg(L, 2)));
  return 1;
}

static int base_setmetatable(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  TValue *mt = lib_arg(L, 2);
  if (!ttisnil(mt) && !ttistable(mt)) err_arg(L, 2, "nil or table expected");
  if (lib_isnone(L, 2)) err_arg(L, 2, "nil or table expected");
  if (t->metatable && !ttisnil(tab_getstr(t->metatable, G.mmnames[MM_METATABLE]))) err_msg(L, "cannot change a protected metatable");
  t->metatable = ttisnil(mt) ? NULL : tabV(mt);
  vm_pushtab(L, t);
  return 1;
}
static int base_getmetatable(lua_State *L) {
  lib_checkany(L, 1);
  Table *mt = vm_getmetatable(lib_arg(L, 1));
  if (!mt) { vm_pushnil(L); return 1; }
  const TValue *p = tab_getstr(mt, G.mmnames[MM_METATABLE]);
  if (!ttisnil(p)) { vm_push(L, p); return 1; }
  vm_pushtab(L, mt);
  return 1;
}

static int base_pcall(lua_State *L) {
  lib_checkany(L, 1);
  TValue *func = L->ci->base;
  ErrorJmp ej; ej.handler = NULL;
  L->ci->ispcall = 1;
  int st = vm_pcall(L, func, -1, &ej);
  if (st == LUA_OK) {
    int n = (int)(L->top - func);
    /* insert true before results */
    for (TValue *p = L->top; p > func; p--) copyTV(p, p - 1);
    setboolV(func, 1);
    L->top++;
    return n + 1;
  }
  /* error value at func */
  TValue err = *func;
  L->top = func;
  vm_pushbool(L, 0);
  vm_push(L, &err);
  return 2;
}

static int base_xpcall(lua_State *L) {
  int n = lib_nargs(L);
  TValue *base = L->ci->base;
  if (n < 2 || !ttisfunction(base + 1)) err_argtype(L, 2, "function");
  /* layout: f, h, args... -> move f after h: h, f, args... */
  TValue f = base[0];
  base[0] = base[1];
  base[1] = f;
  ErrorJmp ej; ej.handler = base;
  L->ci->ispcall = 1;
  int st = vm_pcall(L, base + 1, -1, &ej);
  if (st == LUA_OK) {
    int nr = (int)(L->top - (base + 1));
    for (TValue *p = L->top; p > base + 1; p--) copyTV(p, p - 1);
    setboolV(base + 1, 1);
    L->top++;
    return nr + 1;
  }
  TValue err = base[1];
  L->top = base + 1;
  vm_pushbool(L, 0);
  vm_push(L, &err);
  return 2;
}

static int base_error(lua_State *L) {
  TValue *msg = lib_arg(L, 1);
  int32_t level = lib_optint(L, 2, 1);
  TValue m = *msg;
  if (ttisstring(&m) && level > 0) {
    GCstr *w = vm_where(L, level);
    if (w->len) {
      vm_pushfstring(L, "%s %s", str_data(w), str_data(strV(&m)));
      vm_throw(L, LUA_ERRRUN);
    }
  }
  vm_push(L, &m);
  vm_throw(L, LUA_ERRRUN);
  return 0;
}

static int base_assert(lua_State *L) {
  lib_checkany(L, 1);
  if (isfalse(lib_arg(L, 1))) {
    TValue *m = lib_arg(L, 2);
    if (lib_isnone(L, 2)) err_callermsg(L, "assertion failed!");
    if (ttisstring(m) || ttisnumber(m)) {
      GCstr *s = ttisstring(m) ? strV(m) : num2strobj(numV(m));
      err_callermsg(L, str_data(s));
    }
    TValue mm = *m;
    vm_push(L, &mm);
    vm_throw(L, LUA_ERRRUN);
  }
  return lib_nargs(L);  /* results are the args themselves (already at base..top) */
}

static int base_unpack(lua_State *L) {
  Table *t = lib_checktab(L, 1);
  int32_t i = lib_optint(L, 2, 1);
  int32_t e = ttisnil(lib_arg(L, 3)) ? (int32_t)tab_len(t) : lib_checkint(L, 3);
  if (i > e) return 0;
  int64_t n = (int64_t)e - i + 1;
  if (n <= 0 || n >= LUAI_MAXCSTACK) err_callermsg(L, "too many results to unpack");
  err_check_stack(L, (int)n);
  for (int32_t k = i; k <= e; k++) vm_push(L, tab_getint(t, k));
  return (int)n;
}

/* ---- load ---- */
typedef struct LoadCtx { const char *buf; size_t len; GCstr *chunkname; Proto *p; } LoadCtx;
static void load_protected(lua_State *L, void *ud) {
  LoadCtx *c = (LoadCtx *)ud;
  c->p = parse_chunk(L, c->buf, c->len, c->chunkname);
}

static Table *dumpreg;  /* registry of dumped functions: string -> proto closure */

int lib_load_buffer(lua_State *L, const char *buf, size_t len, const char *chunkname, const char *mode) {
  int isbc = (len >= 3 && buf[0] == 27 && buf[1] == 'L' && buf[2] == 'J');
  if (mode) {
    if (isbc && !strchr(mode, 'b')) { vm_pushstring(L, "attempt to load chunk with wrong mode"); return LUA_ERRSYNTAX; }
    if (!isbc && !strchr(mode, 't')) { vm_pushstring(L, "attempt to load chunk with wrong mode"); return LUA_ERRSYNTAX; }
  }
  if (isbc) {
    if (dumpreg) {
      GCstr *key = str_new(buf, len);
      const TValue *v = tab_getstr(dumpreg, key);
      if (ttisfunction(v)) {
        Closure *orig = funcV(v);
        Closure *c = func_newL(orig->u.l.p, L->env ? L->env : G.globals);
        for (int i = 0; i < c->nupvals; i++) {
          UpVal *uv = (UpVal *)mem_alloc(sizeof(UpVal));
          uv->v = &uv->closed; setnilV(&uv->closed); uv->nextopen = NULL; uv->level = 0;
          gc_link((GCobj *)uv, T_UPVAL);
          c->u.l.upvals[i] = uv;
        }
        vm_pushfunc(L, c);
        return LUA_OK;
      }
    }
    vm_pushfstring(L, "%s: cannot load incompatible bytecode", chunkname);
    return LUA_ERRSYNTAX;
