      s++; p = ep; continue;
    }
    }
  }
}

static void push_onecapture(MatchState *ms, int i, const char *s, const char *e) {
  if (i >= ms->level) {
    if (i == 0) vm_pushlstring(ms->L, s, e - s);
    else err_msg(ms->L, "invalid capture index");
  } else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNFINISHED) err_msg(ms->L, "unfinished capture");
    if (l == CAP_POSITION) vm_pushnum(ms->L, (double)(ms->capture[i].init - ms->src_init + 1));
    else vm_pushlstring(ms->L, ms->capture[i].init, l);
  }
}
static int push_captures(MatchState *ms, const char *s, const char *e) {
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  err_check_stack(ms->L, nlevels);
  for (int i = 0; i < nlevels; i++) push_onecapture(ms, i, s, e);
  return nlevels;
}

static const char *lmemfind(const char *s1, size_t l1, const char *s2, size_t l2) {
  if (l2 == 0) return s1;
  else if (l2 > l1) return NULL;
  else {
    const char *init;
    l2--;
    l1 = l1 - l2;
    while (l1 > 0 && (init = (const char *)memchr(s1, *s2, l1)) != NULL) {
      init++;
      if (memcmp(init, s2 + 1, l2) == 0) return init - 1;
      else { l1 -= init - s1; s1 = init; }
    }
    return NULL;
  }
}

static int nospecials(const char *p, size_t l) {
  size_t i = 0;
  while (i < l) {
    if (strpbrk(p + i, "^$*+?.([%-")) return 0;
    i += strlen(p + i) + 1;
  }
  return 1;
}

static int str_find_aux(lua_State *L, int find) {
  GCstr *s = lib_checkstr(L, 1);
  GCstr *p = lib_checkstr(L, 2);
  size_t ls = s->len, lp = p->len;
  const char *sd = str_data(s), *pd = str_data(p);
  int64_t init = lib_optint(L, 3, 1);
  if (init < 0) { init = (int64_t)ls + init + 1; if (init < 1) init = 1; }
  else if (init == 0) init = 1;
  if ((size_t)init > ls + 1) { vm_pushnil(L); return 1; }
  init--;
  if (find && (!isfalse(lib_arg(L, 4)) || nospecials(pd, lp))) {
    const char *s2 = lmemfind(sd + init, ls - init, pd, lp);
    if (s2) {
      vm_pushnum(L, (double)(s2 - sd + 1));
      vm_pushnum(L, (double)(s2 - sd + lp));
      return 2;
    }
  } else {
    MatchState ms;
    int anchor = (*pd == '^');
    const char *s1 = sd + init;
    if (anchor) { pd++; lp--; }
    ms.L = L; ms.src_init = sd; ms.src_end = sd + ls; ms.p_end = pd + lp;
    do {
      const char *e;
      ms.level = 0; ms.depth = 0;
      if ((e = do_match(&ms, s1, pd)) != NULL) {
        if (find) {
          vm_pushnum(L, (double)(s1 - sd + 1));
          vm_pushnum(L, (double)(e - sd));
          return push_captures(&ms, NULL, 0) + 2;
        } else return push_captures(&ms, s1, e);
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  vm_pushnil(L);
  return 1;
}
static int str_find(lua_State *L) { return str_find_aux(L, 1); }
static int str_match(lua_State *L) { return str_find_aux(L, 0); }

static int gmatch_aux(lua_State *L) {
  Closure *self = L->ci->cl;
  GCstr *s = strV(&self->u.c.upvals[0]);
  GCstr *p = strV(&self->u.c.upvals[1]);
  int64_t pos = (int64_t)numV(&self->u.c.upvals[2]);
  MatchState ms;
  ms.L = L; ms.src_init = str_data(s); ms.src_end = str_data(s) + s->len; ms.p_end = str_data(p) + p->len;
  for (const char *src = str_data(s) + pos; src <= ms.src_end; src++) {
    const char *e;
    ms.level = 0; ms.depth = 0;
    if ((e = do_match(&ms, src, str_data(p))) != NULL) {
      int64_t newpos = e - str_data(s);
      if (e == src) newpos++;
      setnumV(&self->u.c.upvals[2], (double)newpos);
      return push_captures(&ms, src, e);
    }
  }
  return 0;
}
static int str_gmatch(lua_State *L) {
  GCstr *s = lib_checkstr(L, 1);
  GCstr *p = lib_checkstr(L, 2);
  Closure *c = func_newC(gmatch_aux, 3, L->env);
  c->u.c.builtin = 86;
  setstrV(&c->u.c.upvals[0], s);
  setstrV(&c->u.c.upvals[1], p);
  setnumV(&c->u.c.upvals[2], 0);
  vm_pushfunc(L, c);
  return 1;
}

static void add_s(MatchState *ms, SBuf *b, const char *s, const char *e, GCstr *news) {
  const char *p = str_data(news);
  size_t l = news->len;
  for (size_t i = 0; i < l; i++) {
    if (p[i] != L_ESC) sbuf_putc(b, p[i]);
    else {
      i++;
      if (i >= l) { sbuf_putc(b, '\0'); break; }
      if (!isdigit((unsigned char)p[i])) sbuf_putc(b, p[i]);
      else if (p[i] == '0') sbuf_putmem(b, s, e - s);
      else {
        push_onecapture(ms, p[i] - '1', s, e);
        TValue *v = ms->L->top - 1;
        if (ttisnumber(v)) { char nb[64]; int n = num2str(nb, numV(v)); sbuf_putmem(b, nb, n); }
        else sbuf_putmem(b, str_data(strV(v)), strV(v)->len);
        ms->L->top--;
      }
    }
  }
}

static void add_value(MatchState *ms, SBuf *b, const char *s, const char *e, TValue *repl) {
  lua_State *L = ms->L;
  switch (repl->tt) {
  case T_NUMBER: case T_STRING: {
    GCstr *rs = ttisstring(repl) ? strV(repl) : num2strobj(numV(repl));
    if (ttisnumber(repl)) setstrV(repl, rs);
    add_s(ms, b, s, e, rs);
    return;
  }
  case T_FUNCTION: {
    TValue *fb = L->top;
    copyTV(L->top++, repl);
    int n = push_captures(ms, s, e);
    (void)n;
    vm_call(L, fb, 1);
    break;
  }
  case T_TABLE: {
    push_onecapture(ms, 0, s, e);
    TValue key = *(L->top - 1);
    L->top--;
    TValue out;
    vm_index(L, repl, &key, &out);
    vm_push(L, &out);
    break;
  }
  default: break;
  }
  TValue *v = L->top - 1;
  if (isfalse(v)) { L->top--; sbuf_putmem(b, s, e - s); return; }
  if (ttisnumber(v)) { char nb[64]; int n = num2str(nb, numV(v)); sbuf_putmem(b, nb, n); L->top--; return; }
  if (!ttisstring(v)) {
    char msg[128]; snprintf(msg, sizeof(msg), "invalid replacement value (a %s)", typename_of(v));
    err_callermsg(L, msg);
  }
  sbuf_putmem(b, str_data(strV(v)), strV(v)->len);
  L->top--;
}

static int str_gsub(lua_State *L) {
  GCstr *src = lib_checkstr(L, 1);
  GCstr *p = lib_checkstr(L, 2);
  TValue *repl = lib_arg(L, 3);
  int tr = repl->tt;
  int64_t max_s = ttisnil(lib_arg(L, 4)) ? (int64_t)src->len + 1 : lib_checkint(L, 4);
  int anchor = (p->len > 0 && str_data(p)[0] == '^');
  int64_t n = 0;
  MatchState ms;
  SBuf b; sbuf_init(&b);
  if (!(tr == T_NUMBER || tr == T_STRING || tr == T_FUNCTION || tr == T_TABLE)) err_argtype(L, 3, "string/function/table");
  const char *s = str_data(src);
  const char *pd = str_data(p); size_t lp = p->len;
  if (anchor) { pd++; lp--; }
  ms.L = L; ms.src_init = s; ms.src_end = s + src->len; ms.p_end = pd + lp;
  while (n < max_s) {
    const char *e;
    ms.level = 0; ms.depth = 0;
    e = do_match(&ms, s, pd);
    if (e) { n++; add_value(&ms, &b, s, e, repl); }
    if (e && e > s) s = e;
    else if (s < ms.src_end) sbuf_putc(&b, *s++);
    else break;
    if (anchor) break;
  }
  sbuf_putmem(&b, s, ms.src_end - s);
  vm_pushstr(L, sbuf_tostr(&b));
  sbuf_free(&b);
  vm_pushnum(L, (double)n);
  return 2;
}

/* ---- format ---- */
static void addquoted(SBuf *b, GCstr *s) {
  const unsigned char *p = (const unsigned char *)str_data(s);
  size_t l = s->len;
  sbuf_putc(b, '"');
  for (size_t i = 0; i < l; i++) {
    unsigned char c = p[i];
    if (c == '"' || c == '\\') { sbuf_putc(b, '\\'); sbuf_putc(b, c); }
    else if (c == '\n') { sbuf_putc(b, '\\'); sbuf_putc(b, '\n'); }
    else if (c < 32 || c == 127) {
      char tmp[8];
      if (i + 1 < l && isdigit(p[i + 1])) snprintf(tmp, sizeof(tmp), "\\%03d", c);
      else snprintf(tmp, sizeof(tmp), "\\%d", c);
      sbuf_puts(b, tmp);
    } else sbuf_putc(b, c);
  }
  sbuf_putc(b, '"');
}

static uint64_t num2uint64(double n) {
  if (n < 0) return (uint64_t)num2int64(n);
  if (n < 18446744073709551616.0) return (uint64_t)n;
  return (uint64_t)fmod(n, 18446744073709551616.0);
}

static int str_format(lua_State *L) {
  int arg = 1;
  GCstr *fs = lib_checkstr(L, 1);
  const char *strfrmt = str_data(fs), *strfrmt_end = strfrmt + fs->len;
  SBuf b; sbuf_init(&b);
  int top = lib_nargs(L);
  while (strfrmt < strfrmt_end) {
    if (*strfrmt != '%') { sbuf_putc(&b, *strfrmt++); continue; }
    if (*++strfrmt == '%') { sbuf_putc(&b, *strfrmt++); continue; }
    /* parse format spec */
    char form[32]; char *f = form;
    const char *start = strfrmt - 1;
    *f++ = '%';
    while (*strfrmt != '\0' && strchr("-+ #0", *strfrmt) != NULL) *f++ = *strfrmt++;
    { int nd = 0; while (isdigit((unsigned char)*strfrmt) && nd < 2) { *f++ = *strfrmt++; nd++; } }
    if (*strfrmt == '.') {
      *f++ = *strfrmt++;
      int nd = 0; while (isdigit((unsigned char)*strfrmt) && nd < 2) { *f++ = *strfrmt++; nd++; }
    }
    if (isdigit((unsigned char)*strfrmt) || strfrmt >= strfrmt_end) {
      char opt[64]; size_t ol = strfrmt - start + (strfrmt < strfrmt_end ? 1 : 0);
      if (ol > 60) ol = 60;
      memcpy(opt, start, ol); opt[ol] = 0;
      sbuf_free(&b);
      err_msg(L, "invalid option '%s' to 'format'", opt);
    }
    char conv = *strfrmt++;
    *f = '\0';
    char buf[512];
    if (++arg > top && conv != '%') {
      if (strchr("cdiouxXeEfFgGaAqsp", conv)) { sbuf_free(&b); err_arg(L, arg, "value expected"); }
    }
    switch (conv) {
    case 'c': {
      int32_t c = lib_checkint(L, arg);
      strcpy(f, "c");
      snprintf(buf, sizeof(buf), form, (int)(unsigned char)c);
      sbuf_puts(&b, buf);
      break;
    }
    case 'd': case 'i': {
      int64_t n = lib_checkint64(L, arg);
      strcpy(f, "lld");
      snprintf(buf, sizeof(buf), form, (long long)n);
      sbuf_puts(&b, buf);
      break;
    }
    case 'o': case 'u': case 'x': case 'X': {
      double d = lib_checknum(L, arg);
      uint64_t n = num2uint64(d);
      f[0] = 'l'; f[1] = 'l'; f[2] = conv; f[3] = 0;
      snprintf(buf, sizeof(buf), form, (unsigned long long)n);
      sbuf_puts(&b, buf);
      break;
    }
    case 'e': case 'E': case 'f': case 'F': case 'g': case 'G': {
      double n = lib_checknum(L, arg);
      if (isinf(n) || isnan(n)) {
        /* canonical inf/nan with width handling */
        char tmp[8]; const char *txt = isnan(n) ? "nan" : (n > 0 ? "inf" : "-inf");
        if (isupper((unsigned char)conv)) { strcpy(tmp, txt); for (char *q = tmp; *q; q++) *q = (char)toupper((unsigned char)*q); txt = tmp; }
        /* build %s format with width only */
        char wf[32]; char *w = wf; *w++ = '%';
        for (const char *q = form + 1; *q && strchr("-+ #0", *q); q++) if (*q == '-' || (*q == '+' && n > 0 && !isnan(n))) *w++ = *q;
        { const char *q = form + 1; while (*q && strchr("-+ #0", *q)) q++; while (isdigit((unsigned char)*q)) *w++ = *q++; }
        *w++ = 's'; *w = 0;
        snprintf(buf, sizeof(buf), wf, txt);
        sbuf_puts(&b, buf);
        break;
      }
      f[0] = conv; f[1] = 0;
      snprintf(buf, sizeof(buf), form, n);
      sbuf_puts(&b, buf);
      break;
    }
    case 'a': case 'A': {
      double n = lib_checknum(L, arg);
      f[0] = conv; f[1] = 0;
      snprintf(buf, sizeof(buf), form, n);
      sbuf_puts(&b, buf);
      break;
    }
    case 'q': {
      TValue *o = lib_arg(L, arg);
      GCstr *s = ttisstring(o) ? strV(o) : vm_tostring(L, o);
      addquoted(&b, s);
      break;
    }
    case 's': {
      TValue *o = lib_arg(L, arg);
      GCstr *s = vm_tostring(L, o);
      if (form[1] == 's') { sbuf_putmem(&b, str_data(s), s->len); }
      else {
        strcpy(f, "s");
        int need = snprintf(NULL, 0, form, str_data(s));
        char *tmp = (char *)malloc(need + 1);
        snprintf(tmp, need + 1, form, str_data(s));
        sbuf_putmem(&b, tmp, need);
        free(tmp);
      }
      break;
    }
    case 'p': {
      TValue *o = lib_arg(L, arg);
      const void *ptr = NULL;
      if (iscollectable(o)) ptr = o->u.gc;
      else if (ttislightud(o)) ptr = o->u.p;
      strcpy(f, "s");
      if (ptr) { char pb[32]; snprintf(pb, sizeof(pb), "%p", ptr); snprintf(buf, sizeof(buf), form, pb); }
      else snprintf(buf, sizeof(buf), form, "NULL");
      sbuf_puts(&b, buf);
      break;
    }
    default: {
      char opt[64]; size_t ol = strfrmt - start;
      if (ol > 60) ol = 60;
      memcpy(opt, start, ol); opt[ol] = 0;
      sbuf_free(&b);
      err_msg(L, "invalid option '%s' to 'format'", opt);
    }
    }
  }
  vm_pushstr(L, sbuf_tostr(&b));
  sbuf_free(&b);
  return 1;
}

static int str_dump(lua_State *L) { return lib_string_dump(L); }

void lib_open_string(lua_State *L) {
  Table *t = lib_newmodule(L, "string");
  lib_register(L, t, "len", str_len, 0);
  lib_register(L, t, "byte", str_byte, 76);
  lib_register(L, t, "char", str_char, 77);
  lib_register(L, t, "sub", str_sub, 78);
  lib_register(L, t, "rep", str_rep, 79);
  lib_register(L, t, "reverse", str_reverse, 80);
  lib_register(L, t, "lower", str_lower, 81);
  lib_register(L, t, "upper", str_upper, 82);
  lib_register(L, t, "dump", str_dump, 83);
  lib_register(L, t, "find", str_find, 84);
  lib_register(L, t, "match", str_match, 85);
  lib_register(L, t, "gmatch", str_gmatch, 87);
  lib_register(L, t, "gsub", str_gsub, 88);
  lib_register(L, t, "format", str_format, 89);
  /* string metatable */
  Table *mt = tab_new(0, 2);
  TValue v; settabV(&v, t);
  lib_setfield(L, mt, "__index", &v);
  G.strmt = mt;
}
