/* ---- pattern matching ---- */
#define MAXCAPTURES 32
#define CAP_UNFINISHED (-1)
#define CAP_POSITION (-2)
#define L_ESC '%'

typedef struct MatchState {
  const char *src_init, *src_end;
  const char *p_end;
  lua_State *L;
  int level;
  int depth;
  struct { const char *init; ptrdiff_t len; } capture[MAXCAPTURES];
} MatchState;

static int check_capture(MatchState *ms, int l) {
  l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNFINISHED) err_msg(ms->L, "invalid capture index");
  return l;
}
static int capture_to_close(MatchState *ms) {
  int level = ms->level;
  for (level--; level >= 0; level--) if (ms->capture[level].len == CAP_UNFINISHED) return level;
  err_msg(ms->L, "invalid pattern capture");
  return 0;
}
static const char *classEnd(MatchState *ms, const char *p) {
  switch (*p++) {
  case L_ESC:
    if (p == ms->p_end) err_msg(ms->L, "malformed pattern (ends with '%')");
    return p + 1;
  case '[':
    if (*p == '^') p++;
    do {
      if (p == ms->p_end) err_msg(ms->L, "malformed pattern (missing ']')");
      if (*(p++) == L_ESC && p < ms->p_end) p++;
    } while (*p != ']');
    return p + 1;
  default: return p;
  }
}
static int match_class(int c, int cl) {
  int res;
  switch (tolower(cl)) {
  case 'a': res = isalpha(c); break;
  case 'c': res = iscntrl(c); break;
  case 'd': res = isdigit(c); break;
  case 'g': res = isgraph(c); break;
  case 'l': res = islower(c); break;
  case 'p': res = ispunct(c); break;
