}

static int pkg_module(lua_State *L) {
  GCstr *modname = lib_checkstr(L, 1);
  Table *pkg = get_pkg(L);
  Table *loaded = tabV(tab_getstr(pkg, str_newz("loaded")));
  const TValue *mv = tab_getstr(loaded, modname);
  Table *mod;
  if (ttistable(mv)) mod = tabV(mv);
  else {
    /* create via globals, following dotted names */
    Table *cur = G.globals;
    const char *s = str_data(modname);
    for (;;) {
      const char *dot = strchr(s, '.');
      GCstr *part = dot ? str_new(s, dot - s) : str_newz(s);
      const TValue *f = tab_getstr(cur, part);
      Table *next;
      if (ttisnil(f)) { next = tab_new(0, 0); TValue v; settabV(&v, next); copyTV(tab_setstr(L, cur, part), &v); }
      else if (ttistable(f)) next = tabV(f);
      else { err_msg(L, "name conflict for module '%s'", str_data(modname)); return 0; }
      cur = next;
      if (!dot) break;
      s = dot + 1;
    }
    mod = cur;
    TValue v; settabV(&v, mod);
    copyTV(tab_setstr(L, loaded, modname), &v);
  }
  if (ttisnil(tab_getstr(mod, str_newz("_NAME")))) {
    TValue v; settabV(&v, mod); lib_setfield(L, mod, "_M", &v);
    lib_setfieldstr(L, mod, "_NAME", str_data(modname));
    const char *dot = strrchr(str_data(modname), '.');
    if (dot) { GCstr *pk = str_new(str_data(modname), dot - str_data(modname) + 1); TValue pv; setstrV(&pv, pk); lib_setfield(L, mod, "_PACKAGE", &pv); }
    else lib_setfieldstr(L, mod, "_PACKAGE", "");
  }
  /* set env of caller */
  CallInfo *caller = L->ci - 1;
  if (caller > L->cibase && !caller->isC && caller->cl) caller->cl->env = mod;
  else err_msg(L, "'module' not called from a Lua function");
  /* call options */
  int n = lib_nargs(L);
  for (int i = 2; i <= n; i++) {
    TValue *fb = L->top;
    copyTV(L->top++, lib_arg(L, i));
    vm_pushtab(L, mod);
    vm_call(L, fb, 0);
  }
  return 0;
}

void lib_package_ignore_env(int v) { ignore_env = v; }

void lib_open_package(lua_State *L) {
  Table *t = tab_new(0, 16);
  pkg_table = t;
  TValue v; settabV(&v, t);
  lib_setfield(L, G.globals, "package", &v);
  Table *loaded = tab_new(0, 16);
  settabV(&v, loaded); lib_setfield(L, t, "loaded", &v);
  lib_setfield(L, loaded, "package", &(TValue){ .u.gc = (GCobj *)t, .tt = T_TABLE });
  settabV(&v, G.globals); lib_setfield(L, loaded, "_G", &v);
  Table *preload = tab_new(0, 8);
  settabV(&v, preload); lib_setfield(L, t, "preload", &v);
  Table *loaders = tab_new(4, 0);
  settabV(&v, loaders); lib_setfield(L, t, "loaders", &v);
  Closure *c;
  c = lib_register(L, NULL, "loader_preload", loader_preload, 0); setfuncV(&v, c); copyTV(tab_setint(L, loaders, 1), &v);
  c = lib_register(L, NULL, "loader_lua", loader_lua, 0); setfuncV(&v, c); copyTV(tab_setint(L, loaders, 2), &v);
  c = lib_register(L, NULL, "loader_c", loader_c, 0); setfuncV(&v, c); copyTV(tab_setint(L, loaders, 3), &v);
  c = lib_register(L, NULL, "loader_croot", loader_croot, 0); setfuncV(&v, c); copyTV(tab_setint(L, loaders, 4), &v);
  const char *path = ignore_env ? NULL : getenv("LUA_PATH");
  if (path) {
    GCstr *p = gsub_str(path, ";;", ";" LUA_PATH_DEFAULT ";");
    setstrV(&v, p); lib_setfield(L, t, "path", &v);
  } else lib_setfieldstr(L, t, "path", LUA_PATH_DEFAULT);
  const char *cpath = ignore_env ? NULL : getenv("LUA_CPATH");
  if (cpath) {
    GCstr *p = gsub_str(cpath, ";;", ";" LUA_CPATH_DEFAULT ";");
    setstrV(&v, p); lib_setfield(L, t, "cpath", &v);
  } else lib_setfieldstr(L, t, "cpath", LUA_CPATH_DEFAULT);
  lib_setfieldstr(L, t, "config", "/\n;\n?\n!\n-\n");
  lib_register(L, t, "loadlib", pkg_loadlib, 0);
  lib_register(L, t, "searchpath", pkg_searchpath, 0);
  lib_register(L, t, "seeall", pkg_seeall, 0);
  lib_register(L, G.globals, "module", pkg_module, 0);
  lib_register(L, G.globals, "require", lib_require, 0);
}
