static int incomplete(lua_State *L, int status) {
  if (status == LUA_ERRSYNTAX) {
    TValue *e = L->top - 1;
    if (ttisstring(e)) {
      const char *msg = str_data(strV(e));
      size_t lmsg = strV(e)->len;
      const char *tp = "'<eof>'";
      size_t ltp = strlen(tp);
      if (lmsg >= ltp && strcmp(msg + lmsg - ltp, tp) == 0) { L->top--; return 1; }
