  if (fgets(buf, sizeof(buf), stdin) == NULL) return 0;
  size_t l = strlen(buf);
  if (l > 0 && buf[l - 1] == '\n') buf[l - 1] = '\0', l--;
  if (firstline && buf[0] == '=') { sbuf_puts(sb, "return "); sbuf_puts(sb, buf + 1); }
  else sbuf_putmem(sb, buf, l);
