/* ---- arg handling ---- */
#define FLAGS_INTERACTIVE 1
#define FLAGS_VERSION 2
#define FLAGS_EXEC 4
#define FLAGS_OPTION 8
#define FLAGS_NOENV 16

static int collectargs(char **argv, int *flags) {
  int i;
  for (i = 1; argv[i] != NULL; i++) {
    if (argv[i][0] != '-') return i;
    switch (argv[i][1]) {
    case '-':
      if (argv[i][2] != '\0') return -1;
      return argv[i + 1] != NULL ? i + 1 : 0;
    case '\0': return i;
    case 'i': if (argv[i][2] != '\0') return -1; *flags |= FLAGS_INTERACTIVE; /* fallthrough */
    case 'v': if (argv[i][2] != '\0') return -1; *flags |= FLAGS_VERSION; break;
    case 'e': *flags |= FLAGS_EXEC; /* fallthrough */
    case 'j': *flags |= FLAGS_OPTION; /* fallthrough */
    case 'l':
      if (argv[i][2] == '\0') {
        i++;
        if (argv[i] == NULL) return -1;
      }
      break;
    case 'O': break;
    case 'b':
      if (*flags) return -1;
      *flags |= FLAGS_EXEC;
      return 0;
    case 'E': *flags |= FLAGS_NOENV; break;
    default: return -1;
    }
  }
  return 0;
}

static int runargs(lua_State *L, char **argv, int n) {
  for (int i = 1; i < n; i++) {
    if (argv[i] == NULL) continue;
    switch (argv[i][1]) {
    case 'e': {
      const char *chunk = argv[i] + 2;
      if (*chunk == '\0') chunk = argv[++i];
      if (dostring(L, chunk, "=(command line)") != LUA_OK) return 1;
      break;
    }
    case 'l': {
      const char *fname = argv[i] + 2;
      if (*fname == '\0') fname = argv[++i];
      if (dolibrary(L, fname) != LUA_OK) return 1;
      break;
    }
    case 'j': {
      const char *cmd = argv[i] + 2;
      if (*cmd == '\0') cmd = argv[++i];
      if (strcmp(cmd, "on") == 0 || strcmp(cmd, "off") == 0 || strcmp(cmd, "flush") == 0) break;
      {
        char opt[64]; const char *eq = strchr(cmd, '=');
        size_t l = eq ? (size_t)(eq - cmd) : strlen(cmd);
        if (l > 60) l = 60;
        memcpy(opt, cmd, l); opt[l] = 0;
        if (strcmp(opt, "on") == 0 || strcmp(opt, "off") == 0 || strcmp(opt, "flush") == 0) break;
      }
      l_message(progname, "unknown luaJIT command or jit.* modules not installed");
      return 1;
    }
    case 'O': break;
    case 'b': {
      l_message(progname, "unknown luaJIT command or jit.* modules not installed");
      return 1;
    }
    default: break;
    }
  }
  return 0;
}

static int handle_luainit(lua_State *L) {
  const char *init = getenv("LUA_INIT");
  if (init == NULL) return LUA_OK;
  if (init[0] == '@') return dofile_main(L, init + 1);
  return dostring(L, init, "=LUA_INIT");
}

static void real_main(void) {
  int argc = g_argc; char **argv = g_argv;
  lex_init_keywords();
  vm_init();
  lua_State *L = G.mainthread;
  int flags = 0;
  int script = collectargs(argv, &flags);
  if (argv[0] && argv[0][0]) progname = argv[0];
  if (script < 0) { print_usage(); g_exitcode = 1; return; }
  if (flags & FLAGS_NOENV) lib_package_ignore_env(1);
  lib_openlibs(L);
  tb_closure = func_newC(traceback_handler, 0, G.globals);
  { TValue v; setfuncV(&v, tb_closure); lib_setfield(L, G.registry, "__traceback", &v); }
  int argn = script > 0 ? script : argc;
  createargtable(L, argv, argc, argn);
  if (flags & FLAGS_VERSION) print_version();
  if (!(flags & FLAGS_NOENV)) {
    if (handle_luainit(L) != LUA_OK) { g_exitcode = 1; return; }
  }
  if (runargs(L, argv, argn)) { g_exitcode = 1; return; }
  if (script > 0) {
    if (handle_script(L, argv + script) != LUA_OK) { g_exitcode = 1; return; }
  }
  if (flags & FLAGS_INTERACTIVE) {
    print_jit_status(L);
    dotty(L);
  } else if (script == 0 && !(flags & (FLAGS_EXEC | FLAGS_VERSION))) {
    if (isatty(0)) {
      print_version();
      print_jit_status(L);
      dotty(L);
    } else {
      if (dofile_main(L, NULL) != LUA_OK) { g_exitcode = 1; return; }
    }
  }
  g_exitcode = 0;
}

static ucontext_t main_ctx, big_ctx;
static void big_entry(void) {
  real_main();
  fflush(stdout);
  swapcontext(&big_ctx, &main_ctx);
}

int main(int argc, char **argv) {
  g_argc = argc; g_argv = argv;
  size_t sz = 1024u * 1024 * 1024;
  void *stk = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
  if (stk == MAP_FAILED) { real_main(); fflush(stdout); return g_exitcode; }
  main_cstack_base = (char *)stk;
  getcontext(&big_ctx);
  big_ctx.uc_stack.ss_sp = stk;
  big_ctx.uc_stack.ss_size = sz;
  big_ctx.uc_link = &main_ctx;
  makecontext(&big_ctx, big_entry, 0);
  swapcontext(&main_ctx, &big_ctx);
  fflush(stdout);
  return g_exitcode;
}
