  x ^= x >> 33; x *= 0xff51afd7ed558ccdULL; x ^= x >> 33; x *= 0xc4ceb9fe1a85ec53ULL; x ^= x >> 33;
  return (uint32_t)x;
}
static inline uint32_t rol32(uint32_t x, int n) { return (x << n) | (x >> (32 - n)); }
static inline uint32_t hashrot(uint32_t lo, uint32_t hi) {
  lo ^= hi; hi = rol32(hi, 14);
  lo -= hi; hi = rol32(hi, 5);
  hi ^= lo; hi -= rol32(lo, 13);
  return hi;
}

static Node *mainposition(const Table *t, const TValue *key) {
  uint32_t h;
  switch (key->tt) {
  case T_NUMBER: {
    double n = numV(key);
    uint64_t bits;
    if (n == 0) n = 0;
    memcpy(&bits, &n, 8);
    h = hashrot((uint32_t)bits, (uint32_t)(bits >> 32) << 1);
    break;
  }
  case T_STRING: h = strV(key)->hash; break;
  case T_BOOLEAN: h = (uint32_t)boolV(key); break;
  default: { uint32_t p = (uint32_t)(uintptr_t)key->u.p; h = hashrot(p, p + 0x40000000u); break; }
  }
  return &t->node[h & hmask(t)];
}

static inline int num2intkey(double n, int64_t *k) {
  if (n >= -9.2233720368547758e18 && n < 9.2233720368547758e18) {
    int64_t i = (int64_t)n;
    if ((double)i == n) { *k = i; return 1; }
  }
  return 0;
}

static uint32_t fls32(uint32_t x) { return 31 - (uint32_t)__builtin_clz(x); }
static uint32_t hsize2hbits(uint32_t s) { return s ? (s == 1 ? 1 : 1 + fls32(s - 1)) : 0; }

static void setnodevector(Table *t, uint32_t hbits) {
  if (hbits == 0) { t->node = dummynode; t->lsizenode = 0; t->lastfree = dummynode; return; }
  uint32_t size = 1u << hbits;
  t->node = (Node *)mem_alloc(sizeof(Node) * size);
  for (uint32_t i = 0; i < size; i++) { setnilV(&t->node[i].val); setnilV(&t->node[i].key); t->node[i].next = NULL; }
  t->lsizenode = (uint8_t)hbits;
  t->lastfree = t->node + size;
}

Table *tab_new(uint32_t asize, uint32_t hsize) {
  Table *t = (Table *)mem_alloc(sizeof(Table));
  t->flags = 0; t->lsizenode = 0; t->asize = 0; t->array = NULL;
  t->node = dummynode; t->lastfree = dummynode; t->metatable = NULL; t->gclist = NULL;
  gc_link((GCobj *)t, T_TABLE);
  if (asize > 0) {
    t->array = (TValue *)mem_alloc(sizeof(TValue) * asize);
    for (uint32_t i = 0; i < asize; i++) setnilV(&t->array[i]);
    t->asize = asize;
  }
  if (hsize > 0) setnodevector(t, hsize2hbits(hsize));
  return t;
}

void tab_free(Table *t) {
  if (!isdummy(t)) mem_free(t->node, sizeof(Node) * (1u << t->lsizenode));
  if (t->array) mem_free(t->array, sizeof(TValue) * t->asize);
  mem_free(t, sizeof(Table));
}

static TValue *newkey(lua_State *L, Table *t, const TValue *key);

/* resize to asize array slots and 2^hbits hash nodes */
static void resize_hbits(lua_State *L, Table *t, uint32_t nasize, uint32_t hbits) {
  uint32_t oldasize = t->asize;
  uint32_t oldhsize = sizenode(t);
  Node *oldnode = t->node;
  TValue *oldarray = t->array;
  if (nasize != oldasize) {
    TValue *na = nasize ? (TValue *)mem_alloc(sizeof(TValue) * nasize) : NULL;
    uint32_t n = nasize < oldasize ? nasize : oldasize;
    for (uint32_t i = 0; i < n; i++) copyTV(&na[i], &oldarray[i]);
    for (uint32_t i = n; i < nasize; i++) setnilV(&na[i]);
    t->array = na;
    t->asize = nasize;
  }
  setnodevector(t, hbits);
  if (nasize < oldasize) {
    for (uint32_t i = nasize; i < oldasize; i++) {
      if (!ttisnil(&oldarray[i])) {
        TValue k; setnumV(&k, (double)i);
        copyTV(tab_set(L, t, &k), &oldarray[i]);
      }
    }
  }
  if (nasize != oldasize && oldarray) mem_free(oldarray, sizeof(TValue) * oldasize);
  for (uint32_t i = 0; i < oldhsize; i++) {
    Node *old = oldnode + i;
    if (!ttisnil(&old->val)) copyTV(tab_set(L, t, &old->key), &old->val);
  }
  if (oldhsize) mem_free(oldnode, sizeof(Node) * oldhsize);
}

void tab_resize(lua_State *L, Table *t, uint32_t nasize, uint32_t nhsize) {
  resize_hbits(L, t, nasize, hsize2hbits(nhsize));
}

void tab_reasize(lua_State *L, Table *t, uint32_t nasize) {
  if (nasize > t->asize) resize_hbits(L, t, nasize, isdummy(t) ? 0 : t->lsizenode);
}

static uint32_t countint(const TValue *key, uint32_t *bins) {
  if (ttisnumber(key)) {
    double nk = numV(key);
    int64_t k;
    if (num2intkey(nk, &k) && k >= 0 && (uint64_t)k < MAX_ASIZE) {
      bins[k > 2 ? fls32((uint32_t)(k - 1)) : 0]++;
      return 1;
    }
  }
  return 0;
}

static uint32_t countarray(const Table *t, uint32_t *bins) {
  uint32_t na, b, i;
  if (t->asize == 0) return 0;
  for (na = i = b = 0; b < 28; b++) {
    uint32_t n, top = 2u << b;
    if (top >= t->asize) { top = t->asize - 1; if (i > top) break; }
    for (n = 0; i <= top; i++) if (!ttisnil(&t->array[i])) n++;
    bins[b] += n;
    na += n;
  }
  return na;
}

static uint32_t counthash(const Table *t, uint32_t *bins, uint32_t *narray) {
  uint32_t total = 0, na = 0;
  uint32_t ns = sizenode(t);
  for (uint32_t i = 0; i < ns; i++) {
    Node *n = &t->node[i];
    if (!ttisnil(&n->val)) { na += countint(&n->key, bins); total++; }
  }
  *narray += na;
  return total;
}

static uint32_t bestasize(uint32_t bins[], uint32_t *narray) {
  uint32_t b, sum, na = 0, sz = 0, nn = *narray;
  for (b = 0, sum = 0; 2 * nn > (1u << b) && sum != nn; b++)
    if (bins[b] > 0 && 2 * (sum += bins[b]) > (1u << b)) { sz = (2u << b) + 1; na = sum; }
  *narray = sz;
  return na;
}

static void rehash(lua_State *L, Table *t, const TValue *ek) {
  uint32_t bins[32];
  uint32_t total, asize, na;
  memset(bins, 0, sizeof(bins));
  asize = countarray(t, bins);
  total = 1 + asize;
  total += counthash(t, bins, &asize);
  asize += countint(ek, bins);
  na = bestasize(bins, &asize);
  total -= na;
  resize_hbits(L, t, asize, hsize2hbits(total));
}

static Node *getfreepos(Table *t) {
  while (t->lastfree > t->node) {
    t->lastfree--;
    if (ttisnil(&t->lastfree->key)) return t->lastfree;
  }
  return NULL;
}

static const TValue *getgeneric(const Table *t, const TValue *key) {
  Node *n = mainposition(t, key);
  do {
    if (lua_rawequal(&n->key, key)) return &n->val;
    n = n->next;
  } while (n);
  return NILOBJ;
}

static TValue *newkey(lua_State *L, Table *t, const TValue *key) {
  Node *mp = mainposition(t, key);
  if (!ttisnil(&mp->val) || isdummy(t)) {
    Node *othern;
    Node *n = getfreepos(t);
    if (n == NULL) {
      rehash(L, t, key);
      return tab_set(L, t, key);
    }
    othern = mainposition(t, &mp->key);
    if (othern != mp) {
      while (othern->next != mp) othern = othern->next;
      othern->next = n;
      *n = *mp;
      mp->next = NULL;
      setnilV(&mp->val);
    } else {
      n->next = mp->next;
      mp->next = n;
      mp = n;
    }
  }
  copyTV(&mp->key, key);
  if (ttisnumber(&mp->key) && numV(&mp->key) == 0) setnumV(&mp->key, 0);
  setnilV(&mp->val);
  return &mp->val;
}

const TValue *tab_getint(Table *t, int64_t key) {
  if ((uint64_t)key < t->asize) return &t->array[key];
  if (isdummy(t)) return NILOBJ;
  {
    TValue k; setnumV(&k, (double)key);
    Node *n = mainposition(t, &k);
    do {
      if (ttisnumber(&n->key) && numV(&n->key) == (double)key) return &n->val;
      n = n->next;
    } while (n);
    return NILOBJ;
  }
}

const TValue *tab_getstr(Table *t, GCstr *key) {
  if (isdummy(t)) return NILOBJ;
  Node *n = &t->node[key->hash & hmask(t)];
  do {
    if (ttisstring(&n->key) && strV(&n->key) == key) return &n->val;
    n = n->next;
  } while (n);
  return NILOBJ;
}

const TValue *tab_getnum(Table *t, double n) {
  int64_t k;
  if (num2intkey(n, &k)) return tab_getint(t, k);
  if (isnan(n) || isdummy(t)) return NILOBJ;
  { TValue key; setnumV(&key, n); return getgeneric(t, &key); }
}

const TValue *tab_get(Table *t, const TValue *key) {
  switch (key->tt) {
  case T_NIL: return NILOBJ;
  case T_STRING: return tab_getstr(t, strV(key));
  case T_NUMBER: return tab_getnum(t, numV(key));
  default: if (isdummy(t)) return NILOBJ; return getgeneric(t, key);
  }
}

TValue *tab_set(lua_State *L, Table *t, const TValue *key) {
  const TValue *p;
  t->flags = 0;
  if (ttisnumber(key)) {
    double n = numV(key);
    int64_t k;
    if (num2intkey(n, &k)) {
      if ((uint64_t)k < t->asize) return &t->array[k];
      p = tab_getint(t, k);
      if (p != NILOBJ) return (TValue *)p;
      { TValue nk; setnumV(&nk, (double)k); return newkey(L, t, &nk); }
    }
    if (isnan(n)) err_run(L, "table index is NaN");
  } else if (ttisnil(key)) {
    err_run(L, "table index is nil");
  }
  p = tab_get(t, key);
  if (p != NILOBJ) return (TValue *)p;
  return newkey(L, t, key);
}

TValue *tab_setstr(lua_State *L, Table *t, GCstr *key) {
  const TValue *p = tab_getstr(t, key);
  t->flags = 0;
  if (p != NILOBJ) return (TValue *)p;
  { TValue k; setstrV(&k, key); return newkey(L, t, &k); }
}

TValue *tab_setint(lua_State *L, Table *t, int64_t key) {
  const TValue *p = tab_getint(t, key);
  if (p != NILOBJ) return (TValue *)p;
  { TValue k; setnumV(&k, (double)key); return newkey(L, t, &k); }
}

int tab_next(lua_State *L, Table *t, TValue *key) {
  uint32_t i;
  (void)L;
  if (ttisnil(key)) i = 0;
  else if (ttisnumber(key)) {
    int64_t k;
    if (num2intkey(numV(key), &k) && (uint64_t)k < t->asize) i = (uint32_t)k + 1;
    else goto hashpart;
  } else {
    Node *n;
  hashpart:
    if (isdummy(t)) return -1;
    n = mainposition(t, key);
    do {
      if (lua_rawequal(&n->key, key)) break;
      n = n->next;
    } while (n);
    if (n == NULL) return -1;
    i = (uint32_t)(n - t->node) + 1 + t->asize;
  }
  for (; i < t->asize; i++) {
    if (!ttisnil(&t->array[i])) {
      setnumV(&key[0], (double)i);
      copyTV(&key[1], &t->array[i]);
      return 1;
    }
  }
  {
    uint32_t ns = sizenode(t);
    for (i -= t->asize; i < ns; i++) {
      if (!ttisnil(&t->node[i].val)) {
        copyTV(&key[0], &t->node[i].key);
        copyTV(&key[1], &t->node[i].val);
        return 1;
      }
    }
  }
  return 0;
}

static uint32_t unbound_search(Table *t, uint32_t j) {
  uint32_t i = j;
  j++;
  while (!ttisnil(tab_getint(t, j))) {
    i = j;
    if (j > 0x7fffffffu / 2) {
      i = 1;
      while (!ttisnil(tab_getint(t, i))) i++;
      return i - 1;
    }
    j *= 2;
  }
  while (j - i > 1) {
    uint32_t m = (i + j) / 2;
    if (ttisnil(tab_getint(t, m))) j = m; else i = m;
  }
  return i;
}

uint32_t tab_len(Table *t) {
  uint32_t hi = t->asize;
  if (hi) hi--;
  if (hi > 0 && ttisnil(&t->array[hi])) {
    uint32_t lo = 0;
    while (hi - lo > 1) {
      uint32_t mid = (lo + hi) >> 1;
      if (ttisnil(&t->array[mid])) hi = mid; else lo = mid;
    }
    return lo;
  }
  return isdummy(t) ? hi : unbound_search(t, hi);
}

int lua_rawequal(const TValue *a, const TValue *b) {
  if (a->tt != b->tt) return 0;
  switch (a->tt) {
  case T_NIL: return 1;
  case T_BOOLEAN: return boolV(a) == boolV(b);
  case T_NUMBER: return numV(a) == numV(b);
  case T_LIGHTUD: return a->u.p == b->u.p;
  default: return a->u.gc == b->u.gc;
  }
}
