p='/workspace/src/parse.c'
s=open(p).read()
old="""  case '{': {
    el_push(fs, &el, expr(ls, fs));  /* table constructor */
    break;
  }"""
new="""  case '{': {
    el_push(fs, &el, parse_table(ls, fs));  /* table constructor */
    break;
  }"""
assert old in s
s=s.replace(old,new)
# need forward decl of parse_table before parse_args
s=s.replace("""static Expr *parse_args(LexState *ls, FuncState *fs, Expr *fn, GCstr *mname, int line_unused) {""","""static Expr *parse_table(LexState *ls, FuncState *fs);
static Expr *parse_args(LexState *ls, FuncState *fs, Expr *fn, GCstr *mname, int line_unused) {""")
open(p,'w').write(s)
EOF
./build.sh 2>&1 | grep -E "error|warning"; ./cmp.sh /tmp/t37.lua

output.arguments:
{"command":"cd /workspace && python3 - <<'EOF'
p='/workspace/src/gc.c'
s=open(p).read()
s=s.replace("""void gc_check(lua_State *L) {
  if (G.totalbytes >= G.gcthreshold && !G.gcstopped && !G.parsing) gc_fullcollect(L);
}""","""static int gcstress = -1;
void gc_check(lua_State *L) {
  if (gcstress < 0) gcstress = getenv("LJ_GCSTRESS") != NULL;
  if ((gcstress || G.totalbytes >= G.gcthreshold) && !G.gcstopped && !G.parsing) gc_fullcollect(L);
}""")
open(p,'w').write(s)
EOF
./build.sh 2>&1 | grep -E "error|warning"; for f in tests/prog/p1.lua tests/prog/p2.lua tests/prog/p3.lua tests/prog/p5.lua tests/prog/p6.lua tests/prog/p7.lua tests/prog/p9.lua tests/prog/p11.lua /tmp/t7.lua /tmp/t22.lua /tmp/t38.lua /tmp/t39.lua /tmp/tb2.lua; do LJ_GCSTRESS=1 timeout 120 ./myluajit $f > /tmp/gs.out 2>&1 < /dev/null; rc=$?; ./myluajit $f > /tmp/ns.out 2>&1 < /dev/null; sed -i -E 's/0x[0-9a-f]+/ADDR/g' /tmp/gs.out /tmp/ns.out; if diff -q /tmp/gs.out /tmp/ns.out >/dev/null; then echo "OK $f"; else echo "GCSTRESS DIFF $f rc=$rc"; diff /tmp/gs.out /tmp/ns.out | head -5; fi; done"}

