output.arguments:
{"command":"cd /workspace && python3 - <<'EOF'
p='/workspace/src/vm.c'
s=open(p).read()
old="""static const char *expr_name(const Expr *e, const char **what) {
  while (e && e->kind == E_PAREN) e = e->u.un.e;
  if (!e) return NULL;"""
new="""static const char *expr_name(const Expr *e, const char **what) {
  while (e && (e->kind == E_PAREN || e->kind == E_AND || e->kind == E_OR)) e = (e->kind == E_PAREN) ? e->u.un.e : e->u.bin.b;
  if (!e) return NULL;"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
./build.sh 2>&1 | grep -E "error|warning"; ./myluajit -e 'print(pcall(loadstring("aaa={}; x=(aaa or aaa)+(aaa and aaa)")))'; sed -i '12d' /tmp/t43.lua; ./cmp.sh /tmp/t43.lua; ./myluajit /tmp/t43.lua 2>&1 | head -4"}

{"command":"cd /workspace && python3 - <<'EOF'
p='/workspace/src/lib_base.c'
s=open(p).read()
old="""  TValue m = *msg;
  if (ttisstring(&m) && level > 0) {
    GCstr *w = vm_where(L, level);
    if (w->len) {
      vm_pushfstring(L, "%s %s", str_data(w), str_data(strV(&m)));
      vm_throw(L, LUA_ERRRUN);
    }
  }"""
new="""  TValue m = *msg;
  if ((ttisstring(&m) || ttisnumber(&m)) && level > 0) {
    GCstr *w = vm_where(L, level);
    GCstr *ms = ttisstring(&m) ? strV(&m) : num2strobj(numV(&m));
    if (w->len) vm_pushfstring(L, "%s %s", str_data(w), str_data(ms));
    else vm_pushstr(L, ms);
    vm_throw(L, LUA_ERRRUN);
  }"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
./build.sh 2>&1 | grep -E "error|warning"; ./myluajit -e 'print(pcall(error, 42)) print(pcall(error, 42, 2)) local ok, e = pcall(error, 42) print(type(e)) print(pcall(error, 42, 0)) local ok2, e2 = pcall(error, 42, 0) print(type(e2))'; ./executable -e 'print(pcall(error, 42)) print(pcall(error, 42, 2)) local ok, e = pcall(error, 42) print(type(e)) print(pcall(error, 42, 0)) local ok2, e2 = pcall(error, 42, 0) print(type(e2))'; sed -i '44s/assert(e == 42)/assert(e == "42")/' /tmp/t43.lua; ./cmp.sh /tmp/t43.lua"}

